INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C1','math',5,1,'u4',2,'함께 변하는 두 양 — 한 줄만 보면 「몇씩 늘어난다」까지지만 두 양을 짝지어 보면 「몇 배·몇 많다」가 보임을 알고, 짝의 규칙으로 100번째 같은 먼 자리 값을 단번에 구하기',ARRAY['6수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C2','math',5,1,'u4',2,'표에서 대응 관계 찾기 — 표를 위아래로 짝지어 읽고, 두 양 사이의 관계를 곱셈(몇 배)이나 덧셈·뺄셈(몇 많다·적다)으로 말하며 모든 짝에서 맞는지 확인하기',ARRAY['6수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C3','math',5,1,'u4',2,'대응 관계의 뜻 — 한 양이 변할 때 다른 양이 그에 따라 하나로 정해지는 관계를 대응 관계라 하고, 하나로 정해지지 않는 두 양(키와 좋아하는 색깔 수)은 대응 관계가 아님을 가려내기',ARRAY['6수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C4','math',5,1,'u4',3,'대응 관계를 식으로 나타내기 — □·△ 같은 기호가 무엇을 가리키는지 먼저 정하고, 말로 한 관계를 □ × 4 = △, □ − 3 = △처럼 식으로 옮기기',ARRAY['6수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C5','math',5,1,'u4',3,'한 관계를 여러 식으로 — □ × 4 = △와 △ ÷ 4 = □, □ − 3 = △와 △ + 3 = □처럼 같은 관계를 반대 방향에서 쓴 식을 알아보고, 잘못 뒤집은 식(□ ÷ 4 = △)을 가려내기',ARRAY['6수04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C6','math',5,1,'u4',4,'식으로 값 구하기 — □를 알면 식에 넣어 △를, △를 알면 되돌리는 셈(곱셈 ↔ 나눗셈, 덧셈 ↔ 뺄셈)으로 □를 구하고, 표에 없는 먼 자리 값도 식으로 답하기',ARRAY['6수04-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C7','math',5,1,'u4',5,'생활 속 대응 관계 — 주변에서 짝을 이루는 두 양을 찾아 식으로 나타내고, 상황이 달라도 관계의 모양이 같으면 식이 하나임(자전거와 바퀴·사람과 눈 → □ × 2 = △)을 알기',ARRAY['6수04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u4-C8','math',5,1,'u4',6,'문제 해결 — 묻는 것과 이어진 정보만 골라 표를 만들고, 두 양의 짝을 식 한 줄로 정리해 값·개수를 구하기(필요 없는 정보 걷어내기)',ARRAY['6수04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X01','math',5,'u4',ARRAY['M5-1-u4-C1','M5-1-u4-C2','M5-1-u4-C3']::text[],'표의 가로 한 줄만 보고 대응 관계를 「몇씩 늘어난다」로만 말하거나, 한 줄 규칙(버스 번호 502, 504, …)을 두 양의 대응 관계로 여긴다','위아래 짝을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X02','math',5,'u4',ARRAY['M5-1-u4-C2','M5-1-u4-C4','M5-1-u4-C6','M5-1-u4-C7']::text[],'곱셈 관계(몇 배)를 덧셈 관계(몇 많다)로, 또는 덧셈 관계를 곱셈 관계로 바꾸어 본다(4배를 「4 많다」로)','배인지 많은지 짝 둘로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X03','math',5,'u4',ARRAY['M5-1-u4-C2','M5-1-u4-C4']::text[],'짝 하나만 맞추어 보고 관계를 정한다 — 첫 짝 1과 4만 보고 「3 많다」처럼 말하고 다른 짝에서 맞는지 확인하지 않는다','모든 짝에서 맞는지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X04','math',5,'u4',ARRAY['M5-1-u4-C2','M5-1-u4-C4','M5-1-u4-C5']::text[],'관계의 방향을 거꾸로 말하거나 □와 △의 자리를 바꾸어 식을 쓴다(「□는 △의 4배」, △ × 4 = □)','누가 누구의 몇 배인지 말로 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X05','math',5,'u4',ARRAY['M5-1-u4-C3','M5-1-u4-C7']::text[],'한 양이 정해져도 다른 양이 하나로 정해지지 않는 두 양을 대응 관계라고 여기거나, 대응 관계를 아니라고 여긴다','하나로 정해지는지 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X06','math',5,'u4',ARRAY['M5-1-u4-C4','M5-1-u4-C6']::text[],'기호가 무엇을 가리키는지 확인하지 않고 아는 수를 엉뚱한 기호 자리에 넣는다(줄 수 48을 □ 자리에)','□와 △가 무엇인지 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X07','math',5,'u4',ARRAY['M5-1-u4-C6']::text[],'△를 알고 □를 구할 때 되돌리는 셈을 하지 않는다 — 곱했으면 나누고, 뺐으면 더해야 하는데 같은 셈을 또 한다','곱셈 ↔ 나눗셈, 덧셈 ↔ 뺄셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X08','math',5,'u4',ARRAY['M5-1-u4-C5']::text[],'같은 관계를 반대 방향에서 쓴 식을 다른 관계로 여기거나, 식을 잘못 뒤집는다(□ × 4 = △를 □ ÷ 4 = △로)','수를 넣어 두 식이 같은 짝을 내는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X09','math',5,'u4',ARRAY['M5-1-u4-C1','M5-1-u4-C6']::text[],'표에 없는 먼 자리 값은 표를 끝까지 이어야 구할 수 있다고 여기거나, 몇씩 더해 갈 때 한 칸 어긋나게 센다','식은 표를 끝없이 늘린 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X10','math',5,'u4',ARRAY['M5-1-u4-C7','M5-1-u4-C8']::text[],'생활 속 두 양에서 한 개에 붙는 수를 잘못 잡는다(사각형의 변 4·곤충 다리 6·1주일 7일·자전거 바퀴 2)','하나에 몇 개씩인지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X11','math',5,'u4',ARRAY['M5-1-u4-C8']::text[],'문제에 나온 수를 모두 셈에 넣는다 — 묻는 것과 이어지지 않은 정보(걸린 시간·포장지 색 수)까지 쓴다','묻는 것과 이어진 수만 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X12','math',5,'u4',ARRAY['M5-1-u4-C1','M5-1-u4-C2','M5-1-u4-C3','M5-1-u4-C4','M5-1-u4-C5','M5-1-u4-C6','M5-1-u4-C7','M5-1-u4-C8']::text[],'한 걸음의 셈(곱셈·나눗셈·덧셈·뺄셈)을 잘못하거나 자리 수를 틀린다','셈을 거꾸로 해 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u4-X13','math',5,'u4',ARRAY['M5-1-u4-C1','M5-1-u4-C2','M5-1-u4-C3','M5-1-u4-C4','M5-1-u4-C5','M5-1-u4-C6','M5-1-u4-C7','M5-1-u4-C8']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 잘못↔바르게, □를 묻는데 △를 답한다','물음의 「아닌·잘못·무엇을」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#1','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C2',1,'mc','auto','우쿨렐레 수와 줄 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],true,'{"seq":1,"concept":"M5-1-u4-C2","difficulty":1,"kind":"mc","stem":"우쿨렐레 수와 줄 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?","options":[{"t":"16","correct":true},{"t":"8","mis":"M5-1-u4-X02"},{"t":"20","mis":"M5-1-u4-X09"},{"t":"15","mis":"M5-1-u4-X12"}],"explanation":["위아래 짝 1과 4를 보면 줄 수는 우쿨렐레 수의 4배예요.","?의 위 칸은 4 — 4 × 4 = 16이에요.","?에 알맞은 수는 16이에요."],"asset":{"type":"numgrid","rows":[["우쿨렐레 수",1,2,3,4,5],["줄 수",4,8,12,null,20]],"name":"대응표","q":[1,4]},"variant_rule":{"alt":[{"stem":"꿀벌 수와 날개 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?","options":[{"t":"20","correct":true},{"t":"9","mis":"M5-1-u4-X02"},{"t":"24","mis":"M5-1-u4-X09"},{"t":"19","mis":"M5-1-u4-X12"}],"explanation":["위아래 짝 1과 4를 보면 날개 수는 꿀벌 수의 4배예요.","?의 위 칸은 5 — 5 × 4 = 20이에요.","?에 알맞은 수는 20이에요."],"asset":{"type":"numgrid","rows":[["꿀벌 수",1,2,3,4,5],["날개 수",4,8,12,16,null]],"name":"대응표","q":[1,5]}},{"stem":"피자 수와 조각 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?","options":[{"t":"24","correct":true},{"t":"11","mis":"M5-1-u4-X02"},{"t":"32","mis":"M5-1-u4-X09"},{"t":"23","mis":"M5-1-u4-X12"}],"explanation":["위아래 짝 1과 8을 보면 조각 수는 피자 수의 8배예요.","?의 위 칸은 3 — 3 × 8 = 24예요.","?에 알맞은 수는 24예요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4,5],["조각 수",8,16,null,32,40]],"name":"대응표","q":[1,3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#2','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C1',1,'sa','auto','우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 6개의 줄은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C1","difficulty":1,"kind":"sa","stem":"우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 6개의 줄은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24","24개"],"explanation":["우쿨렐레가 하나 늘 때마다 줄 수는 4씩 늘어요 — 줄 수는 우쿨렐레 수의 4배예요.","6 × 4 = 24예요.","우쿨렐레 6개의 줄은 24개예요."],"variant_rule":{"alt":[{"stem":"꿀벌 한 마리의 다리는 6개예요. 꿀벌 5마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["30","30개"],"explanation":["꿀벌이 하나 늘 때마다 다리 수는 6씩 늘어요 — 다리 수는 꿀벌 수의 6배예요.","5 × 6 = 30이에요.","꿀벌 5마리의 다리는 30개예요."]},{"stem":"피자 한 판은 8조각이에요. 피자 5판은 모두 몇 조각인가요? 숫자로 쓰세요.","answer":["40","40조각"],"explanation":["피자가 하나 늘 때마다 조각 수는 8씩 늘어요 — 조각 수는 피자 수의 8배예요.","5 × 8 = 40이에요.","피자 5판의 조각은 40조각이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#3','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C2',1,'sa','auto','원호 나이와 동생 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u4-C2","difficulty":1,"kind":"sa","stem":"원호 나이와 동생 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["위아래 짝 12와 9를 보면 동생 나이는 원호 나이보다 3 적어요.","?의 위 칸은 15 — 15 − 3 = 12예요.","?에 알맞은 수는 12예요."],"asset":{"type":"numgrid","rows":[["원호 나이",12,13,14,15,16],["동생 나이",9,10,11,null,13]],"name":"대응표","q":[1,4]},"variant_rule":{"alt":[{"stem":"내 나이와 형 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["위아래 짝 8과 10을 보면 형 나이는 내 나이보다 2 많아요.","?의 위 칸은 12 — 12 + 2 = 14예요.","?에 알맞은 수는 14예요."],"asset":{"type":"numgrid","rows":[["내 나이",8,9,10,11,12],["형 나이",10,11,12,13,null]],"name":"대응표","q":[1,5]}},{"stem":"언니 나이와 내 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["위아래 짝 10과 6을 보면 내 나이는 언니 나이보다 4 적어요.","?의 위 칸은 12 — 12 − 4 = 8이에요.","?에 알맞은 수는 8이에요."],"asset":{"type":"numgrid","rows":[["언니 나이",10,11,12,13,14],["내 나이",6,7,null,9,10]],"name":"대응표","q":[1,3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#4','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C3',1,'mc','auto','꿀벌 한 마리의 날개는 4개예요. 꿀벌 수가 정해지면 날개 수는 어떻게 되나요?',ARRAY['M5-1-u4-X05','M5-1-u4-X02']::text[],true,'{"seq":4,"concept":"M5-1-u4-C3","difficulty":1,"kind":"mc","stem":"꿀벌 한 마리의 날개는 4개예요. 꿀벌 수가 정해지면 날개 수는 어떻게 되나요?","options":[{"t":"하나로 정해진다","correct":true},{"t":"여러 가지가 될 수 있다","mis":"M5-1-u4-X05"},{"t":"꿀벌 수와 상관없이 늘 같다","mis":"M5-1-u4-X05"},{"t":"꿀벌 수보다 늘 4 많다","mis":"M5-1-u4-X02"}],"explanation":["꿀벌 하나에 날개 4개씩으로 정해져 있어요.","그래서 꿀벌 수가 정해지면 날개 수도 딱 하나로 정해져요.","이렇게 하나로 정해지는 두 양의 관계가 대응 관계예요."],"variant_rule":{"alt":[{"stem":"자전거 한 대에는 바퀴가 2개 있어요. 자전거 수가 정해지면 바퀴 수는 어떻게 되나요?","options":[{"t":"하나로 정해진다","correct":true},{"t":"여러 가지가 될 수 있다","mis":"M5-1-u4-X05"},{"t":"자전거 수와 상관없이 늘 같다","mis":"M5-1-u4-X05"},{"t":"자전거 수보다 늘 2 많다","mis":"M5-1-u4-X02"}],"explanation":["자전거 하나에 바퀴 2개씩으로 정해져 있어요.","그래서 자전거 수가 정해지면 바퀴 수도 딱 하나로 정해져요.","이렇게 하나로 정해지는 두 양의 관계가 대응 관계예요."]},{"stem":"피자 한 판은 8조각이에요. 피자 수가 정해지면 조각 수는 어떻게 되나요?","options":[{"t":"하나로 정해진다","correct":true},{"t":"여러 가지가 될 수 있다","mis":"M5-1-u4-X05"},{"t":"피자 수와 상관없이 늘 같다","mis":"M5-1-u4-X05"},{"t":"피자 수보다 늘 8 많다","mis":"M5-1-u4-X02"}],"explanation":["피자 하나에 조각 8개씩으로 정해져 있어요.","그래서 피자 수가 정해지면 조각 수도 딱 하나로 정해져요.","이렇게 하나로 정해지는 두 양의 관계가 대응 관계예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#5','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],true,'{"seq":5,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"오늘 날씨와 내 나이","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X13"},{"t":"꿀벌 수와 날개 수","mis":"M5-1-u4-X13"},{"t":"피자 수와 조각 수","mis":"M5-1-u4-X13"}],"explanation":["자전거 수와 바퀴 수 · 꿀벌 수와 날개 수 · 피자 수와 조각 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","오늘 날씨와 내 나이는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「오늘 날씨와 내 나이」예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"신발 크기와 좋아하는 과일 수","correct":true},{"t":"의자 수와 의자 다리 수","mis":"M5-1-u4-X13"},{"t":"모둠 수와 사람 수","mis":"M5-1-u4-X13"},{"t":"주 수와 날 수","mis":"M5-1-u4-X13"}],"explanation":["의자 수와 의자 다리 수 · 모둠 수와 사람 수 · 주 수와 날 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","신발 크기와 좋아하는 과일 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「신발 크기와 좋아하는 과일 수」예요."]},{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"내 키와 가진 연필 수","correct":true},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X13"},{"t":"젓가락 벌 수와 짝 수","mis":"M5-1-u4-X13"},{"t":"자동차 수와 바퀴 수","mis":"M5-1-u4-X13"}],"explanation":["삼각형 수와 변의 수 · 젓가락 벌 수와 짝 수 · 자동차 수와 바퀴 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","내 키와 가진 연필 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「내 키와 가진 연필 수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#6','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C2',2,'sa','auto','꿀벌 한 마리의 다리는 6개예요. 꿀벌의 다리가 모두 42개라면 꿀벌은 몇 마리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u4-C2","difficulty":2,"kind":"sa","stem":"꿀벌 한 마리의 다리는 6개예요. 꿀벌의 다리가 모두 42개라면 꿀벌은 몇 마리인가요? 숫자로 쓰세요.","answer":["7","7마리"],"explanation":["다리 수는 꿀벌 수의 6배예요.","거꾸로 가려면 6으로 나누어요 — 42 ÷ 6 = 7.","꿀벌은 7마리예요."],"variant_rule":{"alt":[{"stem":"꿀벌 한 마리의 날개는 4개예요. 꿀벌의 날개가 모두 36개라면 꿀벌은 몇 마리인가요? 숫자로 쓰세요.","answer":["9","9마리"],"explanation":["날개 수는 꿀벌 수의 4배예요.","거꾸로 가려면 4로 나누어요 — 36 ÷ 4 = 9.","꿀벌은 9마리예요."]},{"stem":"피자 한 판은 8조각이에요. 피자 조각이 모두 56조각이라면 피자는 몇 판인가요? 숫자로 쓰세요.","answer":["7","7판"],"explanation":["조각 수는 피자 수의 8배예요.","거꾸로 가려면 8로 나누어요 — 56 ÷ 8 = 7.","피자는 7판이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#7','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C2',2,'mc','auto','삼각형 수와 변의 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-1-u4-X01','M5-1-u4-X03','M5-1-u4-X04']::text[],true,'{"seq":7,"concept":"M5-1-u4-C2","difficulty":2,"kind":"mc","stem":"삼각형 수와 변의 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"변의 수는 삼각형 수의 3배","correct":true},{"t":"변의 수는 3씩 늘어난다","mis":"M5-1-u4-X01"},{"t":"변의 수는 삼각형 수보다 2 많다","mis":"M5-1-u4-X03"},{"t":"삼각형 수는 변의 수의 3배","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 1과 3, 2와 6, 3과 9.","변의 수는 삼각형 수의 3배 — 둘째 짝도 2 × 3 = 6으로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["삼각형 수",1,2,3,4,5],["변의 수",3,6,9,12,15]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"우쿨렐레 수와 줄 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"줄 수는 우쿨렐레 수의 4배","correct":true},{"t":"줄 수는 4씩 늘어난다","mis":"M5-1-u4-X01"},{"t":"줄 수는 우쿨렐레 수보다 3 많다","mis":"M5-1-u4-X03"},{"t":"우쿨렐레 수는 줄 수의 4배","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 1과 4, 2와 8, 3과 12.","줄 수는 우쿨렐레 수의 4배 — 둘째 짝도 2 × 4 = 8로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["우쿨렐레 수",1,2,3,4,5],["줄 수",4,8,12,16,20]],"name":"대응표"}},{"stem":"주 수와 날 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"날 수는 주 수의 7배","correct":true},{"t":"날 수는 7씩 늘어난다","mis":"M5-1-u4-X01"},{"t":"날 수는 주 수보다 6 많다","mis":"M5-1-u4-X03"},{"t":"주 수는 날 수의 7배","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 1과 7, 2와 14, 3과 21.","날 수는 주 수의 7배 — 둘째 짝도 2 × 7 = 14로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["주 수",1,2,3,4,5],["날 수",7,14,21,28,35]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#8','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C2',2,'mc','auto','원호 나이와 동생 나이의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],true,'{"seq":8,"concept":"M5-1-u4-C2","difficulty":2,"kind":"mc","stem":"원호 나이와 동생 나이의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"동생 나이는 원호 나이보다 3 적다","correct":true},{"t":"동생 나이는 원호 나이의 3배","mis":"M5-1-u4-X02"},{"t":"동생 나이는 원호 나이보다 3 많다","mis":"M5-1-u4-X04"},{"t":"원호 나이는 동생 나이보다 3 적다","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 12와 9, 13과 10, 14와 11.","동생 나이는 원호 나이보다 3 적다 — 둘째 짝도 13 − 3 = 10으로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["원호 나이",12,13,14,15],["동생 나이",9,10,11,12]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"내 나이와 형 나이의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"형 나이는 내 나이보다 2 많다","correct":true},{"t":"형 나이는 내 나이의 2배","mis":"M5-1-u4-X02"},{"t":"형 나이는 내 나이보다 2 적다","mis":"M5-1-u4-X04"},{"t":"내 나이는 형 나이보다 2 많다","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 8과 10, 9와 11, 10과 12.","형 나이는 내 나이보다 2 많다 — 둘째 짝도 9 + 2 = 11로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["내 나이",8,9,10,11],["형 나이",10,11,12,13]],"name":"대응표"}},{"stem":"방콕 시각과 서울 시각의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"서울 시각은 방콕 시각보다 2 많다","correct":true},{"t":"서울 시각은 방콕 시각의 2배","mis":"M5-1-u4-X02"},{"t":"서울 시각은 방콕 시각보다 2 적다","mis":"M5-1-u4-X04"},{"t":"방콕 시각은 서울 시각보다 2 많다","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 3과 5, 4와 6, 5와 7.","서울 시각은 방콕 시각보다 2 많다 — 둘째 짝도 4 + 2 = 6으로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["방콕 시각",3,4,5,6],["서울 시각",5,6,7,8]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#9','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C1',2,'ox','auto','우쿨렐레 수와 줄 수의 표에서 아래 줄이 4씩 늘어나는 것만 보아도 우쿨렐레 100개의 줄 수를 곱셈 한 번으로 구할 수 있어요.',ARRAY['M5-1-u4-X01']::text[],true,'{"seq":9,"concept":"M5-1-u4-C1","difficulty":2,"kind":"ox","stem":"우쿨렐레 수와 줄 수의 표에서 아래 줄이 4씩 늘어나는 것만 보아도 우쿨렐레 100개의 줄 수를 곱셈 한 번으로 구할 수 있어요.","answer":"X","reason_options":[{"t":"한 줄 규칙으로는 4를 99번 더해야 하고, 위아래 짝(4배)을 보아야 100 × 4로 한 번에 구하므로","correct":true},{"t":"4씩 늘어나니 100 + 4로 바로 구할 수 있으므로","mis":"M5-1-u4-X01"}],"mis":"M5-1-u4-X01","explanation":["아래 줄만 보면 「4씩 늘어난다」까지예요 — 100번째까지 4를 99번 더해야 해요.","위아래 짝을 보면 줄 수는 우쿨렐레 수의 4배예요.","그래서 100 × 4 = 400 — 짝을 보아야 한 번에 닿아요."],"variant_rule":{"alt":[{"stem":"원호가 12살일 때 동생은 9살, 13살일 때 10살이에요. 동생 나이는 원호 나이에 따라 하나로 정해지니 두 나이는 대응 관계예요.","answer":"O","reason_options":[{"t":"원호 나이가 정해지면 동생 나이가 늘 3살 적은 수로 하나로 정해지므로","correct":true},{"t":"두 사람 모두 해마다 1살씩 늘어나므로","mis":"M5-1-u4-X01"}],"explanation":["원호 나이 □가 정해지면 동생 나이는 □보다 3 적은 수로 하나예요.","「해마다 1살씩」은 한 사람의 나이만 본 한 줄 이야기예요.","두 나이 사이의 짝(3살 차)을 보아야 대응 관계예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_basic#10','math',5,1,'u4','L02','g5_1_math_u4_L02_basic','lesson_basic','M5-1-u4-C1',3,'sa','auto','우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 25개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 25개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["24","24번"],"explanation":["우쿨렐레 1개일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","25개까지 가려면 25 − 1 = 24번 더해요 — 4 + 4 × 24 = 100.","25 × 4 = 100처럼 짝의 규칙으로 곱하면 한 번에 닿아요."],"variant_rule":{"alt":[{"stem":"삼각형 수를 1, 2, 3, …으로 늘려 가며 변 수를 3, 6, 9, …으로 적었어요. 3부터 3씩 더해 가며 삼각형 30개의 변 수까지 가려면 3을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["29","29번"],"explanation":["삼각형 1개일 때가 3이고, 하나 늘 때마다 3을 한 번 더해요.","30개까지 가려면 30 − 1 = 29번 더해요 — 3 + 3 × 29 = 90.","30 × 3 = 90처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]},{"stem":"꿀벌 수를 1, 2, 3, …으로 늘려 가며 다리 수를 6, 12, 18, …으로 적었어요. 6부터 6씩 더해 가며 꿀벌 16마리의 다리 수까지 가려면 6을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["15","15번"],"explanation":["꿀벌 1마리일 때가 6이고, 하나 늘 때마다 6을 한 번 더해요.","16마리까지 가려면 16 − 1 = 15번 더해요 — 6 + 6 × 15 = 96.","16 × 6 = 96처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#1','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',2,'error','auto','우쿨렐레 수와 줄 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u4-X03','M5-1-u4-X13']::text[],true,'{"seq":1,"concept":"M5-1-u4-C2","difficulty":2,"kind":"error","stem":"우쿨렐레 수와 줄 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「첫 짝이 1과 4니 줄 수는 우쿨렐레 수보다 3 많아.」","correct":true,"mis_target":"M5-1-u4-X03"},{"t":"도현 — 「위아래로 짝지어 보면 줄 수는 우쿨렐레 수의 4배야.」","mis":"M5-1-u4-X13"},{"t":"하은 — 「우쿨렐레 수가 3일 때 줄 수는 12야.」","mis":"M5-1-u4-X13"}],"explanation":["짝 1과 4, 2와 8, 3과 12를 모두 보면 줄 수는 우쿨렐레 수의 4배예요.","「3 많다」는 첫 짝에서만 맞아요 — 둘째 짝은 2와 8로 6 차이예요.","서윤은 짝 하나만 보고 관계를 정해 잘못 말했어요."],"asset":{"type":"numgrid","rows":[["우쿨렐레 수",1,2,3,4,5],["줄 수",4,8,12,16,20]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"삼각형 수와 변의 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「첫 짝이 1과 3이니 변의 수는 삼각형 수보다 2 많아.」","correct":true,"mis_target":"M5-1-u4-X03"},{"t":"라온 — 「위아래로 짝지어 보면 변의 수는 삼각형 수의 3배야.」","mis":"M5-1-u4-X13"},{"t":"예준 — 「삼각형 수가 3일 때 변의 수는 9야.」","mis":"M5-1-u4-X13"}],"explanation":["짝 1과 3, 2와 6, 3과 9를 모두 보면 변의 수는 삼각형 수의 3배예요.","「2 많다」는 첫 짝에서만 맞아요 — 둘째 짝은 2와 6으로 4 차이예요.","지민은 짝 하나만 보고 관계를 정해 잘못 말했어요."],"asset":{"type":"numgrid","rows":[["삼각형 수",1,2,3,4,5],["변의 수",3,6,9,12,15]],"name":"대응표"}},{"stem":"피자 수와 조각 수의 대응표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「첫 짝이 1과 8이니 조각 수는 피자 수보다 7 많아.」","correct":true,"mis_target":"M5-1-u4-X03"},{"t":"가온 — 「위아래로 짝지어 보면 조각 수는 피자 수의 8배야.」","mis":"M5-1-u4-X13"},{"t":"다솜 — 「피자 수가 3일 때 조각 수는 24야.」","mis":"M5-1-u4-X13"}],"explanation":["짝 1과 8, 2와 16, 3과 24를 모두 보면 조각 수는 피자 수의 8배예요.","「7 많다」는 첫 짝에서만 맞아요 — 둘째 짝은 2와 16으로 14 차이예요.","윤슬은 짝 하나만 보고 관계를 정해 잘못 말했어요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4],["조각 수",8,16,24,32]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#2','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계인 것은 어느 것인가요?',ARRAY['M5-1-u4-X05']::text[],true,'{"seq":2,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"자전거 수와 바퀴 수","correct":true},{"t":"내 키와 좋아하는 색깔 수","mis":"M5-1-u4-X05"},{"t":"오늘 날씨와 내 나이","mis":"M5-1-u4-X05"},{"t":"내 몸무게와 가진 책 수","mis":"M5-1-u4-X05"}],"explanation":["내 키와 좋아하는 색깔 수 · 오늘 날씨와 내 나이 · 내 몸무게와 가진 책 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","자전거 수와 바퀴 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「자전거 수와 바퀴 수」예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"주 수와 날 수","correct":true},{"t":"신발 크기와 좋아하는 과일 수","mis":"M5-1-u4-X05"},{"t":"내 키와 가진 연필 수","mis":"M5-1-u4-X05"},{"t":"오늘 기온과 반 친구 수","mis":"M5-1-u4-X05"}],"explanation":["신발 크기와 좋아하는 과일 수 · 내 키와 가진 연필 수 · 오늘 기온과 반 친구 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","주 수와 날 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「주 수와 날 수」예요."]},{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"피자 수와 조각 수","correct":true},{"t":"내 나이와 좋아하는 노래 수","mis":"M5-1-u4-X05"},{"t":"머리카락 길이와 가진 공책 수","mis":"M5-1-u4-X05"},{"t":"오늘 날씨와 짝꿍 이름","mis":"M5-1-u4-X05"}],"explanation":["내 나이와 좋아하는 노래 수 · 머리카락 길이와 가진 공책 수 · 오늘 날씨와 짝꿍 이름은 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","피자 수와 조각 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「피자 수와 조각 수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#3','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',3,'sa','auto','꿀벌 수와 다리 수의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u4-C2","difficulty":3,"kind":"sa","stem":"꿀벌 수와 다리 수의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["다리 수는 꿀벌 수의 6배예요.","?는 위 칸이라 아래 수 30에서 거꾸로 가요 — 30 ÷ 6 = 5.","?에 알맞은 수는 5예요."],"asset":{"type":"numgrid","rows":[["꿀벌 수",1,2,3,4,null,6],["다리 수",6,12,18,24,30,36]],"name":"대응표","q":[0,5]},"variant_rule":{"alt":[{"stem":"피자 수와 조각 수의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["조각 수는 피자 수의 8배예요.","?는 위 칸이라 아래 수 48에서 거꾸로 가요 — 48 ÷ 8 = 6.","?에 알맞은 수는 6이에요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4,5,null],["조각 수",8,16,24,32,40,48]],"name":"대응표","q":[0,6]}},{"stem":"원호 나이와 동생 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["동생 나이는 원호 나이보다 3 적어요.","?는 위 칸이라 아래 수 13에서 거꾸로 가요 — 13 + 3 = 16.","?에 알맞은 수는 16이에요."],"asset":{"type":"numgrid","rows":[["원호 나이",12,13,14,15,null,17],["동생 나이",9,10,11,12,13,14]],"name":"대응표","q":[0,5]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#4','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C1',3,'sa','auto','우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 100개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 100개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["99","99번"],"explanation":["우쿨렐레 1개일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","100개까지 가려면 100 − 1 = 99번 더해요 — 4 + 4 × 99 = 400.","100 × 4 = 400처럼 짝의 규칙으로 곱하면 한 번에 닿아요."],"variant_rule":{"alt":[{"stem":"꿀벌 수를 1, 2, 3, …으로 늘려 가며 날개 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 꿀벌 50마리의 날개 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["49","49번"],"explanation":["꿀벌 1마리일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","50마리까지 가려면 50 − 1 = 49번 더해요 — 4 + 4 × 49 = 200.","50 × 4 = 200처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]},{"stem":"삼각형 수를 1, 2, 3, …으로 늘려 가며 변 수를 3, 6, 9, …으로 적었어요. 3부터 3씩 더해 가며 삼각형 80개의 변 수까지 가려면 3을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["79","79번"],"explanation":["삼각형 1개일 때가 3이고, 하나 늘 때마다 3을 한 번 더해요.","80개까지 가려면 80 − 1 = 79번 더해요 — 3 + 3 × 79 = 240.","80 × 3 = 240처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#5','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',3,'mc','auto','위아래 짝이 「△는 □의 3배」인 대응표를 짝으로 적은 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X03']::text[],true,'{"seq":5,"concept":"M5-1-u4-C2","difficulty":3,"kind":"mc","stem":"위아래 짝이 「△는 □의 3배」인 대응표를 짝으로 적은 것은 어느 것인가요?","options":[{"t":"1과 3, 2와 6, 3과 9","correct":true},{"t":"1과 4, 2와 5, 3과 6","mis":"M5-1-u4-X02"},{"t":"3과 1, 6과 2, 9와 3","mis":"M5-1-u4-X04"},{"t":"1과 3, 2와 5, 3과 7","mis":"M5-1-u4-X03"}],"explanation":["「△는 □의 3배」면 □에 3을 곱한 수가 △예요.","1 × 3 = 3, 2 × 3 = 6, 3 × 3 = 9예요.","그래서 짝은 1과 3, 2와 6, 3과 9예요."],"variant_rule":{"alt":[{"stem":"위아래 짝이 「△는 □의 4배」인 대응표를 짝으로 적은 것은 어느 것인가요?","options":[{"t":"1과 4, 2와 8, 3과 12","correct":true},{"t":"1과 5, 2와 6, 3과 7","mis":"M5-1-u4-X02"},{"t":"4와 1, 8과 2, 12와 3","mis":"M5-1-u4-X04"},{"t":"1과 4, 2와 6, 3과 8","mis":"M5-1-u4-X03"}],"explanation":["「△는 □의 4배」면 □에 4를 곱한 수가 △예요.","1 × 4 = 4, 2 × 4 = 8, 3 × 4 = 12예요.","그래서 짝은 1과 4, 2와 8, 3과 12예요."]},{"stem":"위아래 짝이 「△는 □의 5배」인 대응표를 짝으로 적은 것은 어느 것인가요?","options":[{"t":"1과 5, 2와 10, 3과 15","correct":true},{"t":"1과 6, 2와 7, 3과 8","mis":"M5-1-u4-X02"},{"t":"5와 1, 10과 2, 15와 3","mis":"M5-1-u4-X04"},{"t":"1과 5, 2와 7, 3과 9","mis":"M5-1-u4-X03"}],"explanation":["「△는 □의 5배」면 □에 5를 곱한 수가 △예요.","1 × 5 = 5, 2 × 5 = 10, 3 × 5 = 15예요.","그래서 짝은 1과 5, 2와 10, 3과 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#6','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C3',3,'ox','auto','내 키가 정해지면 내가 좋아하는 색깔 수도 하나로 정해지므로 두 양은 대응 관계예요.',ARRAY['M5-1-u4-X05']::text[],true,'{"seq":6,"concept":"M5-1-u4-C3","difficulty":3,"kind":"ox","stem":"내 키가 정해지면 내가 좋아하는 색깔 수도 하나로 정해지므로 두 양은 대응 관계예요.","answer":"X","reason_options":[{"t":"키가 같은 친구들도 좋아하는 색깔 수는 저마다 달라 하나로 정해지지 않으므로","correct":true},{"t":"키와 색깔 수 모두 수로 나타낼 수 있으므로","mis":"M5-1-u4-X05"}],"mis":"M5-1-u4-X05","explanation":["키가 140 cm인 친구가 여럿이어도 좋아하는 색깔 수는 저마다 달라요.","한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","그래서 키와 좋아하는 색깔 수는 대응 관계가 아니에요."],"variant_rule":{"alt":[{"stem":"피자 수가 정해지면 피자 조각 수도 하나로 정해지므로 두 양은 대응 관계예요(한 판은 8조각).","answer":"O","reason_options":[{"t":"한 판에 8조각으로 정해져 있어 판 수가 정해지면 조각 수가 딱 하나로 정해지므로","correct":true},{"t":"피자는 여러 사람이 나누어 먹으므로","mis":"M5-1-u4-X05"}],"explanation":["한 판은 8조각으로 정해져 있어요.","판 수가 정해지면 조각 수는 판 수의 8배로 하나예요.","그래서 피자 수와 조각 수는 대응 관계예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#7','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',3,'sa','auto','꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 36개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u4-C2","difficulty":3,"kind":"sa","stem":"꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 36개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["54","54개"],"explanation":["날개 수는 꿀벌 수의 4배 — 꿀벌은 36 ÷ 4 = 9마리예요.","다리 수는 꿀벌 수의 6배예요.","9 × 6 = 54 — 다리는 54개예요."],"variant_rule":{"alt":[{"stem":"꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 44개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["66","66개"],"explanation":["날개 수는 꿀벌 수의 4배 — 꿀벌은 44 ÷ 4 = 11마리예요.","다리 수는 꿀벌 수의 6배예요.","11 × 6 = 66 — 다리는 66개예요."]},{"stem":"꿀벌 한 마리는 날개가 4개, 다리가 6개예요. 날개가 모두 28개라면 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["42","42개"],"explanation":["날개 수는 꿀벌 수의 4배 — 꿀벌은 28 ÷ 4 = 7마리예요.","다리 수는 꿀벌 수의 6배예요.","7 × 6 = 42 — 다리는 42개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#8','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C2',4,'sa','auto','원호는 늘 동생보다 3살 많아요. 두 사람의 나이를 더했더니 31살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u4-C2","difficulty":4,"kind":"sa","stem":"원호는 늘 동생보다 3살 많아요. 두 사람의 나이를 더했더니 31살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.","answer":["14","14살"],"explanation":["원호 나이는 동생 나이보다 3 많아요 — 합에서 3을 빼면 동생 나이의 2배예요.","31 − 3 = 28, 28 ÷ 2 = 14예요.","동생은 14살, 원호는 17살 — 14 + 17 = 31로 맞아요."],"variant_rule":{"alt":[{"stem":"언니는 늘 나보다 4살 많아요. 두 사람의 나이를 더했더니 30살이에요. 나는 몇 살인가요? 숫자로 쓰세요.","answer":["13","13살"],"explanation":["언니 나이는 나 나이보다 4 많아요 — 합에서 4를 빼면 나 나이의 2배예요.","30 − 4 = 26, 26 ÷ 2 = 13이에요.","나는 13살, 언니는 17살 — 13 + 17 = 30으로 맞아요."]},{"stem":"형은 늘 나보다 2살 많아요. 두 사람의 나이를 더했더니 26살이에요. 나는 몇 살인가요? 숫자로 쓰세요.","answer":["12","12살"],"explanation":["형 나이는 나 나이보다 2 많아요 — 합에서 2를 빼면 나 나이의 2배예요.","26 − 2 = 24, 24 ÷ 2 = 12예요.","나는 12살, 형은 14살 — 12 + 14 = 26으로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#9','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C1',4,'essay','teacher','우쿨렐레 수와 줄 수의 표에서 「줄 수는 4씩 늘어난다」와 「줄 수는 우쿨렐레 수의 4배」는 어떻게 다른지, 우쿨렐레 100개의 줄 수를 구하는 방법과 함께 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u4-C1","difficulty":4,"kind":"essay","stem":"우쿨렐레 수와 줄 수의 표에서 「줄 수는 4씩 늘어난다」와 「줄 수는 우쿨렐레 수의 4배」는 어떻게 다른지, 우쿨렐레 100개의 줄 수를 구하는 방법과 함께 설명하세요.","answer_guide":{"answer":"예: 「4씩 늘어난다」는 아래 줄 한 줄만 본 것이고, 「4배」는 우쿨렐레 수와 줄 수를 위아래로 짝지어 본 대응 관계이다. 4씩 늘어난다는 것만 알면 100개까지 4를 99번 더해야 하지만, 4배라는 짝을 알면 100 × 4 = 400으로 한 번에 구할 수 있다.","scoring_points":["「4씩 늘어난다」는 한 줄, 「4배」는 두 양의 짝이라고 구별했는가","100 × 4 = 400으로 구했는가","짝을 알면 먼 자리 값을 한 번에 구한다고 맺었는가"]},"explanation":["한 줄만 보면 「4씩 늘어난다」예요.","두 양을 짝지으면 「4배」가 보여요.","100 × 4 = 400 — 짝의 규칙으로 한 번에 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L02_challenge#10','math',5,1,'u4','L02','g5_1_math_u4_L02_challenge','lesson_challenge','M5-1-u4-C3',4,'essay','teacher','「오늘 날씨와 내 나이」가 대응 관계가 아닌 까닭을 대응 관계의 뜻을 써서 설명하고, 대응 관계인 두 양을 하나 예로 드세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u4-C3","difficulty":4,"kind":"essay","stem":"「오늘 날씨와 내 나이」가 대응 관계가 아닌 까닭을 대응 관계의 뜻을 써서 설명하고, 대응 관계인 두 양을 하나 예로 드세요.","answer_guide":{"answer":"예: 대응 관계는 한 양이 변할 때 다른 양이 그에 따라 하나로 정해지는 관계이다. 오늘 날씨가 맑든 비가 오든 내 나이는 날씨에 따라 정해지지 않으므로 대응 관계가 아니다. 자전거 수와 바퀴 수는 자전거 수가 정해지면 바퀴 수가 2배로 하나로 정해지므로 대응 관계이다.","scoring_points":["대응 관계의 뜻(하나로 정해짐)을 썼는가","날씨에 따라 나이가 정해지지 않는다고 썼는가","대응 관계인 두 양을 바르게 예로 들었는가"]},"explanation":["대응 관계는 한 양이 정해지면 다른 양이 하나로 정해지는 관계예요.","날씨가 정해져도 나이는 정해지지 않아요.","자전거 수와 바퀴 수처럼 하나로 정해지는 두 양이 대응 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#1','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',1,'mc','auto','우쿨렐레 한 개에 줄이 4개예요. 우쿨렐레 수를 □, 줄 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],true,'{"seq":1,"concept":"M5-1-u4-C4","difficulty":1,"kind":"mc","stem":"우쿨렐레 한 개에 줄이 4개예요. 우쿨렐레 수를 □, 줄 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ − 4 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(줄 수)는 □(우쿨렐레 수)의 4배예요.","그 말을 그대로 옮기면 □ × 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."],"variant_rule":{"alt":[{"stem":"자동차 한 대에 바퀴가 4개예요. 자동차 수를 □, 바퀴 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ − 4 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(바퀴 수)는 □(자동차 수)의 4배예요.","그 말을 그대로 옮기면 □ × 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]},{"stem":"곤충 한 마리에 다리가 6개예요. 곤충 수를 □, 다리 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 6 = △","correct":true},{"t":"□ + 6 = △","mis":"M5-1-u4-X02"},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"},{"t":"□ − 6 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(다리 수)는 □(곤충 수)의 6배예요.","그 말을 그대로 옮기면 □ × 6 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#2','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',1,'sa','auto','□ × 5 = △에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C4","difficulty":1,"kind":"sa","stem":"□ × 5 = △에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["□ 자리에 9를 넣어요.","9 × 5 = 45예요.","△는 45예요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △에서 □가 8일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["□ 자리에 8을 넣어요.","8 × 6 = 48이에요.","△는 48이에요."]},{"stem":"□ × 4 = △에서 □가 12일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["□ 자리에 12를 넣어요.","12 × 4 = 48이에요.","△는 48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#3','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',1,'sa','auto','□ × 4 = △에서 △가 32일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u4-C4","difficulty":1,"kind":"sa","stem":"□ × 4 = △에서 △가 32일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 32가 오도록 □를 찾아요 — 되돌리는 셈을 해요.","32 ÷ 4 = 8이에요.","□는 8이에요. 8 × 4 = 32로 확인해요."],"variant_rule":{"alt":[{"stem":"□ × 7 = △에서 △가 56일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 56이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","56 ÷ 7 = 8이에요.","□는 8이에요. 8 × 7 = 56으로 확인해요."]},{"stem":"□ × 3 = △에서 △가 27일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△ 자리에 27이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","27 ÷ 3 = 9예요.","□는 9예요. 9 × 3 = 27로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#4','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C5',1,'mc','auto','□ × 4 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X08','M5-1-u4-X02']::text[],true,'{"seq":4,"concept":"M5-1-u4-C5","difficulty":1,"kind":"mc","stem":"□ × 4 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 4 = □","correct":true},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 4 = △","mis":"M5-1-u4-X08"},{"t":"△ + 4 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 4 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 4 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 4 = 12, 거꾸로 12 ÷ 4 = 3으로 같은 짝이에요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 6 = □","correct":true},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 6 = △","mis":"M5-1-u4-X08"},{"t":"△ + 6 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 6 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 6 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 6 = 18, 거꾸로 18 ÷ 6 = 3으로 같은 짝이에요."]},{"stem":"□ × 9 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 9 = □","correct":true},{"t":"△ × 9 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 9 = △","mis":"M5-1-u4-X08"},{"t":"△ + 9 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 9 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 9 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 9 = 27, 거꾸로 27 ÷ 9 = 3으로 같은 짝이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#5','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',2,'mc','auto','원호는 동생보다 3살 많아요. 원호 나이를 □, 동생 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X02']::text[],true,'{"seq":5,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"원호는 동생보다 3살 많아요. 원호 나이를 □, 동생 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ − 3 = △","correct":true},{"t":"□ + 3 = △","mis":"M5-1-u4-X04"},{"t":"□ × 3 = △","mis":"M5-1-u4-X02"},{"t":"△ − 3 = □","mis":"M5-1-u4-X04"}],"explanation":["말로 먼저 해요 — △(동생 나이)는 □(원호 나이)보다 3 적어요.","그 말을 그대로 옮기면 □ − 3 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."],"variant_rule":{"alt":[{"stem":"언니는 나보다 4살 많아요. 언니 나이를 □, 내 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ − 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X04"},{"t":"□ × 4 = △","mis":"M5-1-u4-X02"},{"t":"△ − 4 = □","mis":"M5-1-u4-X04"}],"explanation":["말로 먼저 해요 — △(내 나이)는 □(언니 나이)보다 4 적어요.","그 말을 그대로 옮기면 □ − 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]},{"stem":"형은 나보다 2살 많아요. 내 나이를 □, 형 나이를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 2 = △","mis":"M5-1-u4-X02"},{"t":"△ + 2 = □","mis":"M5-1-u4-X04"},{"t":"□ − 2 = △","mis":"M5-1-u4-X04"}],"explanation":["말로 먼저 해요 — △(형 나이)는 □(내 나이)보다 2 많아요.","그 말을 그대로 옮기면 □ + 2 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#6','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',2,'mc','auto','자동차 수를 □, 바퀴 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],true,'{"seq":6,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"자동차 수를 □, 바퀴 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?","options":[{"t":"□ + 3 = △","correct":true},{"t":"□ × 4 = △","mis":"M5-1-u4-X13"},{"t":"△ ÷ 4 = □","mis":"M5-1-u4-X13"},{"t":"△ = □ × 4","mis":"M5-1-u4-X13"}],"explanation":["위아래 짝 1과 4, 2와 8, 3과 12를 모두 보면 △는 □의 4배예요.","□ + 3 = △는 첫 짝에서만 맞아요 — 둘째 짝 2 + 3 = 5이지만 실제 △는 8이에요.","나머지 셋은 같은 관계를 다르게 쓴 맞는 식이에요."],"asset":{"type":"numgrid","rows":[["자동차 수",1,2,3,4,5],["바퀴 수",4,8,12,16,20]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"피자 수를 □, 조각 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?","options":[{"t":"□ + 7 = △","correct":true},{"t":"□ × 8 = △","mis":"M5-1-u4-X13"},{"t":"△ ÷ 8 = □","mis":"M5-1-u4-X13"},{"t":"△ = □ × 8","mis":"M5-1-u4-X13"}],"explanation":["위아래 짝 1과 8, 2와 16, 3과 24를 모두 보면 △는 □의 8배예요.","□ + 7 = △는 첫 짝에서만 맞아요 — 둘째 짝 2 + 7 = 9이지만 실제 △는 16이에요.","나머지 셋은 같은 관계를 다르게 쓴 맞는 식이에요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4,5],["조각 수",8,16,24,32,40]],"name":"대응표"}},{"stem":"삼각형 수를 □, 변의 수를 △라고 할 때 표를 보고 쓴 식 중 잘못된 것은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 3 = △","mis":"M5-1-u4-X13"},{"t":"△ ÷ 3 = □","mis":"M5-1-u4-X13"},{"t":"△ = □ × 3","mis":"M5-1-u4-X13"}],"explanation":["위아래 짝 1과 3, 2와 6, 3과 9를 모두 보면 △는 □의 3배예요.","□ + 2 = △는 첫 짝에서만 맞아요 — 둘째 짝 2 + 2 = 4이지만 실제 △는 6이에요.","나머지 셋은 같은 관계를 다르게 쓴 맞는 식이에요."],"asset":{"type":"numgrid","rows":[["삼각형 수",1,2,3,4,5],["변의 수",3,6,9,12,15]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#7','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',2,'sa','auto','□ − 3 = △에서 △가 14일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u4-C4","difficulty":2,"kind":"sa","stem":"□ − 3 = △에서 △가 14일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["△ 자리에 14가 오도록 □를 찾아요 — 되돌리는 셈을 해요.","14 + 3 = 17이에요.","□는 17이에요. 17 − 3 = 14로 확인해요."],"variant_rule":{"alt":[{"stem":"□ − 5 = △에서 △가 21일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["△ 자리에 21이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","21 + 5 = 26이에요.","□는 26이에요. 26 − 5 = 21로 확인해요."]},{"stem":"□ + 4 = △에서 △가 30일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["△ 자리에 30이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","30 − 4 = 26이에요.","□는 26이에요. 26 + 4 = 30으로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#8','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',2,'mc','auto','방콕 시각을 □, 서울 시각을 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X01']::text[],true,'{"seq":8,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"방콕 시각을 □, 서울 시각을 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 2 = △","mis":"M5-1-u4-X02"},{"t":"△ + 2 = □","mis":"M5-1-u4-X04"},{"t":"□ + 1 = △","mis":"M5-1-u4-X01"}],"explanation":["위아래 짝 3과 5, 4와 6, 5와 7을 보아요.","모든 짝에서 △는 □보다 2 많아요.","그래서 식은 □ + 2 = △예요."],"asset":{"type":"numgrid","rows":[["방콕 시각",3,4,5,6,7],["서울 시각",5,6,7,8,9]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"내 나이를 □, 형 나이를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 2 = △","mis":"M5-1-u4-X02"},{"t":"△ + 2 = □","mis":"M5-1-u4-X04"},{"t":"□ + 1 = △","mis":"M5-1-u4-X01"}],"explanation":["위아래 짝 8과 10, 9와 11, 10과 12를 보아요.","모든 짝에서 △는 □보다 2 많아요.","그래서 식은 □ + 2 = △예요."],"asset":{"type":"numgrid","rows":[["내 나이",8,9,10,11,12],["형 나이",10,11,12,13,14]],"name":"대응표"}},{"stem":"원호 나이를 □, 동생 나이를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ − 3 = △","correct":true},{"t":"□ × 3 = △","mis":"M5-1-u4-X02"},{"t":"△ − 3 = □","mis":"M5-1-u4-X04"},{"t":"□ + 1 = △","mis":"M5-1-u4-X01"}],"explanation":["위아래 짝 12와 9, 13과 10, 14와 11을 보아요.","모든 짝에서 △는 □보다 3 적어요.","그래서 식은 □ − 3 = △예요."],"asset":{"type":"numgrid","rows":[["원호 나이",12,13,14,15,16],["동생 나이",9,10,11,12,13]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#9','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C5',2,'ox','auto','△ ÷ 4 = □와 □ × 4 = △는 서로 다른 대응 관계를 나타내요.',ARRAY['M5-1-u4-X08']::text[],true,'{"seq":9,"concept":"M5-1-u4-C5","difficulty":2,"kind":"ox","stem":"△ ÷ 4 = □와 □ × 4 = △는 서로 다른 대응 관계를 나타내요.","answer":"X","reason_options":[{"t":"□ = 3이면 □ × 4 = 12, 거꾸로 12 ÷ 4 = 3으로 두 식이 같은 짝을 내므로","correct":true},{"t":"쓰인 셈이 ÷와 ×로 다르므로","mis":"M5-1-u4-X08"}],"mis":"M5-1-u4-X08","explanation":["□ × 4 = △에 □ = 3을 넣으면 △ = 12예요.","△ ÷ 4 = □에 △ = 12를 넣으면 □ = 3이에요.","같은 짝을 내니 같은 관계를 반대 방향에서 쓴 식이에요."],"variant_rule":{"alt":[{"stem":"□ − 3 = △와 △ + 3 = □는 같은 대응 관계를 나타내요.","answer":"O","reason_options":[{"t":"□ = 15이면 15 − 3 = 12, 거꾸로 12 + 3 = 15로 같은 짝을 내므로","correct":true},{"t":"−와 +는 반대 셈이라 관계도 반대이므로","mis":"M5-1-u4-X08"}],"explanation":["□ − 3 = △에 □ = 15를 넣으면 △ = 12예요.","△ + 3 = □에 △ = 12를 넣으면 □ = 15예요.","같은 짝을 내니 같은 관계예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_basic#10','math',5,1,'u4','L03','g5_1_math_u4_L03_basic','lesson_basic','M5-1-u4-C4',3,'sa','auto','□ × 5 = △이고 □와 △를 더하면 48이에요. □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-1-u4-C4","difficulty":3,"kind":"sa","stem":"□ × 5 = △이고 □와 △를 더하면 48이에요. □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△는 □의 5배라서 □ + △는 □의 6배예요.","48 ÷ 6 = 8이에요.","□ = 8, △ = 8 × 5 = 40 — 8 + 40 = 48로 맞아요."],"variant_rule":{"alt":[{"stem":"□ × 3 = △이고 □와 △를 더하면 64예요. □는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["△는 □의 3배라서 □ + △는 □의 4배예요.","64 ÷ 4 = 16이에요.","□ = 16, △ = 16 × 3 = 48 — 16 + 48 = 64로 맞아요."]},{"stem":"□ × 7 = △이고 □와 △를 더하면 72예요. □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△는 □의 7배라서 □ + △는 □의 8배예요.","72 ÷ 8 = 9예요.","□ = 9, △ = 9 × 7 = 63 — 9 + 63 = 72로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#1','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C4',2,'error','auto','자동차 한 대에 바퀴가 4개예요. 자동차 수를 □, 바퀴 수를 △라고 정하고 친구들이 식을 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X13']::text[],true,'{"seq":1,"concept":"M5-1-u4-C4","difficulty":2,"kind":"error","stem":"자동차 한 대에 바퀴가 4개예요. 자동차 수를 □, 바퀴 수를 △라고 정하고 친구들이 식을 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"서윤 — 「△ × 4 = □」","correct":true,"mis_target":"M5-1-u4-X04"},{"t":"지호 — 「□ × 4 = △」","mis":"M5-1-u4-X13"},{"t":"하린 — 「△ ÷ 4 = □」","mis":"M5-1-u4-X13"}],"explanation":["말로 하면 △(바퀴 수)는 □(자동차 수)의 4배예요.","□ × 4 = △와 △ ÷ 4 = □는 같은 관계를 두 방향에서 쓴 맞는 식이에요.","서윤은 □와 △의 자리를 바꾸어 다른 관계를 썼어요."],"variant_rule":{"alt":[{"stem":"1주일은 7일이에요. 주 수를 □, 날 수를 △라고 정하고 친구들이 식을 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"도윤 — 「△ × 7 = □」","correct":true,"mis_target":"M5-1-u4-X04"},{"t":"나은 — 「□ × 7 = △」","mis":"M5-1-u4-X13"},{"t":"시온 — 「△ ÷ 7 = □」","mis":"M5-1-u4-X13"}],"explanation":["말로 하면 △(날 수)는 □(주 수)의 7배예요.","□ × 7 = △와 △ ÷ 7 = □는 같은 관계를 두 방향에서 쓴 맞는 식이에요.","도윤은 □와 △의 자리를 바꾸어 다른 관계를 썼어요."]},{"stem":"오각형 하나에 꼭짓점이 5개예요. 오각형 수를 □, 꼭짓점 수를 △라고 정하고 친구들이 식을 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"윤슬 — 「△ × 5 = □」","correct":true,"mis_target":"M5-1-u4-X04"},{"t":"가온 — 「□ × 5 = △」","mis":"M5-1-u4-X13"},{"t":"다솜 — 「△ ÷ 5 = □」","mis":"M5-1-u4-X13"}],"explanation":["말로 하면 △(꼭짓점 수)는 □(오각형 수)의 5배예요.","□ × 5 = △와 △ ÷ 5 = □는 같은 관계를 두 방향에서 쓴 맞는 식이에요.","윤슬은 □와 △의 자리를 바꾸어 다른 관계를 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#2','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C5',2,'match','auto','같은 대응 관계를 나타낸 식끼리 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C5","difficulty":2,"kind":"match","stem":"같은 대응 관계를 나타낸 식끼리 이으세요.","pairs":[{"l":"□ × 6 = △","r":"△ ÷ 6 = □"},{"l":"□ + 6 = △","r":"△ − 6 = □"},{"l":"□ − 6 = △","r":"△ + 6 = □"}],"mis":"M5-1-u4-X08","explanation":["□ × 6 = △를 거꾸로 하면 △ ÷ 6 = □예요.","□ + 6 = △를 거꾸로 하면 △ − 6 = □, □ − 6 = △를 거꾸로 하면 △ + 6 = □예요.","거꾸로 쓸 때는 셈이 반대로 바뀌어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 대응 관계를 나타낸 식끼리 이으세요.","pairs":[{"l":"□ × 8 = △","r":"△ ÷ 8 = □"},{"l":"□ + 8 = △","r":"△ − 8 = □"},{"l":"□ − 8 = △","r":"△ + 8 = □"}],"explanation":["□ × 8 = △를 거꾸로 하면 △ ÷ 8 = □예요.","□ + 8 = △ ↔ △ − 8 = □, □ − 8 = △ ↔ △ + 8 = □예요.","거꾸로 쓸 때는 셈이 반대로 바뀌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#3','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C4',3,'mc','auto','우쿨렐레 수를 □, 줄 수를 △라고 할 때 표의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X03','M5-1-u4-X01','M5-1-u4-X04']::text[],true,'{"seq":3,"concept":"M5-1-u4-C4","difficulty":3,"kind":"mc","stem":"우쿨렐레 수를 □, 줄 수를 △라고 할 때 표의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 9 = △","mis":"M5-1-u4-X03"},{"t":"□ + 4 = △","mis":"M5-1-u4-X01"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"}],"explanation":["첫 짝 3과 12만 보면 「9 많다」 같아 보여요.","둘째 짝 4와 16에서는 12 차이라 「많다」는 맞지 않아요 — 모든 짝에서 △는 □의 4배예요.","그래서 식은 □ × 4 = △예요."],"asset":{"type":"numgrid","rows":[["우쿨렐레 수",3,4,5,6,7],["줄 수",12,16,20,24,28]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"주 수를 □, 날 수를 △라고 할 때 표의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 7 = △","correct":true},{"t":"□ + 12 = △","mis":"M5-1-u4-X03"},{"t":"□ + 7 = △","mis":"M5-1-u4-X01"},{"t":"△ × 7 = □","mis":"M5-1-u4-X04"}],"explanation":["첫 짝 2와 14만 보면 「12 많다」 같아 보여요.","둘째 짝 3과 21에서는 18 차이라 「많다」는 맞지 않아요 — 모든 짝에서 △는 □의 7배예요.","그래서 식은 □ × 7 = △예요."],"asset":{"type":"numgrid","rows":[["주 수",2,3,4,5,6],["날 수",14,21,28,35,42]],"name":"대응표"}},{"stem":"꿀벌 수를 □, 다리 수를 △라고 할 때 표의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 6 = △","correct":true},{"t":"□ + 20 = △","mis":"M5-1-u4-X03"},{"t":"□ + 6 = △","mis":"M5-1-u4-X01"},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"}],"explanation":["첫 짝 4와 24만 보면 「20 많다」 같아 보여요.","둘째 짝 5와 30에서는 25 차이라 「많다」는 맞지 않아요 — 모든 짝에서 △는 □의 6배예요.","그래서 식은 □ × 6 = △예요."],"asset":{"type":"numgrid","rows":[["꿀벌 수",4,5,6,7,8],["다리 수",24,30,36,42,48]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#4','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C4',3,'sa','auto','내 나이와 아빠 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u4-C4","difficulty":3,"kind":"sa","stem":"내 나이와 아빠 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["아빠 나이는 내 나이보다 29 많아요.","?는 위 칸이라 아래 수 41에서 거꾸로 가요 — 41 − 29 = 12.","?에 알맞은 수는 12예요."],"asset":{"type":"numgrid","rows":[["내 나이",9,10,11,null,13],["아빠 나이",38,39,40,41,42]],"name":"대응표","q":[0,4]},"variant_rule":{"alt":[{"stem":"언니 나이와 내 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["내 나이는 언니 나이보다 4 적어요.","?는 위 칸이라 아래 수 13에서 거꾸로 가요 — 13 + 4 = 17.","?에 알맞은 수는 17이에요."],"asset":{"type":"numgrid","rows":[["언니 나이",15,16,null,18,19],["내 나이",11,12,13,14,15]],"name":"대응표","q":[0,3]}},{"stem":"내 나이와 형 나이의 대응표예요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["형 나이는 내 나이보다 2 많아요.","?는 위 칸이라 아래 수 13에서 거꾸로 가요 — 13 − 2 = 11.","?에 알맞은 수는 11이에요."],"asset":{"type":"numgrid","rows":[["내 나이",7,8,9,10,null],["형 나이",9,10,11,12,13]],"name":"대응표","q":[0,5]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#5','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C5',3,'sa','auto','△ ÷ 8 = □에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u4-C5","difficulty":3,"kind":"sa","stem":"△ ÷ 8 = □에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["△ ÷ 8 = □는 □ × 8 = △를 거꾸로 쓴 식이에요.","□가 9이면 9 × 8 = 72예요.","△는 72예요 — 72 ÷ 8 = 9로 식에도 맞아요."],"variant_rule":{"alt":[{"stem":"△ ÷ 9 = □에서 □가 7일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["△ ÷ 9 = □는 □ × 9 = △를 거꾸로 쓴 식이에요.","□가 7이면 7 × 9 = 63이에요.","△는 63이에요 — 63 ÷ 9 = 7로 식에도 맞아요."]},{"stem":"△ ÷ 6 = □에서 □가 13일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["78"],"explanation":["△ ÷ 6 = □는 □ × 6 = △를 거꾸로 쓴 식이에요.","□가 13이면 13 × 6 = 78이에요.","△는 78이에요 — 78 ÷ 6 = 13으로 식에도 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#6','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C4',3,'mc','auto','「△는 □보다 7 적어요.」를 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X02']::text[],true,'{"seq":6,"concept":"M5-1-u4-C4","difficulty":3,"kind":"mc","stem":"「△는 □보다 7 적어요.」를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ − 7 = △","correct":true},{"t":"□ + 7 = △","mis":"M5-1-u4-X04"},{"t":"△ − 7 = □","mis":"M5-1-u4-X04"},{"t":"□ × 7 = △","mis":"M5-1-u4-X02"}],"explanation":["△가 □에서 어떻게 오는지 말에서 찾아요 — △는 □보다 7 적어요.","□에서 7을 빼면 △가 돼요.","그래서 식은 □ − 7 = △예요."],"variant_rule":{"alt":[{"stem":"「△는 □의 9배예요.」를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ × 9 = △","correct":true},{"t":"□ − 9 = △","mis":"M5-1-u4-X04"},{"t":"△ × 9 = □","mis":"M5-1-u4-X04"},{"t":"□ + 9 = △","mis":"M5-1-u4-X02"}],"explanation":["△가 □에서 어떻게 오는지 말에서 찾아요 — △는 □의 9배예요.","□에 9를 곱하면 △가 돼요.","그래서 식은 □ × 9 = △예요."]},{"stem":"「△는 □보다 12 많아요.」를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ + 12 = △","correct":true},{"t":"□ − 12 = △","mis":"M5-1-u4-X04"},{"t":"△ + 12 = □","mis":"M5-1-u4-X04"},{"t":"□ × 12 = △","mis":"M5-1-u4-X02"}],"explanation":["△가 □에서 어떻게 오는지 말에서 찾아요 — △는 □보다 12 많아요.","□에 12를 더하면 △가 돼요.","그래서 식은 □ + 12 = △예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#7','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C4',3,'ox','auto','□ × 4 = △라는 식만 보아도 □와 △가 무엇을 가리키는지 알 수 있어요.',ARRAY['M5-1-u4-X06']::text[],true,'{"seq":7,"concept":"M5-1-u4-C4","difficulty":3,"kind":"ox","stem":"□ × 4 = △라는 식만 보아도 □와 △가 무엇을 가리키는지 알 수 있어요.","answer":"X","reason_options":[{"t":"자동차와 바퀴, 의자와 다리처럼 여러 상황이 같은 식이 되어 기호의 뜻을 먼저 정해야 하므로","correct":true},{"t":"곱하는 수 4를 보면 언제나 자동차 바퀴임을 알 수 있으므로","mis":"M5-1-u4-X06"}],"mis":"M5-1-u4-X06","explanation":["자동차 수와 바퀴 수도, 의자 수와 다리 수도 □ × 4 = △예요.","식만 보아서는 □가 무엇인지 알 수 없어요.","그래서 기호가 무엇을 가리키는지 먼저 정해야 해요."],"variant_rule":{"alt":[{"stem":"원호 나이를 □, 동생 나이를 △라고 정했다면 「동생은 원호보다 3살 적다」는 □ − 3 = △로 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"□(원호 나이)에서 3을 빼면 △(동생 나이)가 되므로","correct":true},{"t":"동생이 적으니 △ − 3 = □로 써야 하므로","mis":"M5-1-u4-X04"}],"explanation":["□는 원호 나이, △는 동생 나이로 정했어요.","원호 나이에서 3을 빼면 동생 나이예요.","그래서 □ − 3 = △ — △ + 3 = □로 써도 같은 관계예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#8','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C4',4,'sa','auto','□ − 4 = △이고 □와 △를 더하면 30이에요. □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u4-C4","difficulty":4,"kind":"sa","stem":"□ − 4 = △이고 □와 △를 더하면 30이에요. □는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["△는 □보다 4 작아서 □ + △에 4를 더하면 □의 2배예요.","30 + 4 = 34, 34 ÷ 2 = 17이에요.","□ = 17, △ = 17 − 4 = 13 — 17 + 13 = 30으로 맞아요."],"variant_rule":{"alt":[{"stem":"□ − 6 = △이고 □와 △를 더하면 40이에요. □는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["△는 □보다 6 작아서 □ + △에 6을 더하면 □의 2배예요.","40 + 6 = 46, 46 ÷ 2 = 23이에요.","□ = 23, △ = 23 − 6 = 17 — 23 + 17 = 40으로 맞아요."]},{"stem":"□ − 8 = △이고 □와 △를 더하면 52예요. □는 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["△는 □보다 8 작아서 □ + △에 8을 더하면 □의 2배예요.","52 + 8 = 60, 60 ÷ 2 = 30이에요.","□ = 30, △ = 30 − 8 = 22 — 30 + 22 = 52로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#9','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C4',4,'essay','teacher','원호 나이를 □, 동생 나이를 △라고 할 때 「원호는 동생보다 3살 많다」를 식 두 가지로 나타내고, 두 식이 같은 관계인 까닭을 수를 넣어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u4-C4","difficulty":4,"kind":"essay","stem":"원호 나이를 □, 동생 나이를 △라고 할 때 「원호는 동생보다 3살 많다」를 식 두 가지로 나타내고, 두 식이 같은 관계인 까닭을 수를 넣어 설명하세요.","answer_guide":{"answer":"예: □ − 3 = △, △ + 3 = □로 나타낼 수 있다. 원호가 12살이면 □ − 3 = △에서 동생은 12 − 3 = 9살이고, △ + 3 = □에 9를 넣으면 9 + 3 = 12로 원호 나이가 나온다. 두 식이 같은 짝을 내므로 같은 관계를 반대 방향에서 쓴 것이다.","scoring_points":["□ − 3 = △를 바르게 썼는가","△ + 3 = □를 바르게 썼는가","수를 넣어 두 식이 같은 짝을 낸다고 설명했는가"]},"explanation":["원호 나이에서 3을 빼면 동생 나이 — □ − 3 = △예요.","동생 나이에 3을 더하면 원호 나이 — △ + 3 = □예요.","12와 9처럼 같은 짝을 내니 같은 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L03_challenge#10','math',5,1,'u4','L03','g5_1_math_u4_L03_challenge','lesson_challenge','M5-1-u4-C5',4,'essay','teacher','□ × 4 = △는 △ ÷ 4 = □로 바꾸어 쓸 수 있지만 □ ÷ 4 = △로는 바꿀 수 없어요. 그 까닭을 □ = 5를 넣어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u4-C5","difficulty":4,"kind":"essay","stem":"□ × 4 = △는 △ ÷ 4 = □로 바꾸어 쓸 수 있지만 □ ÷ 4 = △로는 바꿀 수 없어요. 그 까닭을 □ = 5를 넣어 설명하세요.","answer_guide":{"answer":"예: □ × 4 = △에 □ = 5를 넣으면 △ = 20이다. △ ÷ 4 = □에 20을 넣으면 20 ÷ 4 = 5로 같은 짝이 나온다. 하지만 □ ÷ 4 = △에 □ = 5를 넣으면 △가 20이 되지 않으므로 다른 관계이다.","scoring_points":["□ = 5일 때 △ = 20을 구했는가","△ ÷ 4 = □가 같은 짝을 낸다고 썼는가","□ ÷ 4 = △는 같은 짝을 내지 않는다고 썼는가"]},"explanation":["□ × 4 = △에서 □ = 5이면 △ = 20이에요.","20 ÷ 4 = 5 — △ ÷ 4 = □는 같은 짝이에요.","□ ÷ 4 = △는 5에서 20이 나오지 않아 다른 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#1','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',1,'mc','auto','□ × 6 = △에서 □가 7일 때 △는 얼마인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X12']::text[],true,'{"seq":1,"concept":"M5-1-u4-C6","difficulty":1,"kind":"mc","stem":"□ × 6 = △에서 □가 7일 때 △는 얼마인가요?","options":[{"t":"42","correct":true},{"t":"13","mis":"M5-1-u4-X02"},{"t":"48","mis":"M5-1-u4-X12"},{"t":"36","mis":"M5-1-u4-X12"}],"explanation":["□ 자리에 7을 넣어요.","7 × 6 = 42예요.","△는 42예요."],"variant_rule":{"alt":[{"stem":"□ × 8 = △에서 □가 6일 때 △는 얼마인가요?","options":[{"t":"48","correct":true},{"t":"14","mis":"M5-1-u4-X02"},{"t":"56","mis":"M5-1-u4-X12"},{"t":"40","mis":"M5-1-u4-X12"}],"explanation":["□ 자리에 6을 넣어요.","6 × 8 = 48이에요.","△는 48이에요."]},{"stem":"□ × 9 = △에서 □가 4일 때 △는 얼마인가요?","options":[{"t":"36","correct":true},{"t":"13","mis":"M5-1-u4-X02"},{"t":"45","mis":"M5-1-u4-X12"},{"t":"27","mis":"M5-1-u4-X12"}],"explanation":["□ 자리에 4를 넣어요.","4 × 9 = 36이에요.","△는 36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#2','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',1,'sa','auto','□ × 7 = △에서 △가 63일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ × 7 = △에서 △가 63일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△ 자리에 63이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","63 ÷ 7 = 9예요.","□는 9예요. 9 × 7 = 63으로 확인해요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △에서 △가 54일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△ 자리에 54가 오도록 □를 찾아요 — 되돌리는 셈을 해요.","54 ÷ 6 = 9예요.","□는 9예요. 9 × 6 = 54로 확인해요."]},{"stem":"□ × 8 = △에서 △가 72일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△ 자리에 72가 오도록 □를 찾아요 — 되돌리는 셈을 해요.","72 ÷ 8 = 9예요.","□는 9예요. 9 × 8 = 72로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#3','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',1,'mc','auto','□ + 5 = △에서 □가 20일 때 △는 얼마인가요?',ARRAY['M5-1-u4-X07','M5-1-u4-X02','M5-1-u4-X13']::text[],true,'{"seq":3,"concept":"M5-1-u4-C6","difficulty":1,"kind":"mc","stem":"□ + 5 = △에서 □가 20일 때 △는 얼마인가요?","options":[{"t":"25","correct":true},{"t":"15","mis":"M5-1-u4-X07"},{"t":"100","mis":"M5-1-u4-X02"},{"t":"20","mis":"M5-1-u4-X13"}],"explanation":["□ 자리에 20을 넣어요.","20 + 5 = 25예요.","△는 25예요."],"variant_rule":{"alt":[{"stem":"□ + 8 = △에서 □가 15일 때 △는 얼마인가요?","options":[{"t":"23","correct":true},{"t":"7","mis":"M5-1-u4-X07"},{"t":"120","mis":"M5-1-u4-X02"},{"t":"15","mis":"M5-1-u4-X13"}],"explanation":["□ 자리에 15를 넣어요.","15 + 8 = 23이에요.","△는 23이에요."]},{"stem":"□ − 6 = △에서 □가 30일 때 △는 얼마인가요?","options":[{"t":"24","correct":true},{"t":"36","mis":"M5-1-u4-X07"},{"t":"30","mis":"M5-1-u4-X13"},{"t":"23","mis":"M5-1-u4-X12"}],"explanation":["□ 자리에 30을 넣어요.","30 − 6 = 24예요.","△는 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#4','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',1,'mc','auto','우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 150개의 줄은 모두 몇 개인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],true,'{"seq":4,"concept":"M5-1-u4-C6","difficulty":1,"kind":"mc","stem":"우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 150개의 줄은 모두 몇 개인가요?","options":[{"t":"600개","correct":true},{"t":"154개","mis":"M5-1-u4-X02"},{"t":"604개","mis":"M5-1-u4-X09"},{"t":"6000개","mis":"M5-1-u4-X12"}],"explanation":["줄 수는 우쿨렐레 수의 4배예요 — 표를 150칸까지 그리지 않아도 돼요.","150 × 4 = 600이에요.","우쿨렐레 150개의 줄은 600개예요."],"variant_rule":{"alt":[{"stem":"자동차 한 대에는 바퀴가 4개 있어요. 자동차 120대의 바퀴는 모두 몇 개인가요?","options":[{"t":"480개","correct":true},{"t":"124개","mis":"M5-1-u4-X02"},{"t":"484개","mis":"M5-1-u4-X09"},{"t":"4800개","mis":"M5-1-u4-X12"}],"explanation":["바퀴 수는 자동차 수의 4배예요 — 표를 120칸까지 그리지 않아도 돼요.","120 × 4 = 480이에요.","자동차 120대의 바퀴는 480개예요."]},{"stem":"곤충 한 마리의 다리는 6개예요. 곤충 110마리의 다리는 모두 몇 개인가요?","options":[{"t":"660개","correct":true},{"t":"116개","mis":"M5-1-u4-X02"},{"t":"666개","mis":"M5-1-u4-X09"},{"t":"6600개","mis":"M5-1-u4-X12"}],"explanation":["다리 수는 곤충 수의 6배예요 — 표를 110칸까지 그리지 않아도 돼요.","110 × 6 = 660이에요.","곤충 110마리의 다리는 660개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#5','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',2,'mc','auto','의자 하나에는 다리가 4개 있어요. 의자 다리가 모두 100개라면 의자는 몇 개인가요?',ARRAY['M5-1-u4-X07','M5-1-u4-X02','M5-1-u4-X12']::text[],true,'{"seq":5,"concept":"M5-1-u4-C6","difficulty":2,"kind":"mc","stem":"의자 하나에는 다리가 4개 있어요. 의자 다리가 모두 100개라면 의자는 몇 개인가요?","options":[{"t":"25개","correct":true},{"t":"400개","mis":"M5-1-u4-X07"},{"t":"96개","mis":"M5-1-u4-X02"},{"t":"20개","mis":"M5-1-u4-X12"}],"explanation":["다리 수는 의자 수의 4배예요.","다리 수를 알고 의자 수를 구하니 되돌리는 셈 — 100 ÷ 4 = 25예요.","의자는 25개예요."],"variant_rule":{"alt":[{"stem":"자동차 한 대에는 바퀴가 4개 있어요. 바퀴가 모두 96개라면 자동차는 몇 대인가요?","options":[{"t":"24대","correct":true},{"t":"384대","mis":"M5-1-u4-X07"},{"t":"92대","mis":"M5-1-u4-X02"},{"t":"26대","mis":"M5-1-u4-X12"}],"explanation":["바퀴 수는 자동차 수의 4배예요.","바퀴 수를 알고 자동차 수를 구하니 되돌리는 셈 — 96 ÷ 4 = 24예요.","자동차는 24대예요."]},{"stem":"꿀벌 한 마리의 다리는 6개예요. 꿀벌의 다리가 모두 90개라면 꿀벌은 몇 마리인가요?","options":[{"t":"15마리","correct":true},{"t":"540마리","mis":"M5-1-u4-X07"},{"t":"84마리","mis":"M5-1-u4-X02"},{"t":"13마리","mis":"M5-1-u4-X12"}],"explanation":["다리 수는 꿀벌 수의 6배예요.","다리 수를 알고 꿀벌 수를 구하니 되돌리는 셈 — 90 ÷ 6 = 15예요.","꿀벌은 15마리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#6','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',2,'sa','auto','□ − 4 = △에서 △가 24일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u4-C6","difficulty":2,"kind":"sa","stem":"□ − 4 = △에서 △가 24일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["△ 자리에 24가 오도록 □를 찾아요 — 되돌리는 셈을 해요.","24 + 4 = 28이에요.","□는 28이에요. 28 − 4 = 24로 확인해요."],"variant_rule":{"alt":[{"stem":"□ − 9 = △에서 △가 31일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["△ 자리에 31이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","31 + 9 = 40이에요.","□는 40이에요. 40 − 9 = 31로 확인해요."]},{"stem":"□ + 7 = △에서 △가 40일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["△ 자리에 40이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","40 − 7 = 33이에요.","□는 33이에요. 33 + 7 = 40으로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#7','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',2,'mc','auto','□ × 3 = △에서 □가 1씩 늘어나면 △는 어떻게 되나요?',ARRAY['M5-1-u4-X03','M5-1-u4-X02','M5-1-u4-X05']::text[],true,'{"seq":7,"concept":"M5-1-u4-C6","difficulty":2,"kind":"mc","stem":"□ × 3 = △에서 □가 1씩 늘어나면 △는 어떻게 되나요?","options":[{"t":"3씩 늘어난다","correct":true},{"t":"1씩 늘어난다","mis":"M5-1-u4-X03"},{"t":"3배씩 늘어난다","mis":"M5-1-u4-X02"},{"t":"그대로다","mis":"M5-1-u4-X05"}],"explanation":["□에 4, 5, 6을 차례로 넣어 보아요.","△는 12, 15, 18 — 3씩 늘어나요.","□가 1 늘면 곱한 3만큼 △가 늘어요."],"variant_rule":{"alt":[{"stem":"□ × 5 = △에서 □가 1씩 늘어나면 △는 어떻게 되나요?","options":[{"t":"5씩 늘어난다","correct":true},{"t":"1씩 늘어난다","mis":"M5-1-u4-X03"},{"t":"5배씩 늘어난다","mis":"M5-1-u4-X02"},{"t":"그대로다","mis":"M5-1-u4-X05"}],"explanation":["□에 4, 5, 6을 차례로 넣어 보아요.","△는 20, 25, 30 — 5씩 늘어나요.","□가 1 늘면 곱한 5만큼 △가 늘어요."]},{"stem":"□ + 6 = △에서 □가 1씩 늘어나면 △는 어떻게 되나요?","options":[{"t":"1씩 늘어난다","correct":true},{"t":"6배씩 늘어난다","mis":"M5-1-u4-X02"},{"t":"그대로다","mis":"M5-1-u4-X05"},{"t":"6씩 늘어난다","mis":"M5-1-u4-X02"}],"explanation":["□에 4, 5, 6을 차례로 넣어 보아요.","△는 10, 11, 12 — 1씩 늘어나요.","더하거나 뺀 수는 그대로라 △도 □처럼 1씩 늘어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#8','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',2,'sa','auto','한 상자에 공책이 12권씩 들어 있어요. 공책 156권은 몇 상자인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u4-C6","difficulty":2,"kind":"sa","stem":"한 상자에 공책이 12권씩 들어 있어요. 공책 156권은 몇 상자인가요? 숫자로 쓰세요.","answer":["13","13상자"],"explanation":["공책 수는 상자 수의 12배예요.","거꾸로 가려면 12로 나누어요 — 156 ÷ 12 = 13.","공책 156권은 13상자예요."],"variant_rule":{"alt":[{"stem":"한 상자에 공책이 12권씩 들어 있어요. 공책 180권은 몇 상자인가요? 숫자로 쓰세요.","answer":["15","15상자"],"explanation":["공책 수는 상자 수의 12배예요.","거꾸로 가려면 12로 나누어요 — 180 ÷ 12 = 15.","공책 180권은 15상자예요."]},{"stem":"1주일은 7일이에요. 98일은 몇 주일인가요? 숫자로 쓰세요.","answer":["14","14주일"],"explanation":["날 수는 주 수의 7배예요.","거꾸로 가려면 7로 나누어요 — 98 ÷ 7 = 14.","98일은 14주일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#9','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',2,'ox','auto','우쿨렐레 수와 줄 수의 표에 우쿨렐레 1개부터 5개까지만 있으면 우쿨렐레 100개의 줄 수는 구할 수 없어요.',ARRAY['M5-1-u4-X09']::text[],true,'{"seq":9,"concept":"M5-1-u4-C6","difficulty":2,"kind":"ox","stem":"우쿨렐레 수와 줄 수의 표에 우쿨렐레 1개부터 5개까지만 있으면 우쿨렐레 100개의 줄 수는 구할 수 없어요.","answer":"X","reason_options":[{"t":"식 □ × 4 = △에 100을 넣으면 표 밖의 값도 구할 수 있으므로","correct":true},{"t":"표에 없는 값은 알 수 없으므로","mis":"M5-1-u4-X09"}],"mis":"M5-1-u4-X09","explanation":["표의 짝에서 식 □ × 4 = △를 찾아요.","□ 자리에 100을 넣으면 100 × 4 = 400이에요.","식은 표를 끝없이 늘려 놓은 것이라 표 밖의 값도 답해요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △라는 식을 알면 표를 그리지 않아도 □가 50일 때 △를 구할 수 있어요.","answer":"O","reason_options":[{"t":"□ 자리에 50을 넣어 50 × 6 = 300으로 구하므로","correct":true},{"t":"표를 50칸까지 그려야 알 수 있으므로","mis":"M5-1-u4-X09"}],"explanation":["□ 자리에 50을 넣어요.","50 × 6 = 300이에요.","식이 있으면 표 없이 한 번에 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_basic#10','math',5,1,'u4','L04','g5_1_math_u4_L04_basic','lesson_basic','M5-1-u4-C6',3,'sa','auto','□ × 4 = △에서 △가 □보다 36 크다고 해요. □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-1-u4-C6","difficulty":3,"kind":"sa","stem":"□ × 4 = △에서 △가 □보다 36 크다고 해요. □는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["△는 □의 4배 — △에서 □를 빼면 □의 3배가 남아요.","36 ÷ 3 = 12예요.","□ = 12, △ = 12 × 4 = 48 — 48 − 12 = 36으로 맞아요."],"variant_rule":{"alt":[{"stem":"□ × 5 = △에서 △가 □보다 48 크다고 해요. □는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["△는 □의 5배 — △에서 □를 빼면 □의 4배가 남아요.","48 ÷ 4 = 12예요.","□ = 12, △ = 12 × 5 = 60 — 60 − 12 = 48로 맞아요."]},{"stem":"□ × 3 = △에서 △가 □보다 26 크다고 해요. □는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["△는 □의 3배 — △에서 □를 빼면 □의 2배가 남아요.","26 ÷ 2 = 13이에요.","□ = 13, △ = 13 × 3 = 39 — 39 − 13 = 26으로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#1','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',2,'error','auto','□ × 7 = △에서 △가 63일 때 □를 구한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u4-X07','M5-1-u4-X13']::text[],true,'{"seq":1,"concept":"M5-1-u4-C6","difficulty":2,"kind":"error","stem":"□ × 7 = △에서 △가 63일 때 □를 구한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「63 × 7 = 441이니 □는 441이야.」","correct":true,"mis_target":"M5-1-u4-X07"},{"t":"도윤 — 「63 ÷ 7 = 9 — □는 9야.」","mis":"M5-1-u4-X13"},{"t":"하린 — 「□가 9이면 9 × 7 = 63으로 맞아.」","mis":"M5-1-u4-X13"}],"explanation":["△를 알고 □를 구할 때는 되돌리는 셈을 해요.","63 ÷ 7 = 9 — □는 9예요.","서윤은 같은 셈을 또 해서 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △에서 △가 48일 때 □를 구한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「48 × 6 = 288이니 □는 288이야.」","correct":true,"mis_target":"M5-1-u4-X07"},{"t":"하람 — 「48 ÷ 6 = 8 — □는 8이야.」","mis":"M5-1-u4-X13"},{"t":"은우 — 「□가 8이면 8 × 6 = 48로 맞아.」","mis":"M5-1-u4-X13"}],"explanation":["△를 알고 □를 구할 때는 되돌리는 셈을 해요.","48 ÷ 6 = 8 — □는 8이에요.","지우는 같은 셈을 또 해서 잘못 말했어요."]},{"stem":"□ − 8 = △에서 △가 20일 때 □를 구한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나은 — 「20 − 8 = 12니 □는 12야.」","correct":true,"mis_target":"M5-1-u4-X07"},{"t":"시온 — 「20 + 8 = 28 — □는 28이야.」","mis":"M5-1-u4-X13"},{"t":"태린 — 「□가 28이면 28 − 8 = 20으로 맞아.」","mis":"M5-1-u4-X13"}],"explanation":["△를 알고 □를 구할 때는 되돌리는 셈을 해요.","20 + 8 = 28 — □는 28이에요.","나은은 같은 셈을 또 해서 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#2','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',2,'mc','auto','우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 수를 □, 줄 수를 △라고 하면 □ × 4 = △예요. 줄이 48개일 때 우쿨렐레 수를 구하는 셈은 어느 것인가요?',ARRAY['M5-1-u4-X06','M5-1-u4-X02']::text[],true,'{"seq":2,"concept":"M5-1-u4-C6","difficulty":2,"kind":"mc","stem":"우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 수를 □, 줄 수를 △라고 하면 □ × 4 = △예요. 줄이 48개일 때 우쿨렐레 수를 구하는 셈은 어느 것인가요?","options":[{"t":"48 ÷ 4","correct":true},{"t":"48 × 4","mis":"M5-1-u4-X06"},{"t":"48 − 4","mis":"M5-1-u4-X02"},{"t":"48 + 4","mis":"M5-1-u4-X02"}],"explanation":["줄 48은 △ 자리 수예요.","△를 알고 □를 구하니 곱셈을 나눗셈으로 되돌려요.","48 ÷ 4 = 12 — 우쿨렐레 수는 12예요."],"variant_rule":{"alt":[{"stem":"자동차 한 대에는 바퀴가 4개 있어요. 자동차 수를 □, 바퀴 수를 △라고 하면 □ × 4 = △예요. 바퀴가 64개일 때 자동차 수를 구하는 셈은 어느 것인가요?","options":[{"t":"64 ÷ 4","correct":true},{"t":"64 × 4","mis":"M5-1-u4-X06"},{"t":"64 − 4","mis":"M5-1-u4-X02"},{"t":"64 + 4","mis":"M5-1-u4-X02"}],"explanation":["바퀴 64는 △ 자리 수예요.","△를 알고 □를 구하니 곱셈을 나눗셈으로 되돌려요.","64 ÷ 4 = 16 — 자동차 수는 16이에요."]},{"stem":"의자 하나에는 다리가 4개 있어요. 의자 수를 □, 다리 수를 △라고 하면 □ × 4 = △예요. 다리가 52개일 때 의자 수를 구하는 셈은 어느 것인가요?","options":[{"t":"52 ÷ 4","correct":true},{"t":"52 × 4","mis":"M5-1-u4-X06"},{"t":"52 − 4","mis":"M5-1-u4-X02"},{"t":"52 + 4","mis":"M5-1-u4-X02"}],"explanation":["다리 52는 △ 자리 수예요.","△를 알고 □를 구하니 곱셈을 나눗셈으로 되돌려요.","52 ÷ 4 = 13 — 의자 수는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#3','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',3,'sa','auto','연필 한 개에 400원이에요. 7200원으로 연필을 몇 개 살 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u4-C6","difficulty":3,"kind":"sa","stem":"연필 한 개에 400원이에요. 7200원으로 연필을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["18","18개"],"explanation":["연필 수를 □, 값을 △라고 하면 □ × 400 = △예요.","△가 7200이니 되돌려 나누어요 — 7200 ÷ 400 = 18.","연필 18개를 살 수 있어요."],"variant_rule":{"alt":[{"stem":"지우개 한 개에 500원이에요. 9500원으로 지우개를 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["19","19개"],"explanation":["지우개 수를 □, 값을 △라고 하면 □ × 500 = △예요.","△가 9500이니 되돌려 나누어요 — 9500 ÷ 500 = 19.","지우개 19개를 살 수 있어요."]},{"stem":"공책 한 개에 600원이에요. 9000원으로 공책을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["15","15개"],"explanation":["공책 수를 □, 값을 △라고 하면 □ × 600 = △예요.","△가 9000이니 되돌려 나누어요 — 9000 ÷ 600 = 15.","공책 15개를 살 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#4','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',3,'sa','auto','□ × 6 = △에서 □가 9일 때와 13일 때 △의 차는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u4-C6","difficulty":3,"kind":"sa","stem":"□ × 6 = △에서 □가 9일 때와 13일 때 △의 차는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["□가 9이면 △ = 9 × 6 = 54, □가 13이면 △ = 13 × 6 = 78이에요.","78 − 54 = 24예요.","□가 4 늘었으니 △는 4 × 6 = 24만큼 늘었어요."],"variant_rule":{"alt":[{"stem":"□ × 7 = △에서 □가 8일 때와 12일 때 △의 차는 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["□가 8이면 △ = 8 × 7 = 56, □가 12이면 △ = 12 × 7 = 84예요.","84 − 56 = 28이에요.","□가 4 늘었으니 △는 4 × 7 = 28만큼 늘었어요."]},{"stem":"□ × 9 = △에서 □가 5일 때와 11일 때 △의 차는 얼마인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["□가 5이면 △ = 5 × 9 = 45, □가 11이면 △ = 11 × 9 = 99예요.","99 − 45 = 54예요.","□가 6 늘었으니 △는 6 × 9 = 54만큼 늘었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#5','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',3,'mc','auto','가 기계는 □를 넣으면 □ × 5 = △를, 나 기계는 □를 넣으면 □ + 20 = △를 내놓아요. 두 기계에 4를 넣었을 때 △가 더 큰 기계는 어느 것인가요?',ARRAY['M5-1-u4-X12','M5-1-u4-X09']::text[],true,'{"seq":5,"concept":"M5-1-u4-C6","difficulty":3,"kind":"mc","stem":"가 기계는 □를 넣으면 □ × 5 = △를, 나 기계는 □를 넣으면 □ + 20 = △를 내놓아요. 두 기계에 4를 넣었을 때 △가 더 큰 기계는 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M5-1-u4-X12"},{"t":"두 기계가 같다","mis":"M5-1-u4-X12"},{"t":"넣는 수를 몰라 견줄 수 없다","mis":"M5-1-u4-X09"}],"explanation":["가: 4 × 5 = 20이에요.","나: 4 + 20 = 24예요.","나 기계의 △가 더 커요."],"variant_rule":{"alt":[{"stem":"가 기계는 □를 넣으면 □ × 3 = △를, 나 기계는 □를 넣으면 □ + 18 = △를 내놓아요. 두 기계에 9를 넣었을 때 △가 더 큰 기계는 어느 것인가요?","options":[{"t":"두 기계가 같다","correct":true},{"t":"가","mis":"M5-1-u4-X12"},{"t":"나","mis":"M5-1-u4-X12"},{"t":"넣는 수를 몰라 견줄 수 없다","mis":"M5-1-u4-X09"}],"explanation":["가: 9 × 3 = 27이에요.","나: 9 + 18 = 27이에요.","두 기계의 △가 같아요."]},{"stem":"가 기계는 □를 넣으면 □ × 6 = △를, 나 기계는 □를 넣으면 □ + 25 = △를 내놓아요. 두 기계에 5를 넣었을 때 △가 더 큰 기계는 어느 것인가요?","options":[{"t":"두 기계가 같다","correct":true},{"t":"가","mis":"M5-1-u4-X12"},{"t":"나","mis":"M5-1-u4-X12"},{"t":"넣는 수를 몰라 견줄 수 없다","mis":"M5-1-u4-X09"}],"explanation":["가: 5 × 6 = 30이에요.","나: 5 + 25 = 30이에요.","두 기계의 △가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#6','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',3,'sa','auto','□ × 12 = △에서 △가 96일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u4-C6","difficulty":3,"kind":"sa","stem":"□ × 12 = △에서 △가 96일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 96이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","96 ÷ 12 = 8이에요.","□는 8이에요. 8 × 12 = 96으로 확인해요."],"variant_rule":{"alt":[{"stem":"□ × 15 = △에서 △가 90일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["△ 자리에 90이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","90 ÷ 15 = 6이에요.","□는 6이에요. 6 × 15 = 90으로 확인해요."]},{"stem":"□ × 11 = △에서 △가 88일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 88이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","88 ÷ 11 = 8이에요.","□는 8이에요. 8 × 11 = 88로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#7','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',3,'ox','auto','□ − 8 = △에서 △가 20이면 □는 20 − 8 = 12예요.',ARRAY['M5-1-u4-X07']::text[],true,'{"seq":7,"concept":"M5-1-u4-C6","difficulty":3,"kind":"ox","stem":"□ − 8 = △에서 △가 20이면 □는 20 − 8 = 12예요.","answer":"X","reason_options":[{"t":"△를 알고 □를 구할 때는 되돌려 20 + 8 = 28로 구해야 하므로","correct":true},{"t":"식에 − 가 있으니 그대로 빼면 되므로","mis":"M5-1-u4-X07"}],"mis":"M5-1-u4-X07","explanation":["□에서 8을 빼서 20이 되었어요.","되돌리면 20 + 8 = 28 — □는 28이에요.","28 − 8 = 20으로 확인해요."],"variant_rule":{"alt":[{"stem":"□ × 5 = △에서 △가 45이면 □는 45 ÷ 5 = 9예요.","answer":"O","reason_options":[{"t":"곱셈으로 갔으니 나눗셈으로 되돌려 구하므로","correct":true},{"t":"식에 × 가 있으니 45 × 5로 구해야 하므로","mis":"M5-1-u4-X07"}],"explanation":["□에 5를 곱해 45가 되었어요.","되돌리면 45 ÷ 5 = 9예요.","9 × 5 = 45로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#8','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',4,'sa','auto','□ × 3 = △이고 □ + △ = 64예요. △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u4-C6","difficulty":4,"kind":"sa","stem":"□ × 3 = △이고 □ + △ = 64예요. △는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["□ + △는 □의 4배예요.","□ = 64 ÷ 4 = 16이에요.","△ = 16 × 3 = 48 — 묻는 것은 △라서 48이에요."],"variant_rule":{"alt":[{"stem":"□ × 4 = △이고 □ + △ = 75예요. △는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["□ + △는 □의 5배예요.","□ = 75 ÷ 5 = 15예요.","△ = 15 × 4 = 60 — 묻는 것은 △라서 60이에요."]},{"stem":"□ × 5 = △이고 □ + △ = 84예요. △는 얼마인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["□ + △는 □의 6배예요.","□ = 84 ÷ 6 = 14예요.","△ = 14 × 5 = 70 — 묻는 것은 △라서 70이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#9','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',4,'sa','auto','□ × 4 = △이고 △ + 6 = ○예요. □가 8일 때 ○는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u4-C6","difficulty":4,"kind":"sa","stem":"□ × 4 = △이고 △ + 6 = ○예요. □가 8일 때 ○는 얼마인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["먼저 △를 구해요 — 8 × 4 = 32.","그 △를 다음 식에 넣어요 — 32 + 6 = 38.","○는 38이에요."],"variant_rule":{"alt":[{"stem":"□ × 6 = △이고 △ + 9 = ○예요. □가 7일 때 ○는 얼마인가요? 숫자로 쓰세요.","answer":["51"],"explanation":["먼저 △를 구해요 — 7 × 6 = 42.","그 △를 다음 식에 넣어요 — 42 + 9 = 51.","○는 51이에요."]},{"stem":"□ × 3 = △이고 △ + 15 = ○예요. □가 9일 때 ○는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["먼저 △를 구해요 — 9 × 3 = 27.","그 △를 다음 식에 넣어요 — 27 + 15 = 42.","○는 42예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L04_challenge#10','math',5,1,'u4','L04','g5_1_math_u4_L04_challenge','lesson_challenge','M5-1-u4-C6',4,'essay','teacher','우쿨렐레 수를 □, 줄 수를 △라고 하면 □ × 4 = △예요. 줄이 48개일 때 우쿨렐레 수를 구하는 방법을 쓰고, 왜 그렇게 셈하는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u4-C6","difficulty":4,"kind":"essay","stem":"우쿨렐레 수를 □, 줄 수를 △라고 하면 □ × 4 = △예요. 줄이 48개일 때 우쿨렐레 수를 구하는 방법을 쓰고, 왜 그렇게 셈하는지 설명하세요.","answer_guide":{"answer":"예: 48은 줄 수이므로 △ 자리 수이다. □에 4를 곱해 △가 되었으니 거꾸로 △를 4로 나누면 □가 된다. 48 ÷ 4 = 12이므로 우쿨렐레는 12개이고, 12 × 4 = 48로 확인할 수 있다.","scoring_points":["48이 △ 자리 수임을 알았는가","곱셈을 나눗셈으로 되돌린다고 썼는가","48 ÷ 4 = 12로 구하고 확인했는가"]},"explanation":["48은 줄 수 — △ 자리예요.","곱셈으로 왔으니 나눗셈으로 되돌려요 — 48 ÷ 4 = 12.","12 × 4 = 48로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#1','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',1,'mc','auto','□ × 2 = △로 나타낼 수 있는 두 양은 어느 것인가요?',ARRAY['M5-1-u4-X10']::text[],true,'{"seq":1,"concept":"M5-1-u4-C7","difficulty":1,"kind":"mc","stem":"□ × 2 = △로 나타낼 수 있는 두 양은 어느 것인가요?","options":[{"t":"자전거 수와 바퀴 수","correct":true},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X10"},{"t":"달걀판 수와 달걀 수(한 판에 10개)","mis":"M5-1-u4-X10"},{"t":"사각형 수와 변의 수","mis":"M5-1-u4-X10"}],"explanation":["하나에 몇 개씩인지 보아요 — 「삼각형 수와 변의 수」는 하나에 3개씩 · 「달걀판 수와 달걀 수(한 판에 10개)」는 하나에 10개씩 · 「사각형 수와 변의 수」는 하나에 4개씩.","「자전거 수와 바퀴 수」는 하나에 2개씩이에요.","그래서 □ × 2 = △로 나타낼 수 있는 것은 「자전거 수와 바퀴 수」예요."],"variant_rule":{"alt":[{"stem":"□ × 4 = △로 나타낼 수 있는 두 양은 어느 것인가요?","options":[{"t":"의자 수와 의자 다리 수","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X10"},{"t":"곤충 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X10"}],"explanation":["하나에 몇 개씩인지 보아요 — 「자전거 수와 바퀴 수」는 하나에 2개씩 · 「곤충 수와 다리 수」는 하나에 6개씩 · 「삼각형 수와 변의 수」는 하나에 3개씩.","「의자 수와 의자 다리 수」는 하나에 4개씩이에요.","그래서 □ × 4 = △로 나타낼 수 있는 것은 「의자 수와 의자 다리 수」예요."]},{"stem":"□ × 7 = △로 나타낼 수 있는 두 양은 어느 것인가요?","options":[{"t":"주 수와 날 수","correct":true},{"t":"문어 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"곤충 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"오각형 수와 꼭짓점 수","mis":"M5-1-u4-X10"}],"explanation":["하나에 몇 개씩인지 보아요 — 「문어 수와 다리 수」는 하나에 8개씩 · 「곤충 수와 다리 수」는 하나에 6개씩 · 「오각형 수와 꼭짓점 수」는 하나에 5개씩.","「주 수와 날 수」는 하나에 7개씩이에요.","그래서 □ × 7 = △로 나타낼 수 있는 것은 「주 수와 날 수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#2','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',1,'sa','auto','삼각형 하나의 변은 3개예요. 삼각형 8개의 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C7","difficulty":1,"kind":"sa","stem":"삼각형 하나의 변은 3개예요. 삼각형 8개의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24","24개"],"explanation":["삼각형이 하나 늘 때마다 변 수는 3씩 늘어요 — 변의 수는 삼각형 수의 3배예요.","8 × 3 = 24예요.","삼각형 8개의 변은 24개예요."],"variant_rule":{"alt":[{"stem":"사각형 하나의 변은 4개예요. 사각형 9개의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["36","36개"],"explanation":["사각형이 하나 늘 때마다 변 수는 4씩 늘어요 — 변의 수는 사각형 수의 4배예요.","9 × 4 = 36이에요.","사각형 9개의 변은 36개예요."]},{"stem":"문어 한 마리의 다리는 8개예요. 문어 7마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["56","56개"],"explanation":["문어가 하나 늘 때마다 다리 수는 8씩 늘어요 — 다리 수는 문어 수의 8배예요.","7 × 8 = 56이에요.","문어 7마리의 다리는 56개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#3','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',1,'mc','auto','모둠 하나에 4명씩 앉아요. 모둠 수를 □, 사람 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],true,'{"seq":3,"concept":"M5-1-u4-C7","difficulty":1,"kind":"mc","stem":"모둠 하나에 4명씩 앉아요. 모둠 수를 □, 사람 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ − 4 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(사람 수)는 □(모둠 수)의 4배예요.","그 말을 그대로 옮기면 □ × 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."],"variant_rule":{"alt":[{"stem":"오각형 하나에 꼭짓점이 5개예요. 오각형 수를 □, 꼭짓점 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 5 = △","correct":true},{"t":"□ + 5 = △","mis":"M5-1-u4-X02"},{"t":"△ × 5 = □","mis":"M5-1-u4-X04"},{"t":"□ − 5 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(꼭짓점 수)는 □(오각형 수)의 5배예요.","그 말을 그대로 옮기면 □ × 5 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]},{"stem":"1주일은 7일이에요. 주 수를 □, 날 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 7 = △","correct":true},{"t":"□ + 7 = △","mis":"M5-1-u4-X02"},{"t":"△ × 7 = □","mis":"M5-1-u4-X04"},{"t":"□ − 7 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(날 수)는 □(주 수)의 7배예요.","그 말을 그대로 옮기면 □ × 7 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#4','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',1,'sa','auto','젓가락 한 벌은 2짝이에요. 젓가락 12짝은 몇 벌인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u4-C7","difficulty":1,"kind":"sa","stem":"젓가락 한 벌은 2짝이에요. 젓가락 12짝은 몇 벌인가요? 숫자로 쓰세요.","answer":["6","6벌"],"explanation":["짝 수는 벌 수의 2배예요.","거꾸로 가려면 2로 나누어요 — 12 ÷ 2 = 6.","젓가락 12짝은 6벌이에요."],"variant_rule":{"alt":[{"stem":"젓가락 한 벌은 2짝이에요. 젓가락 18짝은 몇 벌인가요? 숫자로 쓰세요.","answer":["9","9벌"],"explanation":["짝 수는 벌 수의 2배예요.","거꾸로 가려면 2로 나누어요 — 18 ÷ 2 = 9.","젓가락 18짝은 9벌이에요."]},{"stem":"자전거 한 대에는 바퀴가 2개 있어요. 자전거 바퀴가 모두 16개라면 자전거는 몇 대인가요? 숫자로 쓰세요.","answer":["8","8대"],"explanation":["바퀴 수는 자전거 수의 2배예요.","거꾸로 가려면 2로 나누어요 — 16 ÷ 2 = 8.","자전거는 8대예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#5','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],true,'{"seq":5,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"키와 좋아하는 색깔 수","correct":true},{"t":"의자 수와 의자 다리 수","mis":"M5-1-u4-X13"},{"t":"우유갑 수와 빨대 수(하나에 1개)","mis":"M5-1-u4-X13"},{"t":"상자 수와 담긴 사과 수(한 상자에 10개)","mis":"M5-1-u4-X13"}],"explanation":["의자 수와 의자 다리 수 · 우유갑 수와 빨대 수(하나에 1개) · 상자 수와 담긴 사과 수(한 상자에 10개) — 한 양이 정해지면 다른 양이 하나로 정해져요.","키와 좋아하는 색깔 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「키와 좋아하는 색깔 수」예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"신발 크기와 가진 공책 수","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X13"},{"t":"주 수와 날 수","mis":"M5-1-u4-X13"},{"t":"모둠 수와 사람 수(한 모둠에 4명)","mis":"M5-1-u4-X13"}],"explanation":["자전거 수와 바퀴 수 · 주 수와 날 수 · 모둠 수와 사람 수(한 모둠에 4명) — 한 양이 정해지면 다른 양이 하나로 정해져요.","신발 크기와 가진 공책 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「신발 크기와 가진 공책 수」예요."]},{"stem":"이번에는 다른 보기예요. 두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"오늘 기온과 반 친구 수","correct":true},{"t":"문어 수와 다리 수","mis":"M5-1-u4-X13"},{"t":"사람 수와 눈의 수","mis":"M5-1-u4-X13"},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X13"}],"explanation":["문어 수와 다리 수 · 사람 수와 눈의 수 · 삼각형 수와 변의 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","오늘 기온과 반 친구 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「오늘 기온과 반 친구 수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#6','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',2,'sa','auto','1주일은 7일이에요. 364일은 몇 주일인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u4-C7","difficulty":2,"kind":"sa","stem":"1주일은 7일이에요. 364일은 몇 주일인가요? 숫자로 쓰세요.","answer":["52","52주일"],"explanation":["날 수는 주 수의 7배예요.","거꾸로 가려면 7로 나누어요 — 364 ÷ 7 = 52.","364일은 52주일이에요."],"variant_rule":{"alt":[{"stem":"1주일은 7일이에요. 91일은 몇 주일인가요? 숫자로 쓰세요.","answer":["13","13주일"],"explanation":["날 수는 주 수의 7배예요.","거꾸로 가려면 7로 나누어요 — 91 ÷ 7 = 13.","91일은 13주일이에요."]},{"stem":"문어 한 마리의 다리는 8개예요. 문어의 다리가 모두 96개라면 문어는 몇 마리인가요? 숫자로 쓰세요.","answer":["12","12마리"],"explanation":["다리 수는 문어 수의 8배예요.","거꾸로 가려면 8로 나누어요 — 96 ÷ 8 = 12.","문어는 12마리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#7','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',2,'mc','auto','□ + 2 = △로 나타낼 수 있는 두 양은 어느 것인가요? (앞의 양이 □, 뒤의 양이 △예요.)',ARRAY['M5-1-u4-X04','M5-1-u4-X02']::text[],true,'{"seq":7,"concept":"M5-1-u4-C7","difficulty":2,"kind":"mc","stem":"□ + 2 = △로 나타낼 수 있는 두 양은 어느 것인가요? (앞의 양이 □, 뒤의 양이 △예요.)","options":[{"t":"동생 나이와 형 나이(형이 2살 많다)","correct":true},{"t":"형 나이와 동생 나이(형이 2살 많다)","mis":"M5-1-u4-X04"},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X02"},{"t":"상자 수와 사과 수(한 상자에 2개)","mis":"M5-1-u4-X02"}],"explanation":["□ + 2 = △는 △가 □보다 2 많다는 뜻이에요.","동생 나이 □에 2를 더하면 형 나이 △예요.","「2개씩」은 곱셈 관계라 □ × 2 = △예요."],"variant_rule":{"alt":[{"stem":"□ + 3 = △로 나타낼 수 있는 두 양은 어느 것인가요? (앞의 양이 □, 뒤의 양이 △예요.)","options":[{"t":"동생 나이와 형 나이(형이 3살 많다)","correct":true},{"t":"형 나이와 동생 나이(형이 3살 많다)","mis":"M5-1-u4-X04"},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X02"},{"t":"상자 수와 사과 수(한 상자에 3개)","mis":"M5-1-u4-X02"}],"explanation":["□ + 3 = △는 △가 □보다 3 많다는 뜻이에요.","동생 나이 □에 3을 더하면 형 나이 △예요.","「3개씩」은 곱셈 관계라 □ × 3 = △예요."]},{"stem":"□ + 4 = △로 나타낼 수 있는 두 양은 어느 것인가요? (앞의 양이 □, 뒤의 양이 △예요.)","options":[{"t":"동생 나이와 형 나이(형이 4살 많다)","correct":true},{"t":"형 나이와 동생 나이(형이 4살 많다)","mis":"M5-1-u4-X04"},{"t":"사각형 수와 변의 수","mis":"M5-1-u4-X02"},{"t":"상자 수와 사과 수(한 상자에 4개)","mis":"M5-1-u4-X02"}],"explanation":["□ + 4 = △는 △가 □보다 4 많다는 뜻이에요.","동생 나이 □에 4를 더하면 형 나이 △예요.","「4개씩」은 곱셈 관계라 □ × 4 = △예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#8','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C5',2,'mc','auto','□ × 5 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X08','M5-1-u4-X02']::text[],true,'{"seq":8,"concept":"M5-1-u4-C5","difficulty":2,"kind":"mc","stem":"□ × 5 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 5 = □","correct":true},{"t":"△ × 5 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 5 = △","mis":"M5-1-u4-X08"},{"t":"△ + 5 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 5 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 5 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 5 = 15, 거꾸로 15 ÷ 5 = 3으로 같은 짝이에요."],"variant_rule":{"alt":[{"stem":"□ × 7 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 7 = □","correct":true},{"t":"△ × 7 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 7 = △","mis":"M5-1-u4-X08"},{"t":"△ + 7 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 7 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 7 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 7 = 21, 거꾸로 21 ÷ 7 = 3으로 같은 짝이에요."]},{"stem":"□ + 9 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ − 9 = □","correct":true},{"t":"△ + 9 = □","mis":"M5-1-u4-X08"},{"t":"□ − 9 = △","mis":"M5-1-u4-X08"},{"t":"△ × 9 = □","mis":"M5-1-u4-X02"}],"explanation":["□ + 9 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ − 9 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 + 9 = 12, 거꾸로 12 − 9 = 3으로 같은 짝이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#9','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',2,'match','auto','상황과 대응 관계를 나타낸 식을 이으세요. (앞의 양이 □, 뒤의 양이 △예요.)','{}'::text[],true,'{"seq":9,"concept":"M5-1-u4-C7","difficulty":2,"kind":"match","stem":"상황과 대응 관계를 나타낸 식을 이으세요. (앞의 양이 □, 뒤의 양이 △예요.)","pairs":[{"l":"자전거 수와 바퀴 수","r":"□ × 2 = △"},{"l":"사각형 수와 꼭짓점 수","r":"□ × 4 = △"},{"l":"곤충 수와 다리 수","r":"□ × 6 = △"}],"mis":"M5-1-u4-X10","explanation":["자전거 하나에 바퀴 2개 — □ × 2 = △예요.","사각형 하나에 꼭짓점 4개 — □ × 4 = △, 곤충 하나에 다리 6개 — □ × 6 = △예요.","하나에 몇 개씩인지가 곱하는 수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황과 대응 관계를 나타낸 식을 이으세요. (앞의 양이 □, 뒤의 양이 △예요.)","pairs":[{"l":"사람 수와 눈의 수","r":"□ × 2 = △"},{"l":"삼각형 수와 변의 수","r":"□ × 3 = △"},{"l":"주 수와 날 수","r":"□ × 7 = △"}],"explanation":["사람 하나에 눈 2개 — □ × 2 = △예요.","삼각형 하나에 변 3개 — □ × 3 = △, 1주일은 7일 — □ × 7 = △예요.","하나에 몇 개씩인지가 곱하는 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_basic#10','math',5,1,'u4','L05','g5_1_math_u4_L05_basic','lesson_basic','M5-1-u4-C7',3,'sa','auto','다음 중 □ × 2 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 자전거 수와 바퀴 수 / 사람 수와 눈의 수 / 삼각형 수와 변의 수 / 젓가락 벌 수와 짝 수 / 의자 수와 의자 다리 수','{}'::text[],true,'{"seq":10,"concept":"M5-1-u4-C7","difficulty":3,"kind":"sa","stem":"다음 중 □ × 2 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 자전거 수와 바퀴 수 / 사람 수와 눈의 수 / 삼각형 수와 변의 수 / 젓가락 벌 수와 짝 수 / 의자 수와 의자 다리 수","answer":["3","3가지"],"explanation":["하나에 몇 개씩인지 보아요 — 자전거 수와 바퀴 수 2 · 사람 수와 눈의 수 2 · 삼각형 수와 변의 수 3 · 젓가락 벌 수와 짝 수 2 · 의자 수와 의자 다리 수 4.","하나에 2개씩인 것은 「자전거 수와 바퀴 수」, 「사람 수와 눈의 수」, 「젓가락 벌 수와 짝 수」예요.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"다음 중 □ × 4 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 사각형 수와 변의 수 / 곤충 수와 다리 수 / 의자 수와 의자 다리 수 / 자전거 수와 바퀴 수 / 오각형 수와 꼭짓점 수","answer":["2","2가지"],"explanation":["하나에 몇 개씩인지 보아요 — 사각형 수와 변의 수 4 · 곤충 수와 다리 수 6 · 의자 수와 의자 다리 수 4 · 자전거 수와 바퀴 수 2 · 오각형 수와 꼭짓점 수 5.","하나에 4개씩인 것은 「사각형 수와 변의 수」, 「의자 수와 의자 다리 수」예요.","모두 2가지예요."]},{"stem":"다음 중 □ × 3 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 삼각형 수와 변의 수 / 세발자전거 수와 바퀴 수 / 사람 수와 눈의 수 / 주 수와 날 수 / 사각형 수와 변의 수","answer":["2","2가지"],"explanation":["하나에 몇 개씩인지 보아요 — 삼각형 수와 변의 수 3 · 세발자전거 수와 바퀴 수 3 · 사람 수와 눈의 수 2 · 주 수와 날 수 7 · 사각형 수와 변의 수 4.","하나에 3개씩인 것은 「삼각형 수와 변의 수」, 「세발자전거 수와 바퀴 수」예요.","모두 2가지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#1','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C3',2,'error','auto','대응 관계인 두 양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u4-X05','M5-1-u4-X13']::text[],true,'{"seq":1,"concept":"M5-1-u4-C3","difficulty":2,"kind":"error","stem":"대응 관계인 두 양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「키와 좋아하는 색깔 수도 대응 관계야.」","correct":true,"mis_target":"M5-1-u4-X05"},{"t":"도현 — 「의자 수와 의자 다리 수는 대응 관계야.」","mis":"M5-1-u4-X13"},{"t":"하은 — 「주 수와 날 수는 대응 관계야.」","mis":"M5-1-u4-X13"}],"explanation":["의자 수와 의자 다리 수 · 주 수와 날 수 — 한 쪽이 정해지면 다른 쪽이 하나로 정해져요.","키와 좋아하는 색깔 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","서윤은 대응 관계가 아닌 것을 대응 관계라고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대응 관계인 두 양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「오늘 날씨와 내 나이도 대응 관계야.」","correct":true,"mis_target":"M5-1-u4-X05"},{"t":"라온 — 「자전거 수와 바퀴 수는 대응 관계야.」","mis":"M5-1-u4-X13"},{"t":"예준 — 「문어 수와 다리 수는 대응 관계야.」","mis":"M5-1-u4-X13"}],"explanation":["자전거 수와 바퀴 수 · 문어 수와 다리 수 — 한 쪽이 정해지면 다른 쪽이 하나로 정해져요.","오늘 날씨와 내 나이는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","지민은 대응 관계가 아닌 것을 대응 관계라고 잘못 말했어요."]},{"stem":"이번에는 다른 보기예요. 대응 관계인 두 양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「신발 크기와 가진 연필 수도 대응 관계야.」","correct":true,"mis_target":"M5-1-u4-X05"},{"t":"가온 — 「삼각형 수와 변의 수는 대응 관계야.」","mis":"M5-1-u4-X13"},{"t":"다솜 — 「사람 수와 눈의 수는 대응 관계야.」","mis":"M5-1-u4-X13"}],"explanation":["삼각형 수와 변의 수 · 사람 수와 눈의 수 — 한 쪽이 정해지면 다른 쪽이 하나로 정해져요.","신발 크기와 가진 연필 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","윤슬은 대응 관계가 아닌 것을 대응 관계라고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#2','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C7',2,'mc','auto','네 가지 상황 중 대응 관계를 나타내는 식이 다른 하나는 어느 것인가요?',ARRAY['M5-1-u4-X10']::text[],true,'{"seq":2,"concept":"M5-1-u4-C7","difficulty":2,"kind":"mc","stem":"네 가지 상황 중 대응 관계를 나타내는 식이 다른 하나는 어느 것인가요?","options":[{"t":"세발자전거 수와 바퀴 수","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X10"},{"t":"사람 수와 눈의 수","mis":"M5-1-u4-X10"},{"t":"젓가락 벌 수와 짝 수","mis":"M5-1-u4-X10"}],"explanation":["자전거 수와 바퀴 수, 사람 수와 눈의 수, 젓가락 벌 수와 짝 수는 모두 하나에 2개씩 — □ × 2 = △예요.","세발자전거 수와 바퀴 수는 하나에 3개씩 — □ × 3 = △예요.","상황이 달라도 관계 모양이 같으면 식은 하나예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 네 가지 상황 중 대응 관계를 나타내는 식이 다른 하나는 어느 것인가요?","options":[{"t":"오각형 수와 꼭짓점 수","correct":true},{"t":"사각형 수와 변의 수","mis":"M5-1-u4-X10"},{"t":"의자 수와 의자 다리 수","mis":"M5-1-u4-X10"},{"t":"자동차 수와 바퀴 수","mis":"M5-1-u4-X10"}],"explanation":["사각형 수와 변의 수, 의자 수와 의자 다리 수, 자동차 수와 바퀴 수는 모두 하나에 4개씩 — □ × 4 = △예요.","오각형 수와 꼭짓점 수는 하나에 5개씩 — □ × 5 = △예요.","상황이 달라도 관계 모양이 같으면 식은 하나예요."]},{"stem":"이번에는 다른 보기예요. 네 가지 상황 중 대응 관계를 나타내는 식이 다른 하나는 어느 것인가요?","options":[{"t":"사람 수와 눈의 수","correct":true},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X10"},{"t":"세발자전거 수와 바퀴 수","mis":"M5-1-u4-X10"},{"t":"삼각형 수와 꼭짓점 수","mis":"M5-1-u4-X10"}],"explanation":["삼각형 수와 변의 수, 세발자전거 수와 바퀴 수, 삼각형 수와 꼭짓점 수는 모두 하나에 3개씩 — □ × 3 = △예요.","사람 수와 눈의 수는 하나에 2개씩 — □ × 2 = △예요.","상황이 달라도 관계 모양이 같으면 식은 하나예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#3','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C7',3,'sa','auto','강아지 한 마리는 다리가 4개, 귀가 2개예요. 강아지 수를 □, 다리와 귀를 합한 수를 △라고 할 때 △가 54이면 강아지는 몇 마리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u4-C7","difficulty":3,"kind":"sa","stem":"강아지 한 마리는 다리가 4개, 귀가 2개예요. 강아지 수를 □, 다리와 귀를 합한 수를 △라고 할 때 △가 54이면 강아지는 몇 마리인가요? 숫자로 쓰세요.","answer":["9","9마리"],"explanation":["한 마리에 다리와 귀를 합하면 4 + 2 = 6개 — □ × 6 = △예요.","△가 54니 54 ÷ 6 = 9예요.","강아지는 9마리예요."],"variant_rule":{"alt":[{"stem":"고양이 한 마리는 다리가 4개, 귀가 2개예요. 고양이 수를 □, 다리와 귀를 합한 수를 △라고 할 때 △가 48이면 고양이는 몇 마리인가요? 숫자로 쓰세요.","answer":["8","8마리"],"explanation":["한 마리에 다리와 귀를 합하면 4 + 2 = 6개 — □ × 6 = △예요.","△가 48이니 48 ÷ 6 = 8이에요.","고양이는 8마리예요."]},{"stem":"오리 한 마리는 다리가 2개, 귀가 2개예요. 오리 수를 □, 다리와 귀를 합한 수를 △라고 할 때 △가 36이면 오리는 몇 마리인가요? 숫자로 쓰세요.","answer":["9","9마리"],"explanation":["한 마리에 다리와 귀를 합하면 2 + 2 = 4개 — □ × 4 = △예요.","△가 36이니 36 ÷ 4 = 9예요.","오리는 9마리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#4','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C7',3,'mc','auto','오각형 하나에 꼭짓점이 5개예요. 오각형 수를 □, 꼭짓점 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],true,'{"seq":4,"concept":"M5-1-u4-C7","difficulty":3,"kind":"mc","stem":"오각형 하나에 꼭짓점이 5개예요. 오각형 수를 □, 꼭짓점 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 5 = △","correct":true},{"t":"□ + 5 = △","mis":"M5-1-u4-X02"},{"t":"△ × 5 = □","mis":"M5-1-u4-X04"},{"t":"□ − 5 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(꼭짓점 수)는 □(오각형 수)의 5배예요.","그 말을 그대로 옮기면 □ × 5 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."],"variant_rule":{"alt":[{"stem":"1주일은 7일이에요. 주 수를 □, 날 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 7 = △","correct":true},{"t":"□ + 7 = △","mis":"M5-1-u4-X02"},{"t":"△ × 7 = □","mis":"M5-1-u4-X04"},{"t":"□ − 7 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(날 수)는 □(주 수)의 7배예요.","그 말을 그대로 옮기면 □ × 7 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]},{"stem":"곤충 한 마리에 다리가 6개예요. 곤충 수를 □, 다리 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 6 = △","correct":true},{"t":"□ + 6 = △","mis":"M5-1-u4-X02"},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"},{"t":"□ − 6 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(다리 수)는 □(곤충 수)의 6배예요.","그 말을 그대로 옮기면 □ × 6 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#5','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C7',3,'sa','auto','탁자 하나에 의자가 6개씩 놓여 있어요. 의자가 모두 78개라면 탁자는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u4-C7","difficulty":3,"kind":"sa","stem":"탁자 하나에 의자가 6개씩 놓여 있어요. 의자가 모두 78개라면 탁자는 몇 개인가요? 숫자로 쓰세요.","answer":["13","13개"],"explanation":["의자 수는 탁자 수의 6배예요.","거꾸로 가려면 6으로 나누어요 — 78 ÷ 6 = 13.","탁자는 13개예요."],"variant_rule":{"alt":[{"stem":"탁자 하나에 의자가 6개씩 놓여 있어요. 의자가 모두 84개라면 탁자는 몇 개인가요? 숫자로 쓰세요.","answer":["14","14개"],"explanation":["의자 수는 탁자 수의 6배예요.","거꾸로 가려면 6으로 나누어요 — 84 ÷ 6 = 14.","탁자는 14개예요."]},{"stem":"한 상자에 공책이 12권씩 들어 있어요. 공책 96권은 몇 상자인가요? 숫자로 쓰세요.","answer":["8","8상자"],"explanation":["공책 수는 상자 수의 12배예요.","거꾸로 가려면 12로 나누어요 — 96 ÷ 12 = 8.","공책 96권은 8상자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#6','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C7',3,'mc','auto','표와 같은 대응 관계를 나타내는 상황은 어느 것인가요?',ARRAY['M5-1-u4-X10','M5-1-u4-X02']::text[],true,'{"seq":6,"concept":"M5-1-u4-C7","difficulty":3,"kind":"mc","stem":"표와 같은 대응 관계를 나타내는 상황은 어느 것인가요?","options":[{"t":"문어 수와 다리 수","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X10"},{"t":"주 수와 날 수","mis":"M5-1-u4-X10"},{"t":"형 나이와 동생 나이(형이 8살 많다)","mis":"M5-1-u4-X02"}],"explanation":["표의 짝 1과 8, 2와 16, 3과 24 — 아래 수는 위 수의 8배예요.","「문어 수와 다리 수」도 하나에 8개씩이라 □ × 8 = △예요.","상황이 달라도 관계 모양이 같으면 같은 식이에요."],"asset":{"type":"numgrid","rows":[["□",1,2,3,4],["△",8,16,24,32]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표와 같은 대응 관계를 나타내는 상황은 어느 것인가요?","options":[{"t":"주 수와 날 수","correct":true},{"t":"곤충 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"문어 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"동생 나이와 형 나이(형이 7살 많다)","mis":"M5-1-u4-X02"}],"explanation":["표의 짝 1과 7, 2와 14, 3과 21 — 아래 수는 위 수의 7배예요.","「주 수와 날 수」도 하나에 7개씩이라 □ × 7 = △예요.","상황이 달라도 관계 모양이 같으면 같은 식이에요."],"asset":{"type":"numgrid","rows":[["□",1,2,3,4],["△",7,14,21,28]],"name":"대응표"}},{"stem":"이번에는 다른 보기예요. 표와 같은 대응 관계를 나타내는 상황은 어느 것인가요?","options":[{"t":"세발자전거 수와 바퀴 수","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X10"},{"t":"사각형 수와 변의 수","mis":"M5-1-u4-X10"},{"t":"동생 나이와 형 나이(형이 3살 많다)","mis":"M5-1-u4-X02"}],"explanation":["표의 짝 1과 3, 2와 6, 3과 9 — 아래 수는 위 수의 3배예요.","「세발자전거 수와 바퀴 수」도 하나에 3개씩이라 □ × 3 = △예요.","상황이 달라도 관계 모양이 같으면 같은 식이에요."],"asset":{"type":"numgrid","rows":[["□",1,2,3,4],["△",3,6,9,12]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#7','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C3',3,'ox','auto','버스 번호가 502, 504, 506, 508로 2씩 커지는 것은 두 양 사이의 대응 관계예요.',ARRAY['M5-1-u4-X01']::text[],true,'{"seq":7,"concept":"M5-1-u4-C3","difficulty":3,"kind":"ox","stem":"버스 번호가 502, 504, 506, 508로 2씩 커지는 것은 두 양 사이의 대응 관계예요.","answer":"X","reason_options":[{"t":"한 줄의 수가 2씩 커지는 규칙일 뿐, 짝을 이루는 두 양이 없으므로","correct":true},{"t":"수가 2씩 일정하게 변하므로","mis":"M5-1-u4-X01"}],"mis":"M5-1-u4-X01","explanation":["버스 번호는 한 줄로 늘어선 수예요.","대응 관계는 두 양이 짝을 이루어 함께 변하는 관계예요.","그래서 버스 번호의 규칙은 대응 관계가 아니라 한 줄의 규칙이에요."],"variant_rule":{"alt":[{"stem":"우쿨렐레 수가 1, 2, 3일 때 줄 수가 4, 8, 12인 것은 두 양 사이의 대응 관계예요.","answer":"O","reason_options":[{"t":"우쿨렐레 수가 정해지면 줄 수가 그 4배로 하나로 정해지므로","correct":true},{"t":"줄 수가 4씩 늘어나기 때문이므로","mis":"M5-1-u4-X01"}],"explanation":["우쿨렐레 수와 줄 수, 두 양이 짝을 이루어요.","줄 수는 우쿨렐레 수의 4배로 하나로 정해져요.","「4씩 늘어난다」는 한 줄 이야기, 「4배」가 대응 관계예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#8','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C7',4,'sa','auto','세발자전거 1대와 두발자전거 1대를 한 묶음으로 빌려줘요. 묶음 수를 □, 빌려준 자전거의 바퀴 수를 △라고 할 때 △가 85이면 묶음은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u4-C7","difficulty":4,"kind":"sa","stem":"세발자전거 1대와 두발자전거 1대를 한 묶음으로 빌려줘요. 묶음 수를 □, 빌려준 자전거의 바퀴 수를 △라고 할 때 △가 85이면 묶음은 몇 개인가요? 숫자로 쓰세요.","answer":["17","17개"],"explanation":["한 묶음의 바퀴는 3 × 1 + 2 × 1 = 5개예요.","□ × 5 = △에서 △가 85니 85 ÷ 5 = 17이에요.","묶음은 17개예요."],"variant_rule":{"alt":[{"stem":"세발자전거 2대와 두발자전거 1대를 한 묶음으로 빌려줘요. 묶음 수를 □, 빌려준 자전거의 바퀴 수를 △라고 할 때 △가 64이면 묶음은 몇 개인가요? 숫자로 쓰세요.","answer":["8","8개"],"explanation":["한 묶음의 바퀴는 3 × 2 + 2 × 1 = 8개예요.","□ × 8 = △에서 △가 64니 64 ÷ 8 = 8이에요.","묶음은 8개예요."]},{"stem":"세발자전거 1대와 두발자전거 2대를 한 묶음으로 빌려줘요. 묶음 수를 □, 빌려준 자전거의 바퀴 수를 △라고 할 때 △가 91이면 묶음은 몇 개인가요? 숫자로 쓰세요.","answer":["13","13개"],"explanation":["한 묶음의 바퀴는 3 × 1 + 2 × 2 = 7개예요.","□ × 7 = △에서 △가 91이니 91 ÷ 7 = 13이에요.","묶음은 13개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#9','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C7',4,'essay','teacher','□ × 2 = △로 나타낼 수 있는 생활 속 상황을 두 가지 들고, 상황이 달라도 같은 식이 되는 까닭을 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u4-C7","difficulty":4,"kind":"essay","stem":"□ × 2 = △로 나타낼 수 있는 생활 속 상황을 두 가지 들고, 상황이 달라도 같은 식이 되는 까닭을 설명하세요.","answer_guide":{"answer":"예: 자전거 수와 바퀴 수, 사람 수와 눈의 수는 모두 □ × 2 = △로 나타낼 수 있다. 자전거 하나에 바퀴가 2개, 사람 하나에 눈이 2개처럼 하나에 2개씩 붙는 관계의 모양이 같기 때문이다. 담긴 것은 달라도 관계의 모양이 같으면 식은 하나이다.","scoring_points":["□ × 2 = △가 되는 상황을 두 가지 바르게 들었는가","「하나에 2개씩」이라는 공통점을 썼는가","관계 모양이 같으면 식이 같다고 맺었는가"]},"explanation":["자전거와 바퀴, 사람과 눈 — 하나에 2개씩이에요.","하나에 2개씩이면 □ × 2 = △예요.","담긴 것이 달라도 관계 모양이 같으면 같은 식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L05_challenge#10','math',5,1,'u4','L05','g5_1_math_u4_L05_challenge','lesson_challenge','M5-1-u4-C3',4,'essay','teacher','「키와 좋아하는 색깔 수」가 대응 관계가 아닌 까닭을 쓰고, 이런 두 양으로는 왜 「키가 140 cm이면 좋아하는 색깔은 몇 개인가요?」 같은 물음에 답할 수 없는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u4-C3","difficulty":4,"kind":"essay","stem":"「키와 좋아하는 색깔 수」가 대응 관계가 아닌 까닭을 쓰고, 이런 두 양으로는 왜 「키가 140 cm이면 좋아하는 색깔은 몇 개인가요?」 같은 물음에 답할 수 없는지 설명하세요.","answer_guide":{"answer":"예: 키가 같은 친구들도 좋아하는 색깔 수가 저마다 달라 키가 정해져도 색깔 수는 하나로 정해지지 않는다. 그래서 대응 관계가 아니다. 하나로 정해지지 않으니 키가 140 cm라고 해도 색깔 수를 하나로 답할 수 없다.","scoring_points":["키가 정해져도 색깔 수가 하나로 정해지지 않는다고 썼는가","그래서 대응 관계가 아니라고 썼는가","하나로 정해지지 않으면 물음에 답할 수 없다고 이었는가"]},"explanation":["대응 관계는 한 양이 정해지면 다른 양이 하나로 정해져요.","키가 같아도 좋아하는 색깔 수는 저마다 달라요.","하나로 정해지지 않으니 답할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#1','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',1,'mc','auto','룰루랄라 친구들이 선물을 사요. 선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 4개의 값은 모두 얼마인가요?',ARRAY['M5-1-u4-X09','M5-1-u4-X02','M5-1-u4-X12']::text[],true,'{"seq":1,"concept":"M5-1-u4-C8","difficulty":1,"kind":"mc","stem":"룰루랄라 친구들이 선물을 사요. 선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 4개의 값은 모두 얼마인가요?","options":[{"t":"12000원","correct":true},{"t":"9000원","mis":"M5-1-u4-X09"},{"t":"3004원","mis":"M5-1-u4-X02"},{"t":"15000원","mis":"M5-1-u4-X12"}],"explanation":["값을 구하는 데 쓰는 정보는 선물 하나의 값 3000원과 선물 수뿐이에요.","선물 수를 □, 값을 △라고 하면 □ × 3000 = △ — 4 × 3000 = 12000이에요.","선물 값은 모두 12000원이에요."],"variant_rule":{"alt":[{"stem":"룰루랄라 친구들이 선물을 사요. 선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 5개의 값은 모두 얼마인가요?","options":[{"t":"15000원","correct":true},{"t":"12000원","mis":"M5-1-u4-X09"},{"t":"3005원","mis":"M5-1-u4-X02"},{"t":"18000원","mis":"M5-1-u4-X12"}],"explanation":["값을 구하는 데 쓰는 정보는 선물 하나의 값 3000원과 선물 수뿐이에요.","선물 수를 □, 값을 △라고 하면 □ × 3000 = △ — 5 × 3000 = 15000이에요.","선물 값은 모두 15000원이에요."]},{"stem":"룰루랄라 친구들이 선물을 사요. 선물 하나는 2000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 6개의 값은 모두 얼마인가요?","options":[{"t":"12000원","correct":true},{"t":"10000원","mis":"M5-1-u4-X09"},{"t":"2006원","mis":"M5-1-u4-X02"},{"t":"14000원","mis":"M5-1-u4-X12"}],"explanation":["값을 구하는 데 쓰는 정보는 선물 하나의 값 2000원과 선물 수뿐이에요.","선물 수를 □, 값을 △라고 하면 □ × 2000 = △ — 6 × 2000 = 12000이에요.","선물 값은 모두 12000원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#2','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',1,'sa','auto','선물 하나가 3000원이에요. 21000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C8","difficulty":1,"kind":"sa","stem":"선물 하나가 3000원이에요. 21000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["7","7개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 3000 = △예요.","△가 21000이니 되돌려 나누어요 — 21000 ÷ 3000 = 7.","선물 7개를 살 수 있어요."],"variant_rule":{"alt":[{"stem":"선물 하나가 3000원이에요. 18000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["6","6개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 3000 = △예요.","△가 18000이니 되돌려 나누어요 — 18000 ÷ 3000 = 6.","선물 6개를 살 수 있어요."]},{"stem":"선물 하나가 2000원이에요. 16000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["8","8개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 2000 = △예요.","△가 16000이니 되돌려 나누어요 — 16000 ÷ 2000 = 8.","선물 8개를 살 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#3','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',1,'mc','auto','선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 값을 구하는 데 필요 없는 정보는 어느 것인가요?',ARRAY['M5-1-u4-X11']::text[],true,'{"seq":3,"concept":"M5-1-u4-C8","difficulty":1,"kind":"mc","stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 값을 구하는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"가게까지 걸어서 15분","correct":true},{"t":"선물 하나의 값","mis":"M5-1-u4-X11"},{"t":"선물의 개수","mis":"M5-1-u4-X11"},{"t":"선물 수와 값 사이의 관계","mis":"M5-1-u4-X11"}],"explanation":["선물 값을 구하려면 선물 하나의 값과 선물의 개수만 있으면 돼요.","가게까지 걸어서 15분은 묻는 것과 이어지지 않아요.","그래서 필요 없는 정보는 「가게까지 걸어서 15분」이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 값을 구하는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"포장지의 색 4가지","correct":true},{"t":"선물 하나의 값","mis":"M5-1-u4-X11"},{"t":"선물의 개수","mis":"M5-1-u4-X11"},{"t":"선물 수와 값 사이의 관계","mis":"M5-1-u4-X11"}],"explanation":["선물 값을 구하려면 선물 하나의 값과 선물의 개수만 있으면 돼요.","포장지의 색 4가지는 묻는 것과 이어지지 않아요.","그래서 필요 없는 정보는 「포장지의 색 4가지」예요."]},{"stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 살 수 있는 선물 수를 구하는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"가게까지 걸어서 15분","correct":true},{"t":"선물 하나의 값","mis":"M5-1-u4-X11"},{"t":"가진 돈","mis":"M5-1-u4-X11"},{"t":"선물 수와 값 사이의 관계","mis":"M5-1-u4-X11"}],"explanation":["살 수 있는 선물 수를 구하려면 선물 하나의 값과 가진 돈만 있으면 돼요.","가게까지 걸어서 15분은 묻는 것과 이어지지 않아요.","그래서 필요 없는 정보는 「가게까지 걸어서 15분」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#4','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',1,'mc','auto','룰루랄라 친구들이 선물을 사요. 선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 10개의 값은 모두 얼마인가요?',ARRAY['M5-1-u4-X09','M5-1-u4-X02','M5-1-u4-X12']::text[],true,'{"seq":4,"concept":"M5-1-u4-C8","difficulty":1,"kind":"mc","stem":"룰루랄라 친구들이 선물을 사요. 선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 10개의 값은 모두 얼마인가요?","options":[{"t":"30000원","correct":true},{"t":"27000원","mis":"M5-1-u4-X09"},{"t":"3010원","mis":"M5-1-u4-X02"},{"t":"33000원","mis":"M5-1-u4-X12"}],"explanation":["값을 구하는 데 쓰는 정보는 선물 하나의 값 3000원과 선물 수뿐이에요.","선물 수를 □, 값을 △라고 하면 □ × 3000 = △ — 10 × 3000 = 30000이에요.","선물 값은 모두 30000원이에요."],"variant_rule":{"alt":[{"stem":"룰루랄라 친구들이 선물을 사요. 선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 12개의 값은 모두 얼마인가요?","options":[{"t":"36000원","correct":true},{"t":"33000원","mis":"M5-1-u4-X09"},{"t":"3012원","mis":"M5-1-u4-X02"},{"t":"39000원","mis":"M5-1-u4-X12"}],"explanation":["값을 구하는 데 쓰는 정보는 선물 하나의 값 3000원과 선물 수뿐이에요.","선물 수를 □, 값을 △라고 하면 □ × 3000 = △ — 12 × 3000 = 36000이에요.","선물 값은 모두 36000원이에요."]},{"stem":"룰루랄라 친구들이 선물을 사요. 선물 하나는 4000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 9개의 값은 모두 얼마인가요?","options":[{"t":"36000원","correct":true},{"t":"32000원","mis":"M5-1-u4-X09"},{"t":"4009원","mis":"M5-1-u4-X02"},{"t":"40000원","mis":"M5-1-u4-X12"}],"explanation":["값을 구하는 데 쓰는 정보는 선물 하나의 값 4000원과 선물 수뿐이에요.","선물 수를 □, 값을 △라고 하면 □ × 4000 = △ — 9 × 4000 = 36000이에요.","선물 값은 모두 36000원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
