des=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#6','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',2,'sa','auto','선물 하나가 3000원이에요. 27000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u4-C8","difficulty":2,"kind":"sa","stem":"선물 하나가 3000원이에요. 27000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["9","9개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 3000 = △예요.","△가 27000이니 되돌려 나누어요 — 27000 ÷ 3000 = 9.","선물 9개를 살 수 있어요."],"variant_rule":{"alt":[{"stem":"선물 하나가 3000원이에요. 33000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["11","11개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 3000 = △예요.","△가 33000이니 되돌려 나누어요 — 33000 ÷ 3000 = 11.","선물 11개를 살 수 있어요."]},{"stem":"선물 하나가 4000원이에요. 36000원으로는 선물을 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["9","9개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 4000 = △예요.","△가 36000이니 되돌려 나누어요 — 36000 ÷ 4000 = 9.","선물 9개를 살 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#7','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',2,'mc','auto','선물 하나가 3000원이에요. 선물 수를 □, 선물 값을 △라고 할 때 알맞은 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X08']::text[],true,'{"seq":7,"concept":"M5-1-u4-C8","difficulty":2,"kind":"mc","stem":"선물 하나가 3000원이에요. 선물 수를 □, 선물 값을 △라고 할 때 알맞은 식은 어느 것인가요?","options":[{"t":"□ × 3000 = △","correct":true},{"t":"□ + 3000 = △","mis":"M5-1-u4-X02"},{"t":"△ × 3000 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 3000 = △","mis":"M5-1-u4-X08"}],"explanation":["선물 1개면 3000원, 2개면 6000원, 3개면 9000원이에요.","선물 값은 선물 수의 3000배예요.","그래서 식은 □ × 3000 = △예요."],"variant_rule":{"alt":[{"stem":"선물 하나가 2000원이에요. 선물 수를 □, 선물 값을 △라고 할 때 알맞은 식은 어느 것인가요?","options":[{"t":"□ × 2000 = △","correct":true},{"t":"□ + 2000 = △","mis":"M5-1-u4-X02"},{"t":"△ × 2000 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 2000 = △","mis":"M5-1-u4-X08"}],"explanation":["선물 1개면 2000원, 2개면 4000원, 3개면 6000원이에요.","선물 값은 선물 수의 2000배예요.","그래서 식은 □ × 2000 = △예요."]},{"stem":"선물 하나가 5000원이에요. 선물 수를 □, 선물 값을 △라고 할 때 알맞은 식은 어느 것인가요?","options":[{"t":"□ × 5000 = △","correct":true},{"t":"□ + 5000 = △","mis":"M5-1-u4-X02"},{"t":"△ × 5000 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 5000 = △","mis":"M5-1-u4-X08"}],"explanation":["선물 1개면 5000원, 2개면 10000원, 3개면 15000원이에요.","선물 값은 선물 수의 5000배예요.","그래서 식은 □ × 5000 = △예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#8','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',2,'mc','auto','대응 관계로 문제를 풀 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['M5-1-u4-X11','M5-1-u4-X06']::text[],true,'{"seq":8,"concept":"M5-1-u4-C8","difficulty":2,"kind":"mc","stem":"대응 관계로 문제를 풀 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"필요한 정보와 필요 없는 정보를 가른다","correct":true},{"t":"나온 수를 모두 더한다","mis":"M5-1-u4-X11"},{"t":"가장 큰 수를 찾는다","mis":"M5-1-u4-X11"},{"t":"□와 △를 아무렇게나 정한다","mis":"M5-1-u4-X06"}],"explanation":["문제에는 묻는 것과 상관없는 정보도 함께 있어요.","묻는 것에 이어진 수만 고르는 것이 첫걸음이에요.","그다음 표를 그리고 □와 △를 정해 식을 세워요."],"variant_rule":{"alt":[{"stem":"필요한 정보를 고른 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"두 양을 표로 나란히 놓아 짝을 본다","correct":true},{"t":"나온 수를 모두 곱한다","mis":"M5-1-u4-X11"},{"t":"가장 작은 수를 답으로 쓴다","mis":"M5-1-u4-X12"},{"t":"필요 없는 정보를 다시 넣는다","mis":"M5-1-u4-X11"}],"explanation":["필요한 정보만 남겼으면 두 양을 표로 놓아요.","표를 위아래로 읽으면 짝이 보여요.","짝이 보이면 식 한 줄로 정리해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#9','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',2,'sa','auto','선물 수와 선물 값의 대응표예요. 선물 값이 24000원이면 선물은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u4-C8","difficulty":2,"kind":"sa","stem":"선물 수와 선물 값의 대응표예요. 선물 값이 24000원이면 선물은 몇 개인가요? 숫자로 쓰세요.","answer":["8","8개"],"explanation":["표를 위아래로 읽으면 선물 값은 선물 수의 3000배예요.","선물 수를 □, 값을 △라고 하면 □ × 3000 = △ — 되돌려 24000 ÷ 3000 = 8.","표 밖의 값이어도 식으로 선물 8개를 구해요."],"asset":{"type":"numgrid","rows":[["선물 수(개)",1,2,3,4],["값(원)",3000,6000,9000,12000]],"name":"대응표"},"variant_rule":{"alt":[{"stem":"선물 수와 선물 값의 대응표예요. 선물 값이 30000원이면 선물은 몇 개인가요? 숫자로 쓰세요.","answer":["10","10개"],"explanation":["표를 위아래로 읽으면 선물 값은 선물 수의 3000배예요.","선물 수를 □, 값을 △라고 하면 □ × 3000 = △ — 되돌려 30000 ÷ 3000 = 10.","표 밖의 값이어도 식으로 선물 10개를 구해요."],"asset":{"type":"numgrid","rows":[["선물 수(개)",1,2,3,4],["값(원)",3000,6000,9000,12000]],"name":"대응표"}},{"stem":"선물 수와 선물 값의 대응표예요. 선물 값이 18000원이면 선물은 몇 개인가요? 숫자로 쓰세요.","answer":["9","9개"],"explanation":["표를 위아래로 읽으면 선물 값은 선물 수의 2000배예요.","선물 수를 □, 값을 △라고 하면 □ × 2000 = △ — 되돌려 18000 ÷ 2000 = 9.","표 밖의 값이어도 식으로 선물 9개를 구해요."],"asset":{"type":"numgrid","rows":[["선물 수(개)",1,2,3,4],["값(원)",2000,4000,6000,8000]],"name":"대응표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_basic#10','math',5,1,'u4','L06','g5_1_math_u4_L06_basic','lesson_basic','M5-1-u4-C8',3,'sa','auto','가진 돈 50000원으로 하나에 3000원인 선물을 몇 개 샀더니 26000원이 남았어요. 선물을 몇 개 샀나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-1-u4-C8","difficulty":3,"kind":"sa","stem":"가진 돈 50000원으로 하나에 3000원인 선물을 몇 개 샀더니 26000원이 남았어요. 선물을 몇 개 샀나요? 숫자로 쓰세요.","answer":["8","8개"],"explanation":["쓴 돈은 50000 − 26000 = 24000원이에요.","선물 수를 □라고 하면 □ × 3000 = 24000 — 24000 ÷ 3000 = 8이에요.","선물을 8개 샀어요."],"variant_rule":{"alt":[{"stem":"가진 돈 50000원으로 하나에 3000원인 선물을 몇 개 샀더니 20000원이 남았어요. 선물을 몇 개 샀나요? 숫자로 쓰세요.","answer":["10","10개"],"explanation":["쓴 돈은 50000 − 20000 = 30000원이에요.","선물 수를 □라고 하면 □ × 3000 = 30000 — 30000 ÷ 3000 = 10이에요.","선물을 10개 샀어요."]},{"stem":"가진 돈 40000원으로 하나에 4000원인 선물을 몇 개 샀더니 12000원이 남았어요. 선물을 몇 개 샀나요? 숫자로 쓰세요.","answer":["7","7개"],"explanation":["쓴 돈은 40000 − 12000 = 28000원이에요.","선물 수를 □라고 하면 □ × 4000 = 28000 — 28000 ÷ 4000 = 7이에요.","선물을 7개 샀어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#1','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',2,'error','auto','선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 8개의 값을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u4-X11','M5-1-u4-X13']::text[],true,'{"seq":1,"concept":"M5-1-u4-C8","difficulty":2,"kind":"error","stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 8개의 값을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「15분과 4가지 색도 셈에 넣어야 해.」","correct":true,"mis_target":"M5-1-u4-X11"},{"t":"도윤 — 「8 × 3000 = 24000 — 24000원이야.」","mis":"M5-1-u4-X13"},{"t":"하린 — 「선물 수를 □, 값을 △라고 하면 □ × 3000 = △야.」","mis":"M5-1-u4-X13"}],"explanation":["값을 구하는 데 쓰는 것은 선물 하나의 값과 선물 수예요.","8 × 3000 = 24000 — 24000원이에요.","서윤은 값과 상관없는 시간과 색 수까지 넣으려 해 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 6개의 값을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「15분과 4가지 색도 셈에 넣어야 해.」","correct":true,"mis_target":"M5-1-u4-X11"},{"t":"하람 — 「6 × 3000 = 18000 — 18000원이야.」","mis":"M5-1-u4-X13"},{"t":"은우 — 「선물 수를 □, 값을 △라고 하면 □ × 3000 = △야.」","mis":"M5-1-u4-X13"}],"explanation":["값을 구하는 데 쓰는 것은 선물 하나의 값과 선물 수예요.","6 × 3000 = 18000 — 18000원이에요.","지우는 값과 상관없는 시간과 색 수까지 넣으려 해 잘못 말했어요."]},{"stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 9개의 값을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나은 — 「15분과 4가지 색도 셈에 넣어야 해.」","correct":true,"mis_target":"M5-1-u4-X11"},{"t":"시온 — 「9 × 3000 = 27000 — 27000원이야.」","mis":"M5-1-u4-X13"},{"t":"태린 — 「선물 수를 □, 값을 △라고 하면 □ × 3000 = △야.」","mis":"M5-1-u4-X13"}],"explanation":["값을 구하는 데 쓰는 것은 선물 하나의 값과 선물 수예요.","9 × 3000 = 27000 — 27000원이에요.","나은은 값과 상관없는 시간과 색 수까지 넣으려 해 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#2','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',2,'sa','auto','선물 하나가 3000원이에요. 50000원으로 선물을 가장 많이 몇 개 살 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u4-C8","difficulty":2,"kind":"sa","stem":"선물 하나가 3000원이에요. 50000원으로 선물을 가장 많이 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["16","16개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 3000 = △예요.","16 × 3000 = 48000, 17 × 3000 = 51000 — 50000원을 넘지 않는 것은 16개까지예요.","선물 16개를 사고 2000원이 남아요."],"variant_rule":{"alt":[{"stem":"선물 하나가 3000원이에요. 40000원으로 선물을 가장 많이 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["13","13개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 3000 = △예요.","13 × 3000 = 39000, 14 × 3000 = 42000 — 40000원을 넘지 않는 것은 13개까지예요.","선물 13개를 사고 1000원이 남아요."]},{"stem":"선물 하나가 4000원이에요. 50000원으로 선물을 가장 많이 몇 개 살 수 있나요? 숫자로 쓰세요.","answer":["12","12개"],"explanation":["선물 수를 □, 값을 △라고 하면 □ × 4000 = △예요.","12 × 4000 = 48000, 13 × 4000 = 52000 — 50000원을 넘지 않는 것은 12개까지예요.","선물 12개를 사고 2000원이 남아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#3','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',3,'mc','auto','선물 하나는 3000원, 포장 하나는 500원이에요. 친구 한 사람에게 포장한 선물을 하나씩 줄 때 친구 수를 □, 드는 돈을 △라고 하면 알맞은 식은 어느 것인가요?',ARRAY['M5-1-u4-X12','M5-1-u4-X02','M5-1-u4-X04']::text[],true,'{"seq":3,"concept":"M5-1-u4-C8","difficulty":3,"kind":"mc","stem":"선물 하나는 3000원, 포장 하나는 500원이에요. 친구 한 사람에게 포장한 선물을 하나씩 줄 때 친구 수를 □, 드는 돈을 △라고 하면 알맞은 식은 어느 것인가요?","options":[{"t":"□ × 3500 = △","correct":true},{"t":"□ × 3000 = △","mis":"M5-1-u4-X12"},{"t":"□ + 3500 = △","mis":"M5-1-u4-X02"},{"t":"△ × 3500 = □","mis":"M5-1-u4-X04"}],"explanation":["한 사람에게 드는 돈은 3000 + 500 = 3500원이에요.","친구가 1명, 2명, 3명이면 3500원, 7000원, 10500원 — 친구 수의 3500배예요.","그래서 식은 □ × 3500 = △예요."],"variant_rule":{"alt":[{"stem":"선물 하나는 3000원, 포장 하나는 1000원이에요. 친구 한 사람에게 포장한 선물을 하나씩 줄 때 친구 수를 □, 드는 돈을 △라고 하면 알맞은 식은 어느 것인가요?","options":[{"t":"□ × 4000 = △","correct":true},{"t":"□ × 3000 = △","mis":"M5-1-u4-X12"},{"t":"□ + 4000 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4000 = □","mis":"M5-1-u4-X04"}],"explanation":["한 사람에게 드는 돈은 3000 + 1000 = 4000원이에요.","친구가 1명, 2명, 3명이면 4000원, 8000원, 12000원 — 친구 수의 4000배예요.","그래서 식은 □ × 4000 = △예요."]},{"stem":"선물 하나는 2500원, 포장 하나는 500원이에요. 친구 한 사람에게 포장한 선물을 하나씩 줄 때 친구 수를 □, 드는 돈을 △라고 하면 알맞은 식은 어느 것인가요?","options":[{"t":"□ × 3000 = △","correct":true},{"t":"□ × 2500 = △","mis":"M5-1-u4-X12"},{"t":"□ + 3000 = △","mis":"M5-1-u4-X02"},{"t":"△ × 3000 = □","mis":"M5-1-u4-X04"}],"explanation":["한 사람에게 드는 돈은 2500 + 500 = 3000원이에요.","친구가 1명, 2명, 3명이면 3000원, 6000원, 9000원 — 친구 수의 3000배예요.","그래서 식은 □ × 3000 = △예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#4','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',3,'sa','auto','선물 하나는 3000원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 28000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u4-C8","difficulty":3,"kind":"sa","stem":"선물 하나는 3000원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 28000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["8","8명"],"explanation":["한 사람에게 드는 돈은 3000 + 500 = 3500원 — □ × 3500 = △예요.","△가 28000이니 28000 ÷ 3500 = 8이에요.","친구는 8명이에요."],"variant_rule":{"alt":[{"stem":"선물 하나는 3000원, 포장 하나는 1000원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 36000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["9","9명"],"explanation":["한 사람에게 드는 돈은 3000 + 1000 = 4000원 — □ × 4000 = △예요.","△가 36000이니 36000 ÷ 4000 = 9예요.","친구는 9명이에요."]},{"stem":"선물 하나는 2500원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 27000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["9","9명"],"explanation":["한 사람에게 드는 돈은 2500 + 500 = 3000원 — □ × 3000 = △예요.","△가 27000이니 27000 ÷ 3000 = 9예요.","친구는 9명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#5','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',3,'mc','auto','선물을 6개 사려고 해요. 가 가게는 하나에 3000원, 나 가게는 하나에 2500원에 배달비 4000원을 한 번 더 내요. 돈이 덜 드는 곳은 어느 것인가요?',ARRAY['M5-1-u4-X12','M5-1-u4-X11']::text[],true,'{"seq":5,"concept":"M5-1-u4-C8","difficulty":3,"kind":"mc","stem":"선물을 6개 사려고 해요. 가 가게는 하나에 3000원, 나 가게는 하나에 2500원에 배달비 4000원을 한 번 더 내요. 돈이 덜 드는 곳은 어느 것인가요?","options":[{"t":"가 가게","correct":true},{"t":"나 가게","mis":"M5-1-u4-X12"},{"t":"두 가게가 같다","mis":"M5-1-u4-X12"},{"t":"배달비가 있어 견줄 수 없다","mis":"M5-1-u4-X11"}],"explanation":["가 가게: 6 × 3000 = 18000원이에요.","나 가게: 6 × 2500 + 4000 = 19000원이에요.","가 가게가 덜 들어요."],"variant_rule":{"alt":[{"stem":"선물을 10개 사려고 해요. 가 가게는 하나에 3000원, 나 가게는 하나에 2500원에 배달비 4000원을 한 번 더 내요. 돈이 덜 드는 곳은 어느 것인가요?","options":[{"t":"나 가게","correct":true},{"t":"가 가게","mis":"M5-1-u4-X12"},{"t":"두 가게가 같다","mis":"M5-1-u4-X12"},{"t":"배달비가 있어 견줄 수 없다","mis":"M5-1-u4-X11"}],"explanation":["가 가게: 10 × 3000 = 30000원이에요.","나 가게: 10 × 2500 + 4000 = 29000원이에요.","나 가게가 덜 들어요."]},{"stem":"선물을 6개 사려고 해요. 가 가게는 하나에 3000원, 나 가게는 하나에 2000원에 배달비 6000원을 한 번 더 내요. 돈이 덜 드는 곳은 어느 것인가요?","options":[{"t":"두 가게가 같다","correct":true},{"t":"가 가게","mis":"M5-1-u4-X12"},{"t":"나 가게","mis":"M5-1-u4-X12"},{"t":"배달비가 있어 견줄 수 없다","mis":"M5-1-u4-X11"}],"explanation":["가 가게: 6 × 3000 = 18000원이에요.","나 가게: 6 × 2000 + 6000 = 18000원이에요.","두 가게가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#6','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',3,'mc','auto','가진 돈 50000원으로 하나에 3000원인 선물을 사요. 선물 수를 □, 남는 돈을 △라고 할 때 알맞은 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X02','M5-1-u4-X11']::text[],true,'{"seq":6,"concept":"M5-1-u4-C8","difficulty":3,"kind":"mc","stem":"가진 돈 50000원으로 하나에 3000원인 선물을 사요. 선물 수를 □, 남는 돈을 △라고 할 때 알맞은 식은 어느 것인가요?","options":[{"t":"50000 − □ × 3000 = △","correct":true},{"t":"□ × 3000 − 50000 = △","mis":"M5-1-u4-X04"},{"t":"50000 − □ − 3000 = △","mis":"M5-1-u4-X02"},{"t":"□ × 50000 = △","mis":"M5-1-u4-X11"}],"explanation":["선물 □개의 값은 □ × 3000원이에요.","남는 돈은 가진 돈에서 선물 값을 뺀 것 — 50000 − □ × 3000 = △예요.","□가 2이면 50000 − 2 × 3000 = 44000으로 확인해요."],"variant_rule":{"alt":[{"stem":"가진 돈 40000원으로 하나에 4000원인 선물을 사요. 선물 수를 □, 남는 돈을 △라고 할 때 알맞은 식은 어느 것인가요?","options":[{"t":"40000 − □ × 4000 = △","correct":true},{"t":"□ × 4000 − 40000 = △","mis":"M5-1-u4-X04"},{"t":"40000 − □ − 4000 = △","mis":"M5-1-u4-X02"},{"t":"□ × 40000 = △","mis":"M5-1-u4-X11"}],"explanation":["선물 □개의 값은 □ × 4000원이에요.","남는 돈은 가진 돈에서 선물 값을 뺀 것 — 40000 − □ × 4000 = △예요.","□가 2이면 40000 − 2 × 4000 = 32000으로 확인해요."]},{"stem":"가진 돈 30000원으로 하나에 2000원인 선물을 사요. 선물 수를 □, 남는 돈을 △라고 할 때 알맞은 식은 어느 것인가요?","options":[{"t":"30000 − □ × 2000 = △","correct":true},{"t":"□ × 2000 − 30000 = △","mis":"M5-1-u4-X04"},{"t":"30000 − □ − 2000 = △","mis":"M5-1-u4-X02"},{"t":"□ × 30000 = △","mis":"M5-1-u4-X11"}],"explanation":["선물 □개의 값은 □ × 2000원이에요.","남는 돈은 가진 돈에서 선물 값을 뺀 것 — 30000 − □ × 2000 = △예요.","□가 2이면 30000 − 2 × 2000 = 26000으로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#7','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',3,'ox','auto','선물 값을 구할 때 「가게까지 걸어서 15분」이라는 정보도 꼭 써야 해요.',ARRAY['M5-1-u4-X11']::text[],true,'{"seq":7,"concept":"M5-1-u4-C8","difficulty":3,"kind":"ox","stem":"선물 값을 구할 때 「가게까지 걸어서 15분」이라는 정보도 꼭 써야 해요.","answer":"X","reason_options":[{"t":"걸린 시간은 선물 수나 값과 이어지지 않아 값을 구하는 데 쓰이지 않으므로","correct":true},{"t":"문제에 나온 수는 모두 써야 하므로","mis":"M5-1-u4-X11"}],"mis":"M5-1-u4-X11","explanation":["선물 값은 선물 하나의 값과 선물 수로 정해져요.","걸린 시간은 값과 상관없어요.","문제에 있는 수라고 다 쓰이는 것은 아니에요."],"variant_rule":{"alt":[{"stem":"선물 값을 구할 때 「포장지는 4가지 색」이라는 정보는 쓰지 않아도 돼요.","answer":"O","reason_options":[{"t":"포장지 색의 가짓수는 선물 수와 값 사이의 관계와 이어지지 않으므로","correct":true},{"t":"4가지 색이 있으니 값에 4를 곱해야 하므로","mis":"M5-1-u4-X11"}],"explanation":["선물 값은 선물 하나의 값과 선물 수로 정해져요.","포장지 색의 가짓수는 값과 상관없어요.","그래서 쓰지 않아도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#8','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',4,'sa','auto','가진 돈은 50000원이에요. 친구마다 3000원짜리 선물과 500원짜리 포장을 하나씩 샀더니 22000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u4-C8","difficulty":4,"kind":"sa","stem":"가진 돈은 50000원이에요. 친구마다 3000원짜리 선물과 500원짜리 포장을 하나씩 샀더니 22000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["8","8명"],"explanation":["쓴 돈은 50000 − 22000 = 28000원이에요.","한 사람에게 3000 + 500 = 3500원 — □ × 3500 = 28000이에요.","28000 ÷ 3500 = 8 — 친구는 8명이에요."],"variant_rule":{"alt":[{"stem":"가진 돈은 50000원이에요. 친구마다 3000원짜리 선물과 1000원짜리 포장을 하나씩 샀더니 2000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["12","12명"],"explanation":["쓴 돈은 50000 − 2000 = 48000원이에요.","한 사람에게 3000 + 1000 = 4000원 — □ × 4000 = 48000이에요.","48000 ÷ 4000 = 12 — 친구는 12명이에요."]},{"stem":"가진 돈은 40000원이에요. 친구마다 2500원짜리 선물과 500원짜리 포장을 하나씩 샀더니 4000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["12","12명"],"explanation":["쓴 돈은 40000 − 4000 = 36000원이에요.","한 사람에게 2500 + 500 = 3000원 — □ × 3000 = 36000이에요.","36000 ÷ 3000 = 12 — 친구는 12명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#9','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',4,'essay','teacher','「선물 하나는 3000원, 가게까지 15분, 포장지는 4가지 색, 가진 돈은 50000원」일 때 27000원으로 선물을 몇 개 살 수 있는지 구하는 과정을 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u4-C8","difficulty":4,"kind":"essay","stem":"「선물 하나는 3000원, 가게까지 15분, 포장지는 4가지 색, 가진 돈은 50000원」일 때 27000원으로 선물을 몇 개 살 수 있는지 구하는 과정을 설명하세요.","answer_guide":{"answer":"예: 먼저 필요한 정보만 고른다 — 선물 하나의 값 3000원만 쓰고 15분, 4가지 색은 쓰지 않는다. 선물 수를 □, 값을 △라고 하면 □ × 3000 = △이다. △가 27000이므로 27000 ÷ 3000 = 9 — 선물 9개를 살 수 있다.","scoring_points":["필요 없는 정보(15분·4가지 색)를 걷어냈는가","□ × 3000 = △처럼 식을 세웠는가","27000 ÷ 3000 = 9로 구했는가"]},"explanation":["필요한 정보는 선물 하나의 값 3000원이에요.","□ × 3000 = △ — △가 27000이에요.","27000 ÷ 3000 = 9 — 9개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_L06_challenge#10','math',5,1,'u4','L06','g5_1_math_u4_L06_challenge','lesson_challenge','M5-1-u4-C8',4,'essay','teacher','선물 수와 선물 값의 관계를 표로 나타내면 좋은 점과, 표에서 식으로 옮기는 과정을 선물 하나 3000원을 예로 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u4-C8","difficulty":4,"kind":"essay","stem":"선물 수와 선물 값의 관계를 표로 나타내면 좋은 점과, 표에서 식으로 옮기는 과정을 선물 하나 3000원을 예로 설명하세요.","answer_guide":{"answer":"예: 선물 수 1, 2, 3과 값 3000, 6000, 9000을 표에 나란히 놓으면 위아래 짝이 또렷이 보인다. 짝을 보면 값은 선물 수의 3000배이다. 선물 수를 □, 값을 △라고 정하면 □ × 3000 = △로 정리되고, 이 식으로 표에 없는 선물 수의 값도 구할 수 있다.","scoring_points":["표에 두 양을 나란히 놓아 짝을 보았는가","값이 선물 수의 3000배라고 말했는가","□ × 3000 = △로 옮기고 표 밖 값도 구한다고 썼는가"]},"explanation":["표로 놓으면 짝이 보여요.","값은 선물 수의 3000배예요.","□ × 3000 = △ — 식으로 표 밖 값도 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#1','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C1',1,'sa','auto','꿀벌 한 마리의 날개는 4개예요. 꿀벌 9마리의 날개는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-1-u4-C1","difficulty":1,"kind":"sa","stem":"꿀벌 한 마리의 날개는 4개예요. 꿀벌 9마리의 날개는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["36","36개"],"explanation":["꿀벌이 하나 늘 때마다 날개 수는 4씩 늘어요 — 날개 수는 꿀벌 수의 4배예요.","9 × 4 = 36이에요.","꿀벌 9마리의 날개는 36개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#2','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C1',2,'mc','auto','우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 100개의 줄은 모두 몇 개인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],false,'{"seq":2,"concept":"M5-1-u4-C1","difficulty":2,"kind":"mc","stem":"우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 100개의 줄은 모두 몇 개인가요?","options":[{"t":"400개","correct":true},{"t":"104개","mis":"M5-1-u4-X02"},{"t":"404개","mis":"M5-1-u4-X09"},{"t":"4000개","mis":"M5-1-u4-X12"}],"explanation":["줄 수는 우쿨렐레 수의 4배예요 — 표를 100칸까지 그리지 않아도 돼요.","100 × 4 = 400이에요.","우쿨렐레 100개의 줄은 400개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#3','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C1',3,'sa','auto','우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 40개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"우쿨렐레 수를 1, 2, 3, …으로 늘려 가며 줄 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 우쿨렐레 40개의 줄 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["39","39번"],"explanation":["우쿨렐레 1개일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","40개까지 가려면 40 − 1 = 39번 더해요 — 4 + 4 × 39 = 160.","40 × 4 = 160처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#4','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C2',1,'mc','auto','꿀벌 수와 다리 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],false,'{"seq":4,"concept":"M5-1-u4-C2","difficulty":1,"kind":"mc","stem":"꿀벌 수와 다리 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?","options":[{"t":"24","correct":true},{"t":"10","mis":"M5-1-u4-X02"},{"t":"30","mis":"M5-1-u4-X09"},{"t":"23","mis":"M5-1-u4-X12"}],"explanation":["위아래 짝 1과 6을 보면 다리 수는 꿀벌 수의 6배예요.","?의 위 칸은 4 — 4 × 6 = 24예요.","?에 알맞은 수는 24예요."],"asset":{"type":"numgrid","rows":[["꿀벌 수",1,2,3,4,5],["다리 수",6,12,18,null,30]],"name":"대응표","q":[1,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#5','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C2',2,'mc','auto','꿀벌 수와 다리 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-1-u4-X01','M5-1-u4-X03','M5-1-u4-X04']::text[],false,'{"seq":5,"concept":"M5-1-u4-C2","difficulty":2,"kind":"mc","stem":"꿀벌 수와 다리 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"다리 수는 꿀벌 수의 6배","correct":true},{"t":"다리 수는 6씩 늘어난다","mis":"M5-1-u4-X01"},{"t":"다리 수는 꿀벌 수보다 5 많다","mis":"M5-1-u4-X03"},{"t":"꿀벌 수는 다리 수의 6배","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 1과 6, 2와 12, 3과 18.","다리 수는 꿀벌 수의 6배 — 둘째 짝도 2 × 6 = 12로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["꿀벌 수",1,2,3,4,5],["다리 수",6,12,18,24,30]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#6','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C2',4,'sa','auto','원호는 늘 동생보다 3살 많아요. 두 사람의 나이를 더했더니 25살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M5-1-u4-C2","difficulty":4,"kind":"sa","stem":"원호는 늘 동생보다 3살 많아요. 두 사람의 나이를 더했더니 25살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.","answer":["11","11살"],"explanation":["원호 나이는 동생 나이보다 3 많아요 — 합에서 3을 빼면 동생 나이의 2배예요.","25 − 3 = 22, 22 ÷ 2 = 11이에요.","동생은 11살, 원호는 14살 — 11 + 14 = 25로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#7','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C3',1,'mc','auto','우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 수가 정해지면 줄 수는 어떻게 되나요?',ARRAY['M5-1-u4-X05','M5-1-u4-X02']::text[],false,'{"seq":7,"concept":"M5-1-u4-C3","difficulty":1,"kind":"mc","stem":"우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 수가 정해지면 줄 수는 어떻게 되나요?","options":[{"t":"하나로 정해진다","correct":true},{"t":"여러 가지가 될 수 있다","mis":"M5-1-u4-X05"},{"t":"우쿨렐레 수와 상관없이 늘 같다","mis":"M5-1-u4-X05"},{"t":"우쿨렐레 수보다 늘 4 많다","mis":"M5-1-u4-X02"}],"explanation":["우쿨렐레 하나에 줄 4개씩으로 정해져 있어요.","그래서 우쿨렐레 수가 정해지면 줄 수도 딱 하나로 정해져요.","이렇게 하나로 정해지는 두 양의 관계가 대응 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#8','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],false,'{"seq":8,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"키와 좋아하는 색깔 수","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X13"},{"t":"주 수와 날 수","mis":"M5-1-u4-X13"},{"t":"피자 수와 조각 수","mis":"M5-1-u4-X13"}],"explanation":["자전거 수와 바퀴 수 · 주 수와 날 수 · 피자 수와 조각 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","키와 좋아하는 색깔 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「키와 좋아하는 색깔 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#9','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C3',3,'mc','auto','두 양이 대응 관계인 것은 어느 것인가요?',ARRAY['M5-1-u4-X05']::text[],false,'{"seq":9,"concept":"M5-1-u4-C3","difficulty":3,"kind":"mc","stem":"두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"꿀벌 수와 다리 수","correct":true},{"t":"내 키와 좋아하는 색깔 수","mis":"M5-1-u4-X05"},{"t":"오늘 기온과 반 친구 수","mis":"M5-1-u4-X05"},{"t":"머리카락 길이와 가진 책 수","mis":"M5-1-u4-X05"}],"explanation":["내 키와 좋아하는 색깔 수 · 오늘 기온과 반 친구 수 · 머리카락 길이와 가진 책 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","꿀벌 수와 다리 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「꿀벌 수와 다리 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#10','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C4',1,'mc','auto','자동차 한 대에 바퀴가 4개예요. 자동차 수를 □, 바퀴 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],false,'{"seq":10,"concept":"M5-1-u4-C4","difficulty":1,"kind":"mc","stem":"자동차 한 대에 바퀴가 4개예요. 자동차 수를 □, 바퀴 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ − 4 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(바퀴 수)는 □(자동차 수)의 4배예요.","그 말을 그대로 옮기면 □ × 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#11','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C4',2,'mc','auto','원호 나이를 □, 동생 나이를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X01']::text[],false,'{"seq":11,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"원호 나이를 □, 동생 나이를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ − 3 = △","correct":true},{"t":"□ × 3 = △","mis":"M5-1-u4-X02"},{"t":"△ − 3 = □","mis":"M5-1-u4-X04"},{"t":"□ + 1 = △","mis":"M5-1-u4-X01"}],"explanation":["위아래 짝 12와 9, 13과 10, 14와 11을 보아요.","모든 짝에서 △는 □보다 3 적어요.","그래서 식은 □ − 3 = △예요."],"asset":{"type":"numgrid","rows":[["원호 나이",12,13,14,15,16],["동생 나이",9,10,11,12,13]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#12','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C4',3,'sa','auto','□ × 5 = △이고 □와 △를 더하면 54예요. □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u4-C4","difficulty":3,"kind":"sa","stem":"□ × 5 = △이고 □와 △를 더하면 54예요. □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△는 □의 5배라서 □ + △는 □의 6배예요.","54 ÷ 6 = 9예요.","□ = 9, △ = 9 × 5 = 45 — 9 + 45 = 54로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#13','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C5',1,'mc','auto','□ × 4 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":13,"concept":"M5-1-u4-C5","difficulty":1,"kind":"mc","stem":"□ × 4 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 4 = □","correct":true},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 4 = △","mis":"M5-1-u4-X08"},{"t":"△ + 4 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 4 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 4 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 4 = 12, 거꾸로 12 ÷ 4 = 3으로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#14','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C5',2,'mc','auto','□ + 5 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":14,"concept":"M5-1-u4-C5","difficulty":2,"kind":"mc","stem":"□ + 5 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ − 5 = □","correct":true},{"t":"△ + 5 = □","mis":"M5-1-u4-X08"},{"t":"□ − 5 = △","mis":"M5-1-u4-X08"},{"t":"△ × 5 = □","mis":"M5-1-u4-X02"}],"explanation":["□ + 5 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ − 5 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 + 5 = 8, 거꾸로 8 − 5 = 3으로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#15','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C5',3,'sa','auto','△ ÷ 8 = □에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M5-1-u4-C5","difficulty":3,"kind":"sa","stem":"△ ÷ 8 = □에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["△ ÷ 8 = □는 □ × 8 = △를 거꾸로 쓴 식이에요.","□가 9이면 9 × 8 = 72예요.","△는 72예요 — 72 ÷ 8 = 9로 식에도 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#16','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C6',1,'sa','auto','□ × 6 = △에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ × 6 = △에서 □가 9일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["□ 자리에 9를 넣어요.","9 × 6 = 54예요.","△는 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#17','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C6',1,'sa','auto','□ × 6 = △에서 △가 48일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ × 6 = △에서 △가 48일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 48이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","48 ÷ 6 = 8이에요.","□는 8이에요. 8 × 6 = 48로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#18','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C6',2,'mc','auto','□ × 7 = △에서 □가 9일 때 △는 얼마인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X12']::text[],false,'{"seq":18,"concept":"M5-1-u4-C6","difficulty":2,"kind":"mc","stem":"□ × 7 = △에서 □가 9일 때 △는 얼마인가요?","options":[{"t":"63","correct":true},{"t":"16","mis":"M5-1-u4-X02"},{"t":"70","mis":"M5-1-u4-X12"},{"t":"56","mis":"M5-1-u4-X12"}],"explanation":["□ 자리에 9를 넣어요.","9 × 7 = 63이에요.","△는 63이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#19','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C6',4,'sa','auto','□ × 3 = △이고 □ + △ = 64예요. △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u4-C6","difficulty":4,"kind":"sa","stem":"□ × 3 = △이고 □ + △ = 64예요. △는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["□ + △는 □의 4배예요.","□ = 64 ÷ 4 = 16이에요.","△ = 16 × 3 = 48 — 묻는 것은 △라서 48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#20','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C7',1,'mc','auto','□ × 2 = △로 나타낼 수 있는 두 양은 어느 것인가요?',ARRAY['M5-1-u4-X10']::text[],false,'{"seq":20,"concept":"M5-1-u4-C7","difficulty":1,"kind":"mc","stem":"□ × 2 = △로 나타낼 수 있는 두 양은 어느 것인가요?","options":[{"t":"사람 수와 눈의 수","correct":true},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X10"},{"t":"곤충 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"의자 수와 의자 다리 수","mis":"M5-1-u4-X10"}],"explanation":["하나에 몇 개씩인지 보아요 — 「삼각형 수와 변의 수」는 하나에 3개씩 · 「곤충 수와 다리 수」는 하나에 6개씩 · 「의자 수와 의자 다리 수」는 하나에 4개씩.","「사람 수와 눈의 수」는 하나에 2개씩이에요.","그래서 □ × 2 = △로 나타낼 수 있는 것은 「사람 수와 눈의 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#21','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C7',2,'sa','auto','1주일은 7일이에요. 84일은 몇 주일인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u4-C7","difficulty":2,"kind":"sa","stem":"1주일은 7일이에요. 84일은 몇 주일인가요? 숫자로 쓰세요.","answer":["12","12주일"],"explanation":["날 수는 주 수의 7배예요.","거꾸로 가려면 7로 나누어요 — 84 ÷ 7 = 12.","84일은 12주일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#22','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C7',3,'sa','auto','다음 중 □ × 2 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 젓가락 벌 수와 짝 수 / 삼각형 수와 변의 수 / 사람 수와 눈의 수 / 사각형 수와 변의 수 / 세발자전거 수와 바퀴 수','{}'::text[],false,'{"seq":22,"concept":"M5-1-u4-C7","difficulty":3,"kind":"sa","stem":"다음 중 □ × 2 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 젓가락 벌 수와 짝 수 / 삼각형 수와 변의 수 / 사람 수와 눈의 수 / 사각형 수와 변의 수 / 세발자전거 수와 바퀴 수","answer":["2","2가지"],"explanation":["하나에 몇 개씩인지 보아요 — 젓가락 벌 수와 짝 수 2 · 삼각형 수와 변의 수 3 · 사람 수와 눈의 수 2 · 사각형 수와 변의 수 4 · 세발자전거 수와 바퀴 수 3.","하나에 2개씩인 것은 「젓가락 벌 수와 짝 수」, 「사람 수와 눈의 수」예요.","모두 2가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#23','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C8',2,'mc','auto','선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 값을 구하는 데 필요 없는 정보는 어느 것인가요?',ARRAY['M5-1-u4-X11']::text[],false,'{"seq":23,"concept":"M5-1-u4-C8","difficulty":2,"kind":"mc","stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 값을 구하는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"가게까지 걸어서 15분","correct":true},{"t":"선물 하나의 값","mis":"M5-1-u4-X11"},{"t":"선물의 개수","mis":"M5-1-u4-X11"},{"t":"선물 수와 값 사이의 관계","mis":"M5-1-u4-X11"}],"explanation":["선물 값을 구하려면 선물 하나의 값과 선물의 개수만 있으면 돼요.","가게까지 걸어서 15분은 묻는 것과 이어지지 않아요.","그래서 필요 없는 정보는 「가게까지 걸어서 15분」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#24','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C8',3,'sa','auto','선물 하나는 3000원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 31500원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u4-C8","difficulty":3,"kind":"sa","stem":"선물 하나는 3000원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 31500원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["9","9명"],"explanation":["한 사람에게 드는 돈은 3000 + 500 = 3500원 — □ × 3500 = △예요.","△가 31500이니 31500 ÷ 3500 = 9예요.","친구는 9명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_a#25','math',5,1,'u4','','g5_1_math_u4_review_a','unit_review','M5-1-u4-C8',4,'sa','auto','가진 돈은 50000원이에요. 친구마다 3000원짜리 선물과 500원짜리 포장을 하나씩 샀더니 15000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u4-C8","difficulty":4,"kind":"sa","stem":"가진 돈은 50000원이에요. 친구마다 3000원짜리 선물과 500원짜리 포장을 하나씩 샀더니 15000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["10","10명"],"explanation":["쓴 돈은 50000 − 15000 = 35000원이에요.","한 사람에게 3000 + 500 = 3500원 — □ × 3500 = 35000이에요.","35000 ÷ 3500 = 10 — 친구는 10명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#1','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C1',1,'sa','auto','우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 12개의 줄은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-1-u4-C1","difficulty":1,"kind":"sa","stem":"우쿨렐레 한 개에는 줄이 4개 있어요. 우쿨렐레 12개의 줄은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["48","48개"],"explanation":["우쿨렐레가 하나 늘 때마다 줄 수는 4씩 늘어요 — 줄 수는 우쿨렐레 수의 4배예요.","12 × 4 = 48이에요.","우쿨렐레 12개의 줄은 48개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#2','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C1',2,'mc','auto','꿀벌 한 마리의 다리는 6개예요. 꿀벌 100마리의 다리는 모두 몇 개인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],false,'{"seq":2,"concept":"M5-1-u4-C1","difficulty":2,"kind":"mc","stem":"꿀벌 한 마리의 다리는 6개예요. 꿀벌 100마리의 다리는 모두 몇 개인가요?","options":[{"t":"600개","correct":true},{"t":"106개","mis":"M5-1-u4-X02"},{"t":"606개","mis":"M5-1-u4-X09"},{"t":"6000개","mis":"M5-1-u4-X12"}],"explanation":["다리 수는 꿀벌 수의 6배예요 — 표를 100칸까지 그리지 않아도 돼요.","100 × 6 = 600이에요.","꿀벌 100마리의 다리는 600개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#3','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C1',3,'sa','auto','삼각형 수를 1, 2, 3, …으로 늘려 가며 변 수를 3, 6, 9, …으로 적었어요. 3부터 3씩 더해 가며 삼각형 60개의 변 수까지 가려면 3을 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"삼각형 수를 1, 2, 3, …으로 늘려 가며 변 수를 3, 6, 9, …으로 적었어요. 3부터 3씩 더해 가며 삼각형 60개의 변 수까지 가려면 3을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["59","59번"],"explanation":["삼각형 1개일 때가 3이고, 하나 늘 때마다 3을 한 번 더해요.","60개까지 가려면 60 − 1 = 59번 더해요 — 3 + 3 × 59 = 180.","60 × 3 = 180처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#4','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C2',1,'mc','auto','삼각형 수와 변의 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],false,'{"seq":4,"concept":"M5-1-u4-C2","difficulty":1,"kind":"mc","stem":"삼각형 수와 변의 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?","options":[{"t":"18","correct":true},{"t":"9","mis":"M5-1-u4-X02"},{"t":"21","mis":"M5-1-u4-X09"},{"t":"17","mis":"M5-1-u4-X12"}],"explanation":["위아래 짝 1과 3을 보면 변의 수는 삼각형 수의 3배예요.","?의 위 칸은 6 — 6 × 3 = 18이에요.","?에 알맞은 수는 18이에요."],"asset":{"type":"numgrid","rows":[["삼각형 수",1,2,3,4,5,6],["변의 수",3,6,9,12,15,null]],"name":"대응표","q":[1,6]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#5','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C2',2,'mc','auto','피자 수와 조각 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-1-u4-X01','M5-1-u4-X03','M5-1-u4-X04']::text[],false,'{"seq":5,"concept":"M5-1-u4-C2","difficulty":2,"kind":"mc","stem":"피자 수와 조각 수의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"조각 수는 피자 수의 8배","correct":true},{"t":"조각 수는 8씩 늘어난다","mis":"M5-1-u4-X01"},{"t":"조각 수는 피자 수보다 7 많다","mis":"M5-1-u4-X03"},{"t":"피자 수는 조각 수의 8배","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 1과 8, 2와 16, 3과 24.","조각 수는 피자 수의 8배 — 둘째 짝도 2 × 8 = 16으로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["피자 수",1,2,3,4],["조각 수",8,16,24,32]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#6','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C2',4,'sa','auto','언니는 늘 나보다 4살 많아요. 두 사람의 나이를 더했더니 34살이에요. 나는 몇 살인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M5-1-u4-C2","difficulty":4,"kind":"sa","stem":"언니는 늘 나보다 4살 많아요. 두 사람의 나이를 더했더니 34살이에요. 나는 몇 살인가요? 숫자로 쓰세요.","answer":["15","15살"],"explanation":["언니 나이는 나 나이보다 4 많아요 — 합에서 4를 빼면 나 나이의 2배예요.","34 − 4 = 30, 30 ÷ 2 = 15예요.","나는 15살, 언니는 19살 — 15 + 19 = 34로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#7','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C3',1,'mc','auto','자동차 한 대에는 바퀴가 4개 있어요. 자동차 수가 정해지면 바퀴 수는 어떻게 되나요?',ARRAY['M5-1-u4-X05','M5-1-u4-X02']::text[],false,'{"seq":7,"concept":"M5-1-u4-C3","difficulty":1,"kind":"mc","stem":"자동차 한 대에는 바퀴가 4개 있어요. 자동차 수가 정해지면 바퀴 수는 어떻게 되나요?","options":[{"t":"하나로 정해진다","correct":true},{"t":"여러 가지가 될 수 있다","mis":"M5-1-u4-X05"},{"t":"자동차 수와 상관없이 늘 같다","mis":"M5-1-u4-X05"},{"t":"자동차 수보다 늘 4 많다","mis":"M5-1-u4-X02"}],"explanation":["자동차 하나에 바퀴 4개씩으로 정해져 있어요.","그래서 자동차 수가 정해지면 바퀴 수도 딱 하나로 정해져요.","이렇게 하나로 정해지는 두 양의 관계가 대응 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#8','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],false,'{"seq":8,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"오늘 날씨와 내 나이","correct":true},{"t":"의자 수와 의자 다리 수","mis":"M5-1-u4-X13"},{"t":"꿀벌 수와 날개 수","mis":"M5-1-u4-X13"},{"t":"모둠 수와 사람 수","mis":"M5-1-u4-X13"}],"explanation":["의자 수와 의자 다리 수 · 꿀벌 수와 날개 수 · 모둠 수와 사람 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","오늘 날씨와 내 나이는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「오늘 날씨와 내 나이」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#9','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C3',3,'mc','auto','두 양이 대응 관계인 것은 어느 것인가요?',ARRAY['M5-1-u4-X05']::text[],false,'{"seq":9,"concept":"M5-1-u4-C3","difficulty":3,"kind":"mc","stem":"두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"원호 나이와 동생 나이","correct":true},{"t":"오늘 날씨와 내 나이","mis":"M5-1-u4-X05"},{"t":"신발 크기와 좋아하는 과일 수","mis":"M5-1-u4-X05"},{"t":"내 몸무게와 가진 연필 수","mis":"M5-1-u4-X05"}],"explanation":["오늘 날씨와 내 나이 · 신발 크기와 좋아하는 과일 수 · 내 몸무게와 가진 연필 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","원호 나이와 동생 나이는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「원호 나이와 동생 나이」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#10','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C4',1,'mc','auto','곤충 한 마리에 다리가 6개예요. 곤충 수를 □, 다리 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],false,'{"seq":10,"concept":"M5-1-u4-C4","difficulty":1,"kind":"mc","stem":"곤충 한 마리에 다리가 6개예요. 곤충 수를 □, 다리 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 6 = △","correct":true},{"t":"□ + 6 = △","mis":"M5-1-u4-X02"},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"},{"t":"□ − 6 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(다리 수)는 □(곤충 수)의 6배예요.","그 말을 그대로 옮기면 □ × 6 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#11','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C4',2,'mc','auto','방콕 시각을 □, 서울 시각을 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X01']::text[],false,'{"seq":11,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"방콕 시각을 □, 서울 시각을 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 2 = △","mis":"M5-1-u4-X02"},{"t":"△ + 2 = □","mis":"M5-1-u4-X04"},{"t":"□ + 1 = △","mis":"M5-1-u4-X01"}],"explanation":["위아래 짝 3과 5, 4와 6, 5와 7을 보아요.","모든 짝에서 △는 □보다 2 많아요.","그래서 식은 □ + 2 = △예요."],"asset":{"type":"numgrid","rows":[["방콕 시각",3,4,5,6,7],["서울 시각",5,6,7,8,9]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#12','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C4',3,'sa','auto','□ × 3 = △이고 □와 △를 더하면 48이에요. □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u4-C4","difficulty":3,"kind":"sa","stem":"□ × 3 = △이고 □와 △를 더하면 48이에요. □는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["△는 □의 3배라서 □ + △는 □의 4배예요.","48 ÷ 4 = 12예요.","□ = 12, △ = 12 × 3 = 36 — 12 + 36 = 48로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#13','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C5',1,'mc','auto','□ × 7 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":13,"concept":"M5-1-u4-C5","difficulty":1,"kind":"mc","stem":"□ × 7 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 7 = □","correct":true},{"t":"△ × 7 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 7 = △","mis":"M5-1-u4-X08"},{"t":"△ + 7 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 7 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 7 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 7 = 21, 거꾸로 21 ÷ 7 = 3으로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#14','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C5',2,'mc','auto','□ − 3 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":14,"concept":"M5-1-u4-C5","difficulty":2,"kind":"mc","stem":"□ − 3 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ + 3 = □","correct":true},{"t":"△ − 3 = □","mis":"M5-1-u4-X08"},{"t":"□ + 3 = △","mis":"M5-1-u4-X08"},{"t":"△ ÷ 3 = □","mis":"M5-1-u4-X02"}],"explanation":["□ − 3 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ + 3 = □ — 셈이 거꾸로 바뀌어요.","□ = 8이면 8 − 3 = 5, 거꾸로 5 + 3 = 8로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#15','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C5',3,'sa','auto','△ ÷ 6 = □에서 □가 12일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M5-1-u4-C5","difficulty":3,"kind":"sa","stem":"△ ÷ 6 = □에서 □가 12일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["△ ÷ 6 = □는 □ × 6 = △를 거꾸로 쓴 식이에요.","□가 12이면 12 × 6 = 72예요.","△는 72예요 — 72 ÷ 6 = 12로 식에도 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#16','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C6',1,'sa','auto','□ × 7 = △에서 □가 8일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ × 7 = △에서 □가 8일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["□ 자리에 8을 넣어요.","8 × 7 = 56이에요.","△는 56이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#17','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C6',1,'sa','auto','□ × 9 = △에서 △가 81일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ × 9 = △에서 △가 81일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["△ 자리에 81이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","81 ÷ 9 = 9예요.","□는 9예요. 9 × 9 = 81로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#18','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C6',2,'mc','auto','□ + 6 = △에서 □가 25일 때 △는 얼마인가요?',ARRAY['M5-1-u4-X07','M5-1-u4-X02','M5-1-u4-X13']::text[],false,'{"seq":18,"concept":"M5-1-u4-C6","difficulty":2,"kind":"mc","stem":"□ + 6 = △에서 □가 25일 때 △는 얼마인가요?","options":[{"t":"31","correct":true},{"t":"19","mis":"M5-1-u4-X07"},{"t":"150","mis":"M5-1-u4-X02"},{"t":"25","mis":"M5-1-u4-X13"}],"explanation":["□ 자리에 25를 넣어요.","25 + 6 = 31이에요.","△는 31이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#19','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C6',4,'sa','auto','□ × 5 = △이고 □ + △ = 72예요. △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u4-C6","difficulty":4,"kind":"sa","stem":"□ × 5 = △이고 □ + △ = 72예요. △는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["□ + △는 □의 6배예요.","□ = 72 ÷ 6 = 12예요.","△ = 12 × 5 = 60 — 묻는 것은 △라서 60이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#20','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C7',1,'mc','auto','□ × 3 = △로 나타낼 수 있는 두 양은 어느 것인가요?',ARRAY['M5-1-u4-X10']::text[],false,'{"seq":20,"concept":"M5-1-u4-C7","difficulty":1,"kind":"mc","stem":"□ × 3 = △로 나타낼 수 있는 두 양은 어느 것인가요?","options":[{"t":"삼각형 수와 변의 수","correct":true},{"t":"자전거 수와 바퀴 수","mis":"M5-1-u4-X10"},{"t":"사각형 수와 변의 수","mis":"M5-1-u4-X10"},{"t":"주 수와 날 수","mis":"M5-1-u4-X10"}],"explanation":["하나에 몇 개씩인지 보아요 — 「자전거 수와 바퀴 수」는 하나에 2개씩 · 「사각형 수와 변의 수」는 하나에 4개씩 · 「주 수와 날 수」는 하나에 7개씩.","「삼각형 수와 변의 수」는 하나에 3개씩이에요.","그래서 □ × 3 = △로 나타낼 수 있는 것은 「삼각형 수와 변의 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#21','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C7',2,'sa','auto','젓가락 한 벌은 2짝이에요. 젓가락 24짝은 몇 벌인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u4-C7","difficulty":2,"kind":"sa","stem":"젓가락 한 벌은 2짝이에요. 젓가락 24짝은 몇 벌인가요? 숫자로 쓰세요.","answer":["12","12벌"],"explanation":["짝 수는 벌 수의 2배예요.","거꾸로 가려면 2로 나누어요 — 24 ÷ 2 = 12.","젓가락 24짝은 12벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#22','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C7',3,'sa','auto','다음 중 □ × 4 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 자동차 수와 바퀴 수 / 사각형 수와 변의 수 / 의자 수와 의자 다리 수 / 삼각형 수와 변의 수 / 오각형 수와 꼭짓점 수','{}'::text[],false,'{"seq":22,"concept":"M5-1-u4-C7","difficulty":3,"kind":"sa","stem":"다음 중 □ × 4 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 자동차 수와 바퀴 수 / 사각형 수와 변의 수 / 의자 수와 의자 다리 수 / 삼각형 수와 변의 수 / 오각형 수와 꼭짓점 수","answer":["3","3가지"],"explanation":["하나에 몇 개씩인지 보아요 — 자동차 수와 바퀴 수 4 · 사각형 수와 변의 수 4 · 의자 수와 의자 다리 수 4 · 삼각형 수와 변의 수 3 · 오각형 수와 꼭짓점 수 5.","하나에 4개씩인 것은 「자동차 수와 바퀴 수」, 「사각형 수와 변의 수」, 「의자 수와 의자 다리 수」예요.","모두 3가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#23','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C8',2,'mc','auto','선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 값을 구하는 데 필요 없는 정보는 어느 것인가요?',ARRAY['M5-1-u4-X11']::text[],false,'{"seq":23,"concept":"M5-1-u4-C8","difficulty":2,"kind":"mc","stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 선물 값을 구하는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"포장지의 색 4가지","correct":true},{"t":"선물 하나의 값","mis":"M5-1-u4-X11"},{"t":"선물의 개수","mis":"M5-1-u4-X11"},{"t":"선물 수와 값 사이의 관계","mis":"M5-1-u4-X11"}],"explanation":["선물 값을 구하려면 선물 하나의 값과 선물의 개수만 있으면 돼요.","포장지의 색 4가지는 묻는 것과 이어지지 않아요.","그래서 필요 없는 정보는 「포장지의 색 4가지」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#24','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C8',3,'sa','auto','선물 하나는 3000원, 포장 하나는 1000원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 32000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u4-C8","difficulty":3,"kind":"sa","stem":"선물 하나는 3000원, 포장 하나는 1000원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 32000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["8","8명"],"explanation":["한 사람에게 드는 돈은 3000 + 1000 = 4000원 — □ × 4000 = △예요.","△가 32000이니 32000 ÷ 4000 = 8이에요.","친구는 8명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_b#25','math',5,1,'u4','','g5_1_math_u4_review_b','unit_review','M5-1-u4-C8',4,'sa','auto','가진 돈은 50000원이에요. 친구마다 3000원짜리 선물과 1000원짜리 포장을 하나씩 샀더니 10000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u4-C8","difficulty":4,"kind":"sa","stem":"가진 돈은 50000원이에요. 친구마다 3000원짜리 선물과 1000원짜리 포장을 하나씩 샀더니 10000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["10","10명"],"explanation":["쓴 돈은 50000 − 10000 = 40000원이에요.","한 사람에게 3000 + 1000 = 4000원 — □ × 4000 = 40000이에요.","40000 ÷ 4000 = 10 — 친구는 10명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#1','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C1',1,'sa','auto','꿀벌 한 마리의 다리는 6개예요. 꿀벌 8마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-1-u4-C1","difficulty":1,"kind":"sa","stem":"꿀벌 한 마리의 다리는 6개예요. 꿀벌 8마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["48","48개"],"explanation":["꿀벌이 하나 늘 때마다 다리 수는 6씩 늘어요 — 다리 수는 꿀벌 수의 6배예요.","8 × 6 = 48이에요.","꿀벌 8마리의 다리는 48개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#2','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C1',2,'mc','auto','삼각형 하나의 변은 3개예요. 삼각형 200개의 변은 모두 몇 개인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],false,'{"seq":2,"concept":"M5-1-u4-C1","difficulty":2,"kind":"mc","stem":"삼각형 하나의 변은 3개예요. 삼각형 200개의 변은 모두 몇 개인가요?","options":[{"t":"600개","correct":true},{"t":"203개","mis":"M5-1-u4-X02"},{"t":"603개","mis":"M5-1-u4-X09"},{"t":"6000개","mis":"M5-1-u4-X12"}],"explanation":["변의 수는 삼각형 수의 3배예요 — 표를 200칸까지 그리지 않아도 돼요.","200 × 3 = 600이에요.","삼각형 200개의 변은 600개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#3','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C1',3,'sa','auto','꿀벌 수를 1, 2, 3, …으로 늘려 가며 다리 수를 6, 12, 18, …으로 적었어요. 6부터 6씩 더해 가며 꿀벌 35마리의 다리 수까지 가려면 6을 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"꿀벌 수를 1, 2, 3, …으로 늘려 가며 다리 수를 6, 12, 18, …으로 적었어요. 6부터 6씩 더해 가며 꿀벌 35마리의 다리 수까지 가려면 6을 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["34","34번"],"explanation":["꿀벌 1마리일 때가 6이고, 하나 늘 때마다 6을 한 번 더해요.","35마리까지 가려면 35 − 1 = 34번 더해요 — 6 + 6 × 34 = 210.","35 × 6 = 210처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#4','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C2',1,'mc','auto','주 수와 날 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],false,'{"seq":4,"concept":"M5-1-u4-C2","difficulty":1,"kind":"mc","stem":"주 수와 날 수의 대응표예요. ?에 알맞은 수는 어느 것인가요?","options":[{"t":"35","correct":true},{"t":"12","mis":"M5-1-u4-X02"},{"t":"42","mis":"M5-1-u4-X09"},{"t":"34","mis":"M5-1-u4-X12"}],"explanation":["위아래 짝 1과 7을 보면 날 수는 주 수의 7배예요.","?의 위 칸은 5 — 5 × 7 = 35예요.","?에 알맞은 수는 35예요."],"asset":{"type":"numgrid","rows":[["주 수",1,2,3,4,5],["날 수",7,14,21,28,null]],"name":"대응표","q":[1,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#5','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C2',2,'mc','auto','언니 나이와 내 나이의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],false,'{"seq":5,"concept":"M5-1-u4-C2","difficulty":2,"kind":"mc","stem":"언니 나이와 내 나이의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"내 나이는 언니 나이보다 4 적다","correct":true},{"t":"내 나이는 언니 나이의 4배","mis":"M5-1-u4-X02"},{"t":"내 나이는 언니 나이보다 4 많다","mis":"M5-1-u4-X04"},{"t":"언니 나이는 내 나이보다 4 적다","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 10과 6, 11과 7, 12와 8.","내 나이는 언니 나이보다 4 적다 — 둘째 짝도 11 − 4 = 7로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["언니 나이",10,11,12,13],["내 나이",6,7,8,9]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#6','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C2',4,'sa','auto','형은 늘 나보다 2살 많아요. 두 사람의 나이를 더했더니 30살이에요. 나는 몇 살인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M5-1-u4-C2","difficulty":4,"kind":"sa","stem":"형은 늘 나보다 2살 많아요. 두 사람의 나이를 더했더니 30살이에요. 나는 몇 살인가요? 숫자로 쓰세요.","answer":["14","14살"],"explanation":["형 나이는 나 나이보다 2 많아요 — 합에서 2를 빼면 나 나이의 2배예요.","30 − 2 = 28, 28 ÷ 2 = 14예요.","나는 14살, 형은 16살 — 14 + 16 = 30으로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#7','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C3',1,'mc','auto','1주일은 7일이에요. 주 수가 정해지면 날 수는 어떻게 되나요?',ARRAY['M5-1-u4-X05','M5-1-u4-X02']::text[],false,'{"seq":7,"concept":"M5-1-u4-C3","difficulty":1,"kind":"mc","stem":"1주일은 7일이에요. 주 수가 정해지면 날 수는 어떻게 되나요?","options":[{"t":"하나로 정해진다","correct":true},{"t":"여러 가지가 될 수 있다","mis":"M5-1-u4-X05"},{"t":"주 수와 상관없이 늘 같다","mis":"M5-1-u4-X05"},{"t":"주 수보다 늘 7 많다","mis":"M5-1-u4-X02"}],"explanation":["주 하나에 날 7개씩으로 정해져 있어요.","그래서 주 수가 정해지면 날 수도 딱 하나로 정해져요.","이렇게 하나로 정해지는 두 양의 관계가 대응 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#8','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],false,'{"seq":8,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"신발 크기와 가진 공책 수","correct":true},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X13"},{"t":"문어 수와 다리 수","mis":"M5-1-u4-X13"},{"t":"젓가락 벌 수와 짝 수","mis":"M5-1-u4-X13"}],"explanation":["삼각형 수와 변의 수 · 문어 수와 다리 수 · 젓가락 벌 수와 짝 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","신발 크기와 가진 공책 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「신발 크기와 가진 공책 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#9','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C3',3,'mc','auto','두 양이 대응 관계인 것은 어느 것인가요?',ARRAY['M5-1-u4-X05']::text[],false,'{"seq":9,"concept":"M5-1-u4-C3","difficulty":3,"kind":"mc","stem":"두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"오각형 수와 꼭짓점 수","correct":true},{"t":"내 나이와 좋아하는 노래 수","mis":"M5-1-u4-X05"},{"t":"오늘 기온과 짝꿍 키","mis":"M5-1-u4-X05"},{"t":"내 키와 가진 공책 수","mis":"M5-1-u4-X05"}],"explanation":["내 나이와 좋아하는 노래 수 · 오늘 기온과 짝꿍 키 · 내 키와 가진 공책 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","오각형 수와 꼭짓점 수는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「오각형 수와 꼭짓점 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#10','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C4',1,'mc','auto','1주일은 7일이에요. 주 수를 □, 날 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],false,'{"seq":10,"concept":"M5-1-u4-C4","difficulty":1,"kind":"mc","stem":"1주일은 7일이에요. 주 수를 □, 날 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 7 = △","correct":true},{"t":"□ + 7 = △","mis":"M5-1-u4-X02"},{"t":"△ × 7 = □","mis":"M5-1-u4-X04"},{"t":"□ − 7 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(날 수)는 □(주 수)의 7배예요.","그 말을 그대로 옮기면 □ × 7 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#11','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C4',2,'mc','auto','내 나이를 □, 형 나이를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X01']::text[],false,'{"seq":11,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"내 나이를 □, 형 나이를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ + 2 = △","correct":true},{"t":"□ × 2 = △","mis":"M5-1-u4-X02"},{"t":"△ + 2 = □","mis":"M5-1-u4-X04"},{"t":"□ + 1 = △","mis":"M5-1-u4-X01"}],"explanation":["위아래 짝 8과 10, 9와 11, 10과 12를 보아요.","모든 짝에서 △는 □보다 2 많아요.","그래서 식은 □ + 2 = △예요."],"asset":{"type":"numgrid","rows":[["내 나이",8,9,10,11,12],["형 나이",10,11,12,13,14]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#12','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C4',3,'sa','auto','□ × 7 = △이고 □와 △를 더하면 64예요. □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u4-C4","difficulty":3,"kind":"sa","stem":"□ × 7 = △이고 □와 △를 더하면 64예요. □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△는 □의 7배라서 □ + △는 □의 8배예요.","64 ÷ 8 = 8이에요.","□ = 8, △ = 8 × 7 = 56 — 8 + 56 = 64로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#13','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C5',1,'mc','auto','□ × 8 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":13,"concept":"M5-1-u4-C5","difficulty":1,"kind":"mc","stem":"□ × 8 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 8 = □","correct":true},{"t":"△ × 8 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 8 = △","mis":"M5-1-u4-X08"},{"t":"△ + 8 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 8 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 8 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 8 = 24, 거꾸로 24 ÷ 8 = 3으로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#14','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C5',2,'mc','auto','□ + 9 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":14,"concept":"M5-1-u4-C5","difficulty":2,"kind":"mc","stem":"□ + 9 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ − 9 = □","correct":true},{"t":"△ + 9 = □","mis":"M5-1-u4-X08"},{"t":"□ − 9 = △","mis":"M5-1-u4-X08"},{"t":"△ × 9 = □","mis":"M5-1-u4-X02"}],"explanation":["□ + 9 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ − 9 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 + 9 = 12, 거꾸로 12 − 9 = 3으로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#15','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C5',3,'sa','auto','△ + 7 = □에서 □가 30일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M5-1-u4-C5","difficulty":3,"kind":"sa","stem":"△ + 7 = □에서 □가 30일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["△ + 7 = □는 □ − 7 = △를 거꾸로 쓴 식이에요.","□가 30이면 30 − 7 = 23이에요.","△는 23이에요 — 23 + 7 = 30으로 식에도 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#16','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C6',1,'sa','auto','□ + 12 = △에서 □가 40일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ + 12 = △에서 □가 40일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["□ 자리에 40을 넣어요.","40 + 12 = 52예요.","△는 52예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#17','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C6',1,'sa','auto','□ − 5 = △에서 △가 17일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ − 5 = △에서 △가 17일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["△ 자리에 17이 오도록 □를 찾아요 — 되돌리는 셈을 해요.","17 + 5 = 22예요.","□는 22예요. 22 − 5 = 17로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#18','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C6',2,'mc','auto','□ × 5 = △에서 □가 13일 때 △는 얼마인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X12']::text[],false,'{"seq":18,"concept":"M5-1-u4-C6","difficulty":2,"kind":"mc","stem":"□ × 5 = △에서 □가 13일 때 △는 얼마인가요?","options":[{"t":"65","correct":true},{"t":"18","mis":"M5-1-u4-X02"},{"t":"70","mis":"M5-1-u4-X12"},{"t":"60","mis":"M5-1-u4-X12"}],"explanation":["□ 자리에 13을 넣어요.","13 × 5 = 65예요.","△는 65예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#19','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C6',4,'sa','auto','□ × 4 = △이고 □ + △ = 60이에요. △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u4-C6","difficulty":4,"kind":"sa","stem":"□ × 4 = △이고 □ + △ = 60이에요. △는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["□ + △는 □의 5배예요.","□ = 60 ÷ 5 = 12예요.","△ = 12 × 4 = 48 — 묻는 것은 △라서 48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#20','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C7',1,'mc','auto','□ × 6 = △로 나타낼 수 있는 두 양은 어느 것인가요?',ARRAY['M5-1-u4-X10']::text[],false,'{"seq":20,"concept":"M5-1-u4-C7","difficulty":1,"kind":"mc","stem":"□ × 6 = △로 나타낼 수 있는 두 양은 어느 것인가요?","options":[{"t":"곤충 수와 다리 수","correct":true},{"t":"문어 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"오각형 수와 꼭짓점 수","mis":"M5-1-u4-X10"},{"t":"삼각형 수와 변의 수","mis":"M5-1-u4-X10"}],"explanation":["하나에 몇 개씩인지 보아요 — 「문어 수와 다리 수」는 하나에 8개씩 · 「오각형 수와 꼭짓점 수」는 하나에 5개씩 · 「삼각형 수와 변의 수」는 하나에 3개씩.","「곤충 수와 다리 수」는 하나에 6개씩이에요.","그래서 □ × 6 = △로 나타낼 수 있는 것은 「곤충 수와 다리 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#21','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C7',2,'sa','auto','문어 한 마리의 다리는 8개예요. 문어의 다리가 모두 72개라면 문어는 몇 마리인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u4-C7","difficulty":2,"kind":"sa","stem":"문어 한 마리의 다리는 8개예요. 문어의 다리가 모두 72개라면 문어는 몇 마리인가요? 숫자로 쓰세요.","answer":["9","9마리"],"explanation":["다리 수는 문어 수의 8배예요.","거꾸로 가려면 8로 나누어요 — 72 ÷ 8 = 9.","문어는 9마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#22','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C7',3,'sa','auto','다음 중 □ × 3 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 삼각형 수와 꼭짓점 수 / 자전거 수와 바퀴 수 / 세발자전거 수와 바퀴 수 / 삼각형 수와 변의 수 / 곤충 수와 다리 수','{}'::text[],false,'{"seq":22,"concept":"M5-1-u4-C7","difficulty":3,"kind":"sa","stem":"다음 중 □ × 3 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 삼각형 수와 꼭짓점 수 / 자전거 수와 바퀴 수 / 세발자전거 수와 바퀴 수 / 삼각형 수와 변의 수 / 곤충 수와 다리 수","answer":["3","3가지"],"explanation":["하나에 몇 개씩인지 보아요 — 삼각형 수와 꼭짓점 수 3 · 자전거 수와 바퀴 수 2 · 세발자전거 수와 바퀴 수 3 · 삼각형 수와 변의 수 3 · 곤충 수와 다리 수 6.","하나에 3개씩인 것은 「삼각형 수와 꼭짓점 수」, 「세발자전거 수와 바퀴 수」, 「삼각형 수와 변의 수」예요.","모두 3가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#23','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C8',2,'mc','auto','선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 살 수 있는 선물 수를 구하는 데 필요 없는 정보는 어느 것인가요?',ARRAY['M5-1-u4-X11']::text[],false,'{"seq":23,"concept":"M5-1-u4-C8","difficulty":2,"kind":"mc","stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 살 수 있는 선물 수를 구하는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"포장지의 색 4가지","correct":true},{"t":"선물 하나의 값","mis":"M5-1-u4-X11"},{"t":"가진 돈","mis":"M5-1-u4-X11"},{"t":"선물 수와 값 사이의 관계","mis":"M5-1-u4-X11"}],"explanation":["살 수 있는 선물 수를 구하려면 선물 하나의 값과 가진 돈만 있으면 돼요.","포장지의 색 4가지는 묻는 것과 이어지지 않아요.","그래서 필요 없는 정보는 「포장지의 색 4가지」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#24','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C8',3,'sa','auto','선물 하나는 2500원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 24000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u4-C8","difficulty":3,"kind":"sa","stem":"선물 하나는 2500원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 24000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["8","8명"],"explanation":["한 사람에게 드는 돈은 2500 + 500 = 3000원 — □ × 3000 = △예요.","△가 24000이니 24000 ÷ 3000 = 8이에요.","친구는 8명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_c#25','math',5,1,'u4','','g5_1_math_u4_review_c','unit_review','M5-1-u4-C8',4,'sa','auto','가진 돈은 40000원이에요. 친구마다 2500원짜리 선물과 500원짜리 포장을 하나씩 샀더니 10000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u4-C8","difficulty":4,"kind":"sa","stem":"가진 돈은 40000원이에요. 친구마다 2500원짜리 선물과 500원짜리 포장을 하나씩 샀더니 10000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["10","10명"],"explanation":["쓴 돈은 40000 − 10000 = 30000원이에요.","한 사람에게 2500 + 500 = 3000원 — □ × 3000 = 30000이에요.","30000 ÷ 3000 = 10 — 친구는 10명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#1','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C1',1,'sa','auto','문어 한 마리의 다리는 8개예요. 문어 6마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-1-u4-C1","difficulty":1,"kind":"sa","stem":"문어 한 마리의 다리는 8개예요. 문어 6마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["48","48개"],"explanation":["문어가 하나 늘 때마다 다리 수는 8씩 늘어요 — 다리 수는 문어 수의 8배예요.","6 × 8 = 48이에요.","문어 6마리의 다리는 48개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#2','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C1',2,'mc','auto','자동차 한 대에는 바퀴가 4개 있어요. 자동차 150대의 바퀴는 모두 몇 개인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X09','M5-1-u4-X12']::text[],false,'{"seq":2,"concept":"M5-1-u4-C1","difficulty":2,"kind":"mc","stem":"자동차 한 대에는 바퀴가 4개 있어요. 자동차 150대의 바퀴는 모두 몇 개인가요?","options":[{"t":"600개","correct":true},{"t":"154개","mis":"M5-1-u4-X02"},{"t":"604개","mis":"M5-1-u4-X09"},{"t":"6000개","mis":"M5-1-u4-X12"}],"explanation":["바퀴 수는 자동차 수의 4배예요 — 표를 150칸까지 그리지 않아도 돼요.","150 × 4 = 600이에요.","자동차 150대의 바퀴는 600개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#3','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C1',3,'sa','auto','꿀벌 수를 1, 2, 3, …으로 늘려 가며 날개 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 꿀벌 90마리의 날개 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u4-C1","difficulty":3,"kind":"sa","stem":"꿀벌 수를 1, 2, 3, …으로 늘려 가며 날개 수를 4, 8, 12, …으로 적었어요. 4부터 4씩 더해 가며 꿀벌 90마리의 날개 수까지 가려면 4를 몇 번 더해야 하나요? 숫자로 쓰세요.","answer":["89","89번"],"explanation":["꿀벌 1마리일 때가 4이고, 하나 늘 때마다 4를 한 번 더해요.","90마리까지 가려면 90 − 1 = 89번 더해요 — 4 + 4 × 89 = 360.","90 × 4 = 360처럼 짝의 규칙으로 곱하면 한 번에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#4','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C2',1,'mc','auto','내 나이와 형 나이의 대응표예요. ?에 알맞은 수는 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04','M5-1-u4-X12']::text[],false,'{"seq":4,"concept":"M5-1-u4-C2","difficulty":1,"kind":"mc","stem":"내 나이와 형 나이의 대응표예요. ?에 알맞은 수는 어느 것인가요?","options":[{"t":"13","correct":true},{"t":"22","mis":"M5-1-u4-X02"},{"t":"9","mis":"M5-1-u4-X04"},{"t":"14","mis":"M5-1-u4-X12"}],"explanation":["위아래 짝 8과 10을 보면 형 나이는 내 나이보다 2 많아요.","?의 위 칸은 11 — 11 + 2 = 13이에요.","?에 알맞은 수는 13이에요."],"asset":{"type":"numgrid","rows":[["내 나이",8,9,10,11,12],["형 나이",10,11,12,null,14]],"name":"대응표","q":[1,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#5','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C2',2,'mc','auto','내 나이와 아빠 나이의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],false,'{"seq":5,"concept":"M5-1-u4-C2","difficulty":2,"kind":"mc","stem":"내 나이와 아빠 나이의 대응표예요. 두 양 사이의 대응 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"아빠 나이는 내 나이보다 29 많다","correct":true},{"t":"아빠 나이는 내 나이의 29배","mis":"M5-1-u4-X02"},{"t":"아빠 나이는 내 나이보다 29 적다","mis":"M5-1-u4-X04"},{"t":"내 나이는 아빠 나이보다 29 많다","mis":"M5-1-u4-X04"}],"explanation":["표를 위아래로 짝지어 읽어요 — 9와 38, 10과 39, 11과 40.","아빠 나이는 내 나이보다 29 많다 — 둘째 짝도 10 + 29 = 39로 맞아요.","가로 한 줄만 보면 「몇씩 늘어난다」까지예요. 대응 관계는 위아래 짝에서 찾아요."],"asset":{"type":"numgrid","rows":[["내 나이",9,10,11,12],["아빠 나이",38,39,40,41]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#6','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C2',4,'sa','auto','누나는 늘 동생보다 5살 많아요. 두 사람의 나이를 더했더니 29살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M5-1-u4-C2","difficulty":4,"kind":"sa","stem":"누나는 늘 동생보다 5살 많아요. 두 사람의 나이를 더했더니 29살이에요. 동생은 몇 살인가요? 숫자로 쓰세요.","answer":["12","12살"],"explanation":["누나 나이는 동생 나이보다 5 많아요 — 합에서 5를 빼면 동생 나이의 2배예요.","29 − 5 = 24, 24 ÷ 2 = 12예요.","동생은 12살, 누나는 17살 — 12 + 17 = 29로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#7','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C3',1,'mc','auto','삼각형 하나의 변은 3개예요. 삼각형 수가 정해지면 변 수는 어떻게 되나요?',ARRAY['M5-1-u4-X05','M5-1-u4-X02']::text[],false,'{"seq":7,"concept":"M5-1-u4-C3","difficulty":1,"kind":"mc","stem":"삼각형 하나의 변은 3개예요. 삼각형 수가 정해지면 변 수는 어떻게 되나요?","options":[{"t":"하나로 정해진다","correct":true},{"t":"여러 가지가 될 수 있다","mis":"M5-1-u4-X05"},{"t":"삼각형 수와 상관없이 늘 같다","mis":"M5-1-u4-X05"},{"t":"삼각형 수보다 늘 3 많다","mis":"M5-1-u4-X02"}],"explanation":["삼각형 하나에 변 3개씩으로 정해져 있어요.","그래서 삼각형 수가 정해지면 변 수도 딱 하나로 정해져요.","이렇게 하나로 정해지는 두 양의 관계가 대응 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#8','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C3',2,'mc','auto','두 양이 대응 관계가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u4-X13']::text[],false,'{"seq":8,"concept":"M5-1-u4-C3","difficulty":2,"kind":"mc","stem":"두 양이 대응 관계가 아닌 것은 어느 것인가요?","options":[{"t":"내 몸무게와 좋아하는 노래 수","correct":true},{"t":"사람 수와 눈의 수","mis":"M5-1-u4-X13"},{"t":"자동차 수와 바퀴 수","mis":"M5-1-u4-X13"},{"t":"곤충 수와 다리 수","mis":"M5-1-u4-X13"}],"explanation":["사람 수와 눈의 수 · 자동차 수와 바퀴 수 · 곤충 수와 다리 수 — 한 양이 정해지면 다른 양이 하나로 정해져요.","내 몸무게와 좋아하는 노래 수는 한 쪽이 정해져도 다른 쪽이 정해지지 않아요.","그래서 대응 관계가 아닌 것은 「내 몸무게와 좋아하는 노래 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#9','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C3',3,'mc','auto','두 양이 대응 관계인 것은 어느 것인가요?',ARRAY['M5-1-u4-X05']::text[],false,'{"seq":9,"concept":"M5-1-u4-C3","difficulty":3,"kind":"mc","stem":"두 양이 대응 관계인 것은 어느 것인가요?","options":[{"t":"상자 수와 공책 수(한 상자에 12권)","correct":true},{"t":"오늘 날씨와 반 친구 수","mis":"M5-1-u4-X05"},{"t":"내 키와 좋아하는 운동 수","mis":"M5-1-u4-X05"},{"t":"신발 크기와 가진 책 수","mis":"M5-1-u4-X05"}],"explanation":["오늘 날씨와 반 친구 수 · 내 키와 좋아하는 운동 수 · 신발 크기와 가진 책 수는 한 쪽이 정해져도 다른 쪽이 하나로 정해지지 않아요.","상자 수와 공책 수(한 상자에 12권)는 한 쪽이 정해지면 다른 쪽도 하나로 정해져요.","그래서 대응 관계인 것은 「상자 수와 공책 수(한 상자에 12권)」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#10','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C4',1,'mc','auto','모둠 하나에 4명씩 앉아요. 모둠 수를 □, 사람 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X02','M5-1-u4-X04']::text[],false,'{"seq":10,"concept":"M5-1-u4-C4","difficulty":1,"kind":"mc","stem":"모둠 하나에 4명씩 앉아요. 모둠 수를 □, 사람 수를 △라고 할 때 두 양 사이의 대응 관계를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"□ × 4 = △","correct":true},{"t":"□ + 4 = △","mis":"M5-1-u4-X02"},{"t":"△ × 4 = □","mis":"M5-1-u4-X04"},{"t":"□ − 4 = △","mis":"M5-1-u4-X02"}],"explanation":["말로 먼저 해요 — △(사람 수)는 □(모둠 수)의 4배예요.","그 말을 그대로 옮기면 □ × 4 = △예요.","□와 △의 자리를 바꾸거나 곱셈을 덧셈으로 바꾸면 다른 관계가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#11','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C4',2,'mc','auto','꿀벌 수를 □, 다리 수를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u4-X03','M5-1-u4-X04','M5-1-u4-X01']::text[],false,'{"seq":11,"concept":"M5-1-u4-C4","difficulty":2,"kind":"mc","stem":"꿀벌 수를 □, 다리 수를 △라고 할 때 표의 대응 관계를 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"□ × 6 = △","correct":true},{"t":"□ + 5 = △","mis":"M5-1-u4-X03"},{"t":"△ × 6 = □","mis":"M5-1-u4-X04"},{"t":"□ + 6 = △","mis":"M5-1-u4-X01"}],"explanation":["위아래 짝 1과 6, 2와 12, 3과 18을 보아요.","모든 짝에서 △는 □의 6배예요.","그래서 식은 □ × 6 = △예요."],"asset":{"type":"numgrid","rows":[["꿀벌 수",1,2,3,4,5],["다리 수",6,12,18,24,30]],"name":"대응표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#12','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C4',3,'sa','auto','□ × 4 = △이고 □와 △를 더하면 75예요. □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-1-u4-C4","difficulty":3,"kind":"sa","stem":"□ × 4 = △이고 □와 △를 더하면 75예요. □는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["△는 □의 4배라서 □ + △는 □의 5배예요.","75 ÷ 5 = 15예요.","□ = 15, △ = 15 × 4 = 60 — 15 + 60 = 75로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#13','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C5',1,'mc','auto','□ × 3 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X04','M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":13,"concept":"M5-1-u4-C5","difficulty":1,"kind":"mc","stem":"□ × 3 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ ÷ 3 = □","correct":true},{"t":"△ × 3 = □","mis":"M5-1-u4-X04"},{"t":"□ ÷ 3 = △","mis":"M5-1-u4-X08"},{"t":"△ + 3 = □","mis":"M5-1-u4-X02"}],"explanation":["□ × 3 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ ÷ 3 = □ — 셈이 거꾸로 바뀌어요.","□ = 3이면 3 × 3 = 9, 거꾸로 9 ÷ 3 = 3으로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#14','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C5',2,'mc','auto','□ − 6 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?',ARRAY['M5-1-u4-X08','M5-1-u4-X02']::text[],false,'{"seq":14,"concept":"M5-1-u4-C5","difficulty":2,"kind":"mc","stem":"□ − 6 = △와 같은 대응 관계를 나타낸 식은 어느 것인가요?","options":[{"t":"△ + 6 = □","correct":true},{"t":"△ − 6 = □","mis":"M5-1-u4-X08"},{"t":"□ + 6 = △","mis":"M5-1-u4-X08"},{"t":"△ ÷ 6 = □","mis":"M5-1-u4-X02"}],"explanation":["□ − 6 = △는 □에서 △로 가는 식이에요.","△에서 □로 되돌아오면 △ + 6 = □ — 셈이 거꾸로 바뀌어요.","□ = 11이면 11 − 6 = 5, 거꾸로 5 + 6 = 11로 같은 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#15','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C5',3,'sa','auto','△ − 15 = □에서 □가 40일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M5-1-u4-C5","difficulty":3,"kind":"sa","stem":"△ − 15 = □에서 □가 40일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["△ − 15 = □는 □ + 15 = △를 거꾸로 쓴 식이에요.","□가 40이면 40 + 15 = 55예요.","△는 55예요 — 55 − 15 = 40으로 식에도 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#16','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C6',1,'sa','auto','□ × 9 = △에서 □가 6일 때 △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ × 9 = △에서 □가 6일 때 △는 얼마인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["□ 자리에 6을 넣어요.","6 × 9 = 54예요.","△는 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#17','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C6',1,'sa','auto','□ × 8 = △에서 △가 64일 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u4-C6","difficulty":1,"kind":"sa","stem":"□ × 8 = △에서 △가 64일 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["△ 자리에 64가 오도록 □를 찾아요 — 되돌리는 셈을 해요.","64 ÷ 8 = 8이에요.","□는 8이에요. 8 × 8 = 64로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#18','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C6',2,'mc','auto','□ − 8 = △에서 □가 30일 때 △는 얼마인가요?',ARRAY['M5-1-u4-X07','M5-1-u4-X13','M5-1-u4-X12']::text[],false,'{"seq":18,"concept":"M5-1-u4-C6","difficulty":2,"kind":"mc","stem":"□ − 8 = △에서 □가 30일 때 △는 얼마인가요?","options":[{"t":"22","correct":true},{"t":"38","mis":"M5-1-u4-X07"},{"t":"30","mis":"M5-1-u4-X13"},{"t":"21","mis":"M5-1-u4-X12"}],"explanation":["□ 자리에 30을 넣어요.","30 − 8 = 22예요.","△는 22예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#19','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C6',4,'sa','auto','□ × 2 = △이고 □ + △ = 99예요. △는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u4-C6","difficulty":4,"kind":"sa","stem":"□ × 2 = △이고 □ + △ = 99예요. △는 얼마인가요? 숫자로 쓰세요.","answer":["66"],"explanation":["□ + △는 □의 3배예요.","□ = 99 ÷ 3 = 33이에요.","△ = 33 × 2 = 66 — 묻는 것은 △라서 66이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#20','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C7',1,'mc','auto','□ × 8 = △로 나타낼 수 있는 두 양은 어느 것인가요?',ARRAY['M5-1-u4-X10']::text[],false,'{"seq":20,"concept":"M5-1-u4-C7","difficulty":1,"kind":"mc","stem":"□ × 8 = △로 나타낼 수 있는 두 양은 어느 것인가요?","options":[{"t":"문어 수와 다리 수","correct":true},{"t":"곤충 수와 다리 수","mis":"M5-1-u4-X10"},{"t":"주 수와 날 수","mis":"M5-1-u4-X10"},{"t":"사각형 수와 변의 수","mis":"M5-1-u4-X10"}],"explanation":["하나에 몇 개씩인지 보아요 — 「곤충 수와 다리 수」는 하나에 6개씩 · 「주 수와 날 수」는 하나에 7개씩 · 「사각형 수와 변의 수」는 하나에 4개씩.","「문어 수와 다리 수」는 하나에 8개씩이에요.","그래서 □ × 8 = △로 나타낼 수 있는 것은 「문어 수와 다리 수」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#21','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C7',2,'sa','auto','탁자 하나에 의자가 6개씩 놓여 있어요. 의자가 모두 90개라면 탁자는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u4-C7","difficulty":2,"kind":"sa","stem":"탁자 하나에 의자가 6개씩 놓여 있어요. 의자가 모두 90개라면 탁자는 몇 개인가요? 숫자로 쓰세요.","answer":["15","15개"],"explanation":["의자 수는 탁자 수의 6배예요.","거꾸로 가려면 6으로 나누어요 — 90 ÷ 6 = 15.","탁자는 15개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#22','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C7',3,'sa','auto','다음 중 □ × 6 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 곤충 수와 다리 수 / 문어 수와 다리 수 / 주 수와 날 수 / 사각형 수와 변의 수 / 오각형 수와 꼭짓점 수','{}'::text[],false,'{"seq":22,"concept":"M5-1-u4-C7","difficulty":3,"kind":"sa","stem":"다음 중 □ × 6 = △로 나타낼 수 있는 두 양은 모두 몇 가지인가요? 숫자로 쓰세요. — 곤충 수와 다리 수 / 문어 수와 다리 수 / 주 수와 날 수 / 사각형 수와 변의 수 / 오각형 수와 꼭짓점 수","answer":["1","1가지"],"explanation":["하나에 몇 개씩인지 보아요 — 곤충 수와 다리 수 6 · 문어 수와 다리 수 8 · 주 수와 날 수 7 · 사각형 수와 변의 수 4 · 오각형 수와 꼭짓점 수 5.","하나에 6개씩인 것은 「곤충 수와 다리 수」예요.","모두 1가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#23','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C8',2,'mc','auto','선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 살 수 있는 선물 수를 구하는 데 필요 없는 정보는 어느 것인가요?',ARRAY['M5-1-u4-X11']::text[],false,'{"seq":23,"concept":"M5-1-u4-C8","difficulty":2,"kind":"mc","stem":"선물 하나는 3000원, 가게까지 걸어서 15분, 포장지는 4가지 색, 가진 돈은 50000원이에요. 살 수 있는 선물 수를 구하는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"가게까지 걸어서 15분","correct":true},{"t":"선물 하나의 값","mis":"M5-1-u4-X11"},{"t":"가진 돈","mis":"M5-1-u4-X11"},{"t":"선물 수와 값 사이의 관계","mis":"M5-1-u4-X11"}],"explanation":["살 수 있는 선물 수를 구하려면 선물 하나의 값과 가진 돈만 있으면 돼요.","가게까지 걸어서 15분은 묻는 것과 이어지지 않아요.","그래서 필요 없는 정보는 「가게까지 걸어서 15분」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#24','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C8',3,'sa','auto','선물 하나는 4000원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 45000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u4-C8","difficulty":3,"kind":"sa","stem":"선물 하나는 4000원, 포장 하나는 500원이에요. 포장한 선물을 친구에게 하나씩 주는 데 모두 45000원이 들었어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["10","10명"],"explanation":["한 사람에게 드는 돈은 4000 + 500 = 4500원 — □ × 4500 = △예요.","△가 45000이니 45000 ÷ 4500 = 10이에요.","친구는 10명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u4_review_d#25','math',5,1,'u4','','g5_1_math_u4_review_d','unit_review','M5-1-u4-C8',4,'sa','auto','가진 돈은 50000원이에요. 친구마다 4000원짜리 선물과 1000원짜리 포장을 하나씩 샀더니 15000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u4-C8","difficulty":4,"kind":"sa","stem":"가진 돈은 50000원이에요. 친구마다 4000원짜리 선물과 1000원짜리 포장을 하나씩 샀더니 15000원이 남았어요. 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["7","7명"],"explanation":["쓴 돈은 50000 − 15000 = 35000원이에요.","한 사람에게 4000 + 1000 = 5000원 — □ × 5000 = 35000이에요.","35000 ÷ 5000 = 7 — 친구는 7명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
